def _load_premium_map() -> None:
    """Load emoji->id mapping. Uses WORKING_IDS pool (bot-accessible) cycle per unique emoji."""
    global _PREMIUM_MAP, _PREMIUM_KEYS, _PREMIUM_MAP_LOADED
    if _PREMIUM_MAP_LOADED:
        return
    _PREMIUM_MAP_LOADED = True
    try:
        p = Path(__file__).resolve().with_name("premiumemoji.txt")
        if not p.is_file():
            return
        for line in p.read_text(encoding="utf-8", errors="ignore").splitlines():
            m = re.match(r"^\s*\d+\.\s+(\d+)\s+\[(.+?)\]", line)
            if m:
                _cid, e = m.group(1), m.group(2).strip()
                if e and e not in _PREMIUM_MAP:
                    # Use cycling pool ID instead of file ID
                    _PREMIUM_MAP[e] = _WORKING_IDS[_MAP_IDX[0] % len(_WORKING_IDS)]
                    _MAP_IDX[0] += 1
        # Merge custom file if present
        try:
            _custom_p = Path(__file__).resolve().with_name("premiumemoji_custom.txt")
            if _custom_p.is_file():
                for line in _custom_p.read_text(encoding="utf-8", errors="ignore").splitlines():
                    line = line.strip()
                    if not line or line.startswith("#"):
                        continue
                    m = re.match(r"^(\S+)\s*[—\-:]+\s*(\d{5,30})\s*$", line)
                    if m:
                        e, cid = m.group(1), m.group(2)
                        if e and e not in _PREMIUM_MAP:
                            _PREMIUM_MAP[e] = cid
                        continue
                    m = re.match(r"^(\d{5,30})\s+\[(.+?)\]\s*$", line)
                    if m:
                        cid, e = m.group(1), m.group(2)
                        if e and e not in _PREMIUM_MAP:
                            _PREMIUM_MAP[e] = cid
                        continue
                    m = re.match(r"^(\d{5,30})\s+(\S+)\s*$", line)
                    if m:
                        cid, e = m.group(1), m.group(2)
                        if e and e not in _PREMIUM_MAP:
                            _PREMIUM_MAP[e] = cid
        except Exception:
            pass
        _PREMIUM_KEYS = sorted(_PREMIUM_MAP.keys(), key=len, reverse=True)
    except Exception:
        pass


def _load_premium_pool_ordered():
    pool = []
    seen = set()
    try:
        p = Path(__file__).resolve().with_name("premiumemoji.txt")
        if not p.is_file():
            return pool
        for line in p.read_text(encoding="utf-8", errors="ignore").splitlines():
            m = re.match(r"^\s*\d+\.\s+(\d+)\s+\[(.+?)\]", line)
            if m:
                cid, e = m.group(1), m.group(2).strip()
                if e and cid not in seen:
                    pool.append((e, cid))
                    seen.add(cid)
    except Exception:
        pass
    return pool


