def _is_primary_emoji(cp: int) -> bool:
    if cp in (0xFE0F, 0x200D, 0x20E3):
        return False
    return any(lo <= cp <= hi for lo, hi in _EMOJI_RANGES)


def _is_modifier(cp: int) -> bool:
    if 0xFE00 <= cp <= 0xFE0F: return True
    if cp == 0x200D: return True
    if cp == 0x20E3: return True
    if 0x1F3FB <= cp <= 0x1F3FF: return True
    return False


def _get_substitute(emoji: str):
    global _SUBSTITUTE_IDX
    if not _SUBSTITUTE_POOL:
        return None
    if emoji in _AUTO_SUBSTITUTE:
        return _AUTO_SUBSTITUTE[emoji]
    used = set(_AUTO_SUBSTITUTE.values())
    attempts = 0
    while attempts < len(_SUBSTITUTE_POOL):
        cand = _SUBSTITUTE_POOL[_SUBSTITUTE_IDX % len(_SUBSTITUTE_POOL)]
        _SUBSTITUTE_IDX = (_SUBSTITUTE_IDX + 1) % len(_SUBSTITUTE_POOL)
        attempts += 1
        if cand not in used:
            _AUTO_SUBSTITUTE[emoji] = cand
            return cand
    return None


def premiumize(text):
    """Runtime emoji -> <tg-emoji>. Skips already-tagged portions, tags the rest."""
    global _SUBSTITUTE_POOL
    if not text or not isinstance(text, str):
        return text or ""
    _load_premium_map()
    if not _SUBSTITUTE_POOL:
        _SUBSTITUTE_POOL = [e for e, _ in _load_premium_pool_ordered()]
    out = []
    i, n = 0, len(text)
    while i < n:
        # --- skip already-tagged portion ---
        if text.startswith("<tg-emoji", i):
            close = text.find("</tg-emoji>", i)
            if close != -1:
                out.append(text[i:close + 11])
                i = close + 11
                continue
            # malformed tag — skip past opening
            gt = text.find(">", i)
            if gt != -1:
                out.append(text[i:gt + 1])
                i = gt + 1
                continue
        # --- special override ---
        sp_hit = None
        for sp in _SPECIAL_OVERRIDE:
            if text.startswith(sp, i):
                sp_hit = sp
                break
        if sp_hit:
            pe, pid = _SPECIAL_OVERRIDE[sp_hit]
            out.append('<tg-emoji emoji-id="' + pid + '">' + pe + '</tg-emoji>')
            i += len(sp_hit)
            while i < n and _is_modifier(ord(text[i])):
                i += 1
            continue
        # --- premium file match ---
        matched = False
        for e in _PREMIUM_KEYS:
            if text.startswith(e, i):
                cid = _PREMIUM_MAP[e]
                out.append('<tg-emoji emoji-id="' + cid + '">' + e + '</tg-emoji>')
                i += len(e)
                matched = True
                break
        if matched:
            continue
        # --- non-premium emoji: substitute from pool ---
        cp = ord(text[i])
        if _is_primary_emoji(cp):
            sub = _get_substitute(text[i])
            if sub:
                cid = _PREMIUM_MAP.get(sub)
                if cid:
                    out.append('<tg-emoji emoji-id="' + cid + '">' + sub + '</tg-emoji>')
            i += 1
            while i < n and _is_modifier(ord(text[i])):
                i += 1
            continue
        if _is_modifier(cp):
            i += 1
            continue
        out.append(text[i])
        i += 1
    return "".join(out)

