# Emoji detection ranges (broad — covers most Unicode emoji)
_EMOJI_RANGES_DETECT = [
    (0x1F300, 0x1F5FF), (0x1F600, 0x1F64F), (0x1F680, 0x1F6FF),
    (0x1F700, 0x1F77F), (0x1F780, 0x1F7FF), (0x1F800, 0x1F8FF),
    (0x1F900, 0x1F9FF), (0x1FA00, 0x1FA6F), (0x1FA70, 0x1FAFF),
    (0x2600, 0x26FF), (0x2700, 0x27BF), (0x2300, 0x23FF),
    (0x2B00, 0x2BFF), (0x25A0, 0x25FF), (0x2900, 0x297F),
    (0x2122, 0x2122), (0x2139, 0x2139),
]


def _has_emoji(text: str) -> bool:
    if not text:
        return False
    for ch in text:
        cp = ord(ch)
        for lo, hi in _EMOJI_RANGES_DETECT:
            if lo <= cp <= hi:
                return True
    return False


def _next_inject_emoji() -> str:
    e = _EMOJI_INJECT_POOL[_EMOJI_INJECT_IDX[0] % len(_EMOJI_INJECT_POOL)]
    _EMOJI_INJECT_IDX[0] += 1
    return e


