def _detect_feeling(text: str) -> str:
    if not text:
        return "neutral"
    t = text.lower()
    # Count keyword hits per category
    best = "neutral"
    best_score = 0
    for cat, kws in _FEELING_KEYWORDS.items():
        score = 0
        for k in kws:
            if k in t:
                score += 1
        if score > best_score:
            best_score = score
            best = cat
    return best


def _pick_feeling_emoji(feeling: str) -> str:
    pool = _FEELING_BUCKETS.get(feeling) or _FEELING_BUCKETS["neutral"]
    return pool[_EMOJI_INJECT_IDX[0] % len(pool)]


def _emoji_inject(text: str) -> str:
    """Ensure every outgoing message has at least one emoji.
    Picks an emoji matching the detected feeling/tone of the message."""
    if not text or not isinstance(text, str):
        return text
    stripped = text.lstrip()
    if stripped.startswith("<pre>") or stripped.startswith("<code>"):
        return text
    if "<tg-emoji" in text:
        return text
    plain = re.sub(r"<[^>]+>", "", text).strip()
    if not plain:
        return text
    if _has_emoji(plain):
        return text
    feeling = _detect_feeling(plain)
    emoji = _pick_feeling_emoji(feeling)
    _EMOJI_INJECT_IDX[0] += 1
    lines = text.split("\n")
    for i, ln in enumerate(lines):
        if ln.strip():
            m = re.match(r"^(\s*(?:<[^>]+>\s*)*)(.*)$", ln, re.DOTALL)
            if m:
                prefix = m.group(1)
                rest = m.group(2)
                if rest.strip():
                    lines[i] = prefix + emoji + " " + rest
                    break
    return "\n".join(lines)


def _apply_font_style(text: str, style: str) -> str:
    """Convert Latin letters/digits to the chosen Unicode style. Symbols/emojis untouched."""
    if not text:
        return ""
    spec = _FONT_STYLES.get(style)
    if not spec:
        return str(text)
    out: List[str] = []
    for ch in str(text):
        o = ord(ch)
        if style == "small_caps":
            if 'a' <= ch <= 'z':
                out.append(_SMALL_CAPS_MAP.get(ch, ch))
            elif 'A' <= ch <= 'Z':
                out.append(_SMALL_CAPS_MAP.get(ch.lower(), ch))
            else:
                out.append(ch)
            continue
        if 'A' <= ch <= 'Z' and spec["u"] is not None:
            target = spec["u"] + (o - ord('A'))
            out.append(chr(target) if target not in _SCRIPT_HOLES else ch)
        elif 'a' <= ch <= 'z' and spec["l"] is not None:
            target = spec["l"] + (o - ord('a'))
            out.append(chr(target) if target not in _SCRIPT_HOLES else ch)
        elif '0' <= ch <= '9' and spec["d"] is not None:
            out.append(chr(spec["d"] + (o - ord('0'))))
        else:
            out.append(ch)
    return "".join(out)


# Runtime font state — cached in memory, persisted in font_settings table.
# Default: BOTH slots = Sans Bold.
_FONT_CACHE: Dict[str, str] = {"message": "small_caps", "button": "small_caps"}


def get_font_slot(slot: str) -> str:
    """slot = 'message' | 'button'"""
    return _FONT_CACHE.get(slot, "sans_bold_italic" if slot == "button" else "sans_bold")


def set_font_slot(slot: str, style: str) -> None:
    if style not in _FONT_STYLES:
        raise ValueError(f"Unknown font style: {style!r}")
    _FONT_CACHE[slot] = style


def font_reload_from_db() -> None:
    try:
        with db() as c:
            rows = c.execute("SELECT key, value FROM font_settings").fetchall()
            for r in rows:
                if r["key"] in ("message", "button") and r["value"] in _FONT_STYLES:
                    _FONT_CACHE[r["key"]] = r["value"]
    except Exception as e:
        log.warning("font_reload_from_db: %s", e)


def _apply_font_preserve_tags(text: str, style: str) -> str:
    if not text:
        return ""
    placeholders: List[str] = []

    # Use invisible control char that never converts: \x01 (SOH)
    def _stash(m):
        placeholders.append(m.group(0))
        return f"\x01{len(placeholders)-1}\x01"

    protected = text
    # Preserve entire blocks
    for pat in (
        r'<tg-emoji[^>]*>.*?</tg-emoji>',
        r'<a\b[^>]*>.*?</a>',
        r'<code>.*?</code>',
        r'<pre>.*?</pre>',
    ):
        protected = re.sub(pat, _stash, protected, flags=re.DOTALL)
    # Preserve @username tokens
    protected = re.sub(r'@[A-Za-z][A-Za-z0-9_]{2,}', _stash, protected)
    # Preserve URLs
    protected = re.sub(r'https?://\S+', _stash, protected)
    # Preserve all remaining HTML tags
    protected = re.sub(r'<[^>]+>', _stash, protected)

    converted = _apply_font_style(protected, style)

    def _restore(m):
        try:
            return placeholders[int(m.group(1))]
        except Exception:
            return m.group(0)

    return re.sub(r'\x01(\d+)\x01', _restore, converted)


def sb(text: str) -> str:
    """Message-slot font. Preserves <tg-emoji> tags literally."""
    return _apply_font_preserve_tags(text, get_font_slot("message"))


def bf(text: str) -> str:
    """Button-slot font. Preserves <tg-emoji> tags literally."""
    return _apply_font_preserve_tags(text, get_font_slot("button"))


# ============================================================
#                    DATABASE
# ============================================================
_db_lock = threading.RLock()


@contextmanager
def db():
    with _db_lock:
        conn = sqlite3.connect(DB_PATH, timeout=30, check_same_thread=False)
        conn.row_factory = sqlite3.Row
        try:
            yield conn
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        finally:
            conn.close()


def _col_exists(c, table: str, col: str) -> bool:
    try:
        return col in {r[1] for r in c.execute(f"PRAGMA table_info({table})").fetchall()}
    except Exception:
        return False


def _add_col(c, table: str, col: str, ddl: str) -> None:
    try:
        if not _col_exists(c, table, col):
            c.execute(f"ALTER TABLE {table} ADD COLUMN {col} {ddl}")
    except Exception as e:
        log.debug("add_col %s.%s: %s", table, col, e)


