def init_db() -> None:
    with db() as c:
        for stmt in SCHEMA_STATEMENTS:
            try:
                c.execute(stmt)
            except Exception as e:
                log.warning("schema stmt: %s | %s", e, stmt[:80])
        for tbl, col, ddl in [
            ("economy", "bank", "INTEGER DEFAULT 0"),
            ("economy", "bank_last_interest", "TEXT"),
            ("economy", "streak", "INTEGER DEFAULT 0"),
            ("economy", "streak_last", "TEXT"),
            ("channel_post_limits", "window_hours", "INTEGER DEFAULT 24"),
            ("channel_auto_reaction", "reaction_mode", "TEXT DEFAULT 'fixed'"),
            ("channel_auto_reaction", "reaction_pool", "TEXT DEFAULT ''"),
            ("channel_post_counts", "window_start", "TEXT"),
            ("operators", "banner_caption", "TEXT DEFAULT ''"),
            ("users", "last_name", "TEXT"),
            ("users", "first_seen", "TEXT"),
            ("users", "status", "TEXT DEFAULT 'active'"),
            ("managed_channels", "added_by_user_id", "INTEGER"),
            ("managed_channels", "added_by_first_name", "TEXT"),
            ("managed_channels", "added_by_last_name", "TEXT"),
            ("managed_channels", "added_by_username", "TEXT"),
            ("managed_channels", "updated_at", "TEXT"),
            ("managed_channels", "status", "TEXT DEFAULT 'active'"),
            ("managed_chats", "added_by_user_id", "INTEGER"),
            ("managed_chats", "added_by_first_name", "TEXT"),
            ("managed_chats", "added_by_last_name", "TEXT"),
            ("managed_chats", "added_by_username", "TEXT"),
            ("managed_chats", "added_at", "TEXT"),
            ("managed_chats", "updated_at", "TEXT"),
            ("managed_chats", "status", "TEXT DEFAULT 'active'"),
            ("force_join", "enabled", "INTEGER DEFAULT 1"),
            ("force_join", "display_order", "INTEGER DEFAULT 0"),
            ("force_join", "custom_button_name", "TEXT"),
            ("force_join", "join_url", "TEXT"),
            ("force_join", "channel_id", "INTEGER"),
            ("force_join", "is_private", "INTEGER DEFAULT 0"),
            ("force_join", "verify_message", "TEXT"),
            ("force_join", "custom_banner_file_id", "TEXT"),
        ]:
            _add_col(c, tbl, col, ddl)

        for k, v in DEFAULT_VARS.items():
            c.execute("INSERT OR IGNORE INTO vars(k,v) VALUES(?,?)", (k, v))

        # Font defaults — both slots Sans Bold
        for slot, style_default in (("message", "small_caps"), ("button", "small_caps")):
            c.execute(
                "INSERT OR IGNORE INTO font_settings(key,value,updated_at) VALUES(?,?,?)",
                (slot, style_default, datetime.now(UTC).isoformat()),
            )

        # Broadcast config singleton
        c.execute(
            "INSERT OR IGNORE INTO broadcast_config(id,auto_brand,auto_quote,auto_pin_channels,auto_pin_groups,updated_at) "
            "VALUES(1,1,1,0,0,?)",
            (datetime.now(UTC).isoformat(),),
        )

        # Seed message templates with new defaults if missing
        for k, v in (
            ("group_welcome_message", GROUP_WELCOME_DEFAULT),
            ("group_goodbye_message", GROUP_GOODBYE_DEFAULT),
        ):
            c.execute(
                "INSERT INTO message_templates(key, body) VALUES(?,?) "
                "ON CONFLICT(key) DO UPDATE SET body=excluded.body",
                (k, v),
            )
            c.execute(
                "INSERT INTO vars(k,v) VALUES(?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",
                (k, v),
            )

    font_reload_from_db()
    log.info("[DB] initialized at %s", DB_PATH)

