def now_ist() -> datetime:
    return datetime.now(IST)


def now_utc() -> datetime:
    return datetime.now(UTC)


def html_escape(s: str) -> str:
    return (s or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def mention_user(user) -> str:
    if not user:
        return "Unknown"
    name = html_escape(getattr(user, "first_name", None) or getattr(user, "username", None) or str(getattr(user, "id", "?")))
    uid = getattr(user, "id", None)
    if not uid:
        return name
    return f'<a href="tg://user?id={uid}">{name}</a>'


def get_var(key: str, default: str = "") -> str:
    with db() as c:
        r = c.execute("SELECT v FROM vars WHERE k=?", (key,)).fetchone()
        return r["v"] if r else default


def set_var(key: str, value: str) -> None:
    with db() as c:
        c.execute("INSERT INTO vars(k,v) VALUES(?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v", (key, str(value)))


def get_msg(key: str, default: str = "") -> str:
    with db() as c:
        r = c.execute("SELECT body FROM message_templates WHERE key=?", (key,)).fetchone()
        if r and r["body"]:
            return r["body"]
    return get_var(key, default)


def set_msg(key: str, body: str) -> None:
    with db() as c:
        c.execute(
            "INSERT INTO message_templates(key,body) VALUES(?,?) "
            "ON CONFLICT(key) DO UPDATE SET body=excluded.body",
            (key, body),
        )
    set_var(key, body)


def log_action(actor_id: int, action: str, detail: str = "", level: str = "INFO") -> None:
    try:
        with db() as c:
            c.execute(
                "INSERT INTO logs(ts,level,actor_id,action,detail) VALUES(?,?,?,?,?)",
                (now_ist().isoformat(), level, actor_id, action, (detail or "")[:2000]),
            )
    except Exception as e:
        log.warning("log_action: %s", e)


def is_main_admin(user_id) -> bool:
    try:
        return bool(user_id and int(user_id) == int(MAIN_ADMIN_ID))
    except Exception:
        return False


def get_brand_line() -> str:
    if get_var("brand_tag_enabled", "1") == "0":
        return ""
    name = get_var("brand_name", "Dev")
    dev = get_var("brand_dev_username", "@RehanCodex")
    fmt = get_var("brand_tag_format", "<tg-emoji emoji-id=\"6154431420677752889\">🤩</tg-emoji> {name} {username}")
    try:
        return fmt.replace("{name}", sb(name)).replace("{username}", dev)
    except Exception:
        return "<tg-emoji emoji-id=\"6129705083501293112\">👑</tg-emoji> " + sb(name) + " " + dev


def _brand_marker() -> str:
    return get_var("brand_dev_username", "@RehanCodex")


_LINE_EMOJI_COUNTER = [0]
_LINE_EMOJI_FALLBACKS = ["✨", "💎", "📌", "🔥", "⚡", "🚀", "🌟", "🎯", "💫", "🔮"]


def _apply_line_prefixes(body_lines):
    if not globals().get("_AUTO_EMOJI_ENABLED", False):
        return list(body_lines)
    # Only prefix if total size stays under limit
    joined_len = sum(len(b or "") for b in body_lines)
    if joined_len + 5 * len(body_lines) * 50 > 800:
        return list(body_lines)
    return [_prefix_one_line(ln) for ln in body_lines]


def quote_panel(*lines: str, brand: bool = True) -> str:
    marker = _brand_marker()
    body = []
    for ln in lines:
        if ln is None:
            continue
        s = str(ln)
        if marker and marker in s:
            continue
        if "Dev @RehanCodex" in s or "𝗗𝗲𝘃 @RehanCodex" in s:
            continue
        body.append(s)
    while body and not body[0].strip():
        body.pop(0)
    while body and not body[-1].strip():
        body.pop()
    body = _apply_line_prefixes(body)
    main = "\n".join(body) if body else ""
    brand_line = get_brand_line() if brand else ""
    if not brand_line:
        result = f"<blockquote>{main}</blockquote>" if main else ""
    elif main:
        result = f"<blockquote>{main}</blockquote>\n\n<blockquote>{brand_line}</blockquote>"
    else:
        result = f"<blockquote>{brand_line}</blockquote>"
    return premiumize(result)


def panel(title: str, *detail_lines: str, brand: bool = True) -> str:
    lines = [sb(title), ""]
    for d in detail_lines:
        if d:
            lines.append(d)
    result = quote_panel(*lines, brand=brand)
    try:
        if "Advanced Telegram Management System" in title and "_BOT_ONLINE_HEADER" in globals():
            if "6120587228709130895" not in result:
                result = _BOT_ONLINE_HEADER + "\n" + result
    except Exception:
        pass
    return result


def get_btn(key: str, default_emoji: str, default_label: str,
            default_style: str = "primary") -> Tuple[str, str, str]:
    """Read emoji/label/style from button_labels table. Falls back to defaults."""
    try:
        with db() as c:
            r = c.execute(
                "SELECT emoji, label, style FROM button_labels WHERE key=?",
                (key,),
            ).fetchone()
        if r:
            emoji = r["emoji"] if r["emoji"] is not None else default_emoji
            label = r["label"] if r["label"] else default_label
            style = r["style"] if r["style"] in ("primary", "success", "danger") else default_style
            return (emoji or "", label, style)
    except Exception:
        pass
    return (default_emoji, default_label, default_style)






