def _split_leading_emoji(text):
    if not text:
        return None, ""
    s = str(text)
    try:
        _load_premium_map()
    except Exception:
        pass
    for e in _PREMIUM_KEYS:
        if s.startswith(e):
            rest = s[len(e):]
            while rest and _is_modifier(ord(rest[0])):
                rest = rest[1:]
            return e, rest.lstrip()
    if s and _is_primary_emoji(ord(s[0])):
        j = 1
        while j < len(s) and _is_modifier(ord(s[j])):
            j += 1
        return s[:j], s[j:].lstrip()
    return None, s


import hashlib as _hashlib


def _stable_idx(key: str, mod: int) -> int:
    """Deterministic index from string key — same key → same idx."""
    if mod <= 0:
        return 0
    try:
        h = int(_hashlib.md5(key.encode("utf-8")).hexdigest(), 16)
        return h % mod
    except Exception:
        return 0


def styled_button(text, callback_data=None, url=None, *, style="primary", icon_id=None, copy_text=None):
    """Premium-aware button builder — supports copy_text mode too."""
    global _BTN_ID_COUNTER
    if style not in ("primary", "success", "danger"):
        raise ValueError(f"bad style: {style}")
    raw = "" if text is None else str(text)
    # DB override (only for callback_data buttons)
    if callback_data is not None:
        try:
            lbl, ic = _btn_override_get(callback_data)
            if lbl is not None:
                raw = lbl
            if ic:
                icon_id = ic
        except Exception:
            pass
    # Strip <tg-emoji> tags
    raw = re.sub(r"<tg-emoji[^>]*>", "", raw).replace("</tg-emoji>", "")
    # Strip leading emoji
    stripped = raw.lstrip()
    if stripped:
        try:
            cp0 = ord(stripped[0])
        except TypeError:
            cp0 = 0
        if _is_primary_emoji(cp0):
            j = 1
            while j < len(stripped):
                try:
                    if _is_modifier(ord(stripped[j])):
                        j += 1
                    else:
                        break
                except TypeError:
                    break
            stripped = stripped[j:].lstrip()
    raw = stripped
    # Icon
    if icon_id is None and _BTN_PREMIUM_IDS:
        icon_id = _BTN_PREMIUM_IDS[_BTN_ID_COUNTER % len(_BTN_PREMIUM_IDS)]
        _BTN_ID_COUNTER += 1
    display = bf(raw)

    # ============================================================
    # copy_text mode — exclusive (no callback_data, no url)
    # ============================================================
    if copy_text is not None:
        try:
            from telegram import CopyTextButton
            kw = {
                "text": display,
                "copy_text": CopyTextButton(text=str(copy_text)[:256]),
            }
            if icon_id:
                kw["icon_custom_emoji_id"] = icon_id
            kw["style"] = style
            try:
                return InlineKeyboardButton(**kw)
            except TypeError:
                # Fallback — try without icon/style
                kw.pop("icon_custom_emoji_id", None)
                kw.pop("style", None)
                return InlineKeyboardButton(**kw)
        except Exception as e:
            log.warning("copy_text button failed: %s", e)
            # Fall through to normal mode with callback_data

    # ============================================================
    # Normal mode
    # ============================================================
    kwargs = {"text": display, "style": style}
    if icon_id:
        kwargs["icon_custom_emoji_id"] = icon_id
    if callback_data is not None:
        kwargs["callback_data"] = callback_data
    if url is not None:
        kwargs["url"] = url
    try:
        return InlineKeyboardButton(**kwargs)
    except TypeError:
        kwargs.pop("icon_custom_emoji_id", None)
        return InlineKeyboardButton(**kwargs)

def clean_ui_text(t: str) -> str:
    return str(t or "").strip()


def parse_time_to_hhmm(raw: str) -> Optional[str]:
    if raw is None:
        return None
    text = str(raw).strip()
    if not text:
        return None
    for ch in ("\u00a0", "\u2009", "\u200b", "\u200c", "\u200d", "\ufeff"):
        text = text.replace(ch, " ")
    text = text.upper().replace(".", "").replace(",", "")
    text = re.sub(r"\s+", " ", text).strip()
    text = re.sub(r"\bA\s*M\b", "AM", text)
    text = re.sub(r"\bP\s*M\b", "PM", text)
    text = re.sub(r"(\d)\s*(AM|PM)\b", r"\1 \2", text)
    text = re.sub(r"(\d{1,2}:\d{1,2})\s*(AM|PM)\b", r"\1 \2", text)
    m = re.fullmatch(r"(\d{1,2})(?::(\d{1,2}))?\s*(AM|PM)?", text)
    if not m:
        return None
    try:
        hour = int(m.group(1))
        minute = int(m.group(2)) if m.group(2) is not None else 0
    except Exception:
        return None
    ampm = m.group(3)
    if minute < 0 or minute > 59:
        return None
    if ampm:
        if hour < 1 or hour > 12:
            return None
        if ampm == "AM":
            hour = 0 if hour == 12 else hour
        else:
            hour = 12 if hour == 12 else hour + 12
    else:
        if hour < 0 or hour > 23:
            return None
    return f"{hour:02d}:{minute:02d}"


def _hhmm_minutes(v: str, default: str) -> int:
    v = (str(v).strip() if v else "") or default
    try:
        h, m = map(int, str(v).split(":"))
        return (h % 24) * 60 + (m % 60)
    except Exception:
        try:
            h, m = map(int, str(default).split(":"))
            return (h % 24) * 60 + (m % 60)
        except Exception:
            return 0


def format_hhmm_display(hhmm: str) -> str:
    try:
        h, m = map(int, str(hhmm).split(":"))
        dt = now_ist().replace(hour=h % 24, minute=m % 60, second=0, microsecond=0)
        out = dt.strftime("%I:%M %p")
        return out.lstrip("0") if not out.startswith("0:") else out
    except Exception:
        return str(hhmm)


def format_remaining(delta: timedelta) -> str:
    secs = max(0, int(delta.total_seconds()))
    h, rem = divmod(secs, 3600)
    m, _ = divmod(rem, 60)
    if h > 0 and m > 0:
        return f"{h}h {m}m"
    if h > 0:
        return f"{h}h"
    if m > 0:
        return f"{m}m"
    return "less than a minute"


def format_remaining_delay(seconds: float) -> str:
    seconds = max(0, int(seconds))
    m, s = divmod(seconds, 60)
    return f"{m}m {s}s" if m else f"{s}s"


def night_window_status(start: str, end: str, now=None) -> Dict[str, Any]:
    now = now or now_ist()
    s_min = _hhmm_minutes(start, "23:00")
    e_min = _hhmm_minutes(end, "07:00")
    cur = now.hour * 60 + now.minute
    overnight = s_min > e_min
    active = (cur >= s_min or cur < e_min) if overnight else (s_min <= cur < e_min)
    today_midnight = now.replace(hour=0, minute=0, second=0, microsecond=0)
    end_dt = today_midnight + timedelta(minutes=e_min)
    if end_dt <= now:
        end_dt += timedelta(days=1)
    remaining = max(timedelta(0), end_dt - now) if active else timedelta(0)
    return {"active": active, "end_dt": end_dt if active else None, "remaining": remaining,
            "start_hhmm": start, "end_hhmm": end}


def parse_delay_duration(raw: str) -> Optional[int]:
    raw = (raw or "").strip().lower()
    m = re.fullmatch(r"(\d+)\s*(s|m|h)", raw)
    if not m:
        return None
    n, unit = int(m.group(1)), m.group(2)
    if n <= 0:
        return None
    mult = {"s": 1, "m": 60, "h": 3600}[unit]
    secs = n * mult
    return secs if 1 <= secs <= 24 * 3600 else None


def parse_telegram_post_link(raw: str) -> Optional[Dict[str, Any]]:
    raw = (raw or "").strip()
    if not raw:
        return None
    m = re.match(r"(?i)^https?://t\.me/c/(\d+)/(\d+)/?(?:\?.*)?$", raw)
    if m:
        return {"ref": int(f"-100{m.group(1)}"), "message_id": int(m.group(2)),
                "post_link": raw, "kind": "private"}
    m = re.match(r"(?i)^https?://t\.me/([A-Za-z0-9_]{4,})/(\d+)/?(?:\?.*)?$", raw)
    if m:
        return {"ref": f"@{m.group(1)}", "message_id": int(m.group(2)),
                "post_link": raw, "kind": "public"}
    return None


def _fmt_duration(secs: int) -> str:
    secs = int(secs or 0)
    if secs % 86400 == 0 and secs >= 86400:
        d = secs // 86400
        return f"{d} Day" + ("s" if d != 1 else "")
    if secs % 3600 == 0 and secs >= 3600:
        h = secs // 3600
        return f"{h} Hour" + ("s" if h != 1 else "")
    if secs % 60 == 0:
        return f"{secs // 60} Minutes"
    return f"{secs}s"


def quota_day_key(dt: Optional[datetime] = None) -> str:
    if dt is None:
        dt = now_ist()
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=IST)
    else:
        dt = dt.astimezone(IST)
    return dt.strftime("%Y-%m-%d")


def progress_bar(pct: int, width: int = 20) -> str:
    pct = max(0, min(100, int(pct)))
    filled = int(round(width * pct / 100))
    bar = "█" * filled + "░" * (width - filled)
    return f"[{bar}] {pct}%"


