# ============================================================
#              PYROGRAM SINGLETON CLIENT
# ============================================================
_pyro_client = None
_pyro_lock: Optional[asyncio.Lock] = None


def _pyro_get_lock() -> asyncio.Lock:
    global _pyro_lock
    if _pyro_lock is None:
        _pyro_lock = asyncio.Lock()
    return _pyro_lock


def pyro_available() -> bool:
    return bool(MT_PROTO_API_ID and MT_PROTO_API_HASH and MT_PROTO_SESSION_STRING)


async def get_pyro_client():
    """Singleton Pyrogram client. Reused across features so session is not
    duplicated / revoked by Telegram."""
    global _pyro_client
    if not pyro_available():
        return None
    if _pyro_client is not None:
        try:
            if _pyro_client.is_connected:
                return _pyro_client
        except Exception:
            pass
    async with _pyro_get_lock():
        if _pyro_client is not None:
            try:
                if _pyro_client.is_connected:
                    return _pyro_client
            except Exception:
                pass
        try:
            from pyrogram import Client as _PC
            _pyro_client = _PC(
                "rehan_codex_mtproto",
                api_id=int(MT_PROTO_API_ID),
                api_hash=str(MT_PROTO_API_HASH),
                session_string=str(MT_PROTO_SESSION_STRING),
                in_memory=True,
                no_updates=True,
            )
            await _pyro_client.start()
            log.info("[PYRO] client connected")
            return _pyro_client
        except Exception as e:
            log.warning("[PYRO] start failed: %s", e)
            _pyro_client = None
            return None


async def stop_pyro_client() -> None:
    global _pyro_client
    if _pyro_client is not None:
        try:
            await _pyro_client.stop()
        except Exception:
            pass
        _pyro_client = None


