async def send_section_banner(bot, chat_id: int, section_key: str,
                              caption: str = "", reply_markup=None) -> Optional[Message]:
    media_type = None
    file_id = None
    with db() as c:
        row = c.execute(
            "SELECT media_type, file_id FROM section_banners WHERE section_key=?",
            (section_key,),
        ).fetchone()
        if row and row["file_id"]:
            media_type, file_id = row["media_type"], row["file_id"]
        if not file_id and section_key not in _GROUP_DEFAULT_SLOTS:
            gfid = get_var("global_banner_file_id", "")
            if gfid:
                media_type = get_var("global_banner_media_type", "photo") or "photo"
                file_id = gfid

    caption = caption or ""
    try:
        if file_id:
            if media_type == "video":
                return await bot.send_video(chat_id, file_id, caption=caption,
                                            parse_mode=ParseMode.HTML, reply_markup=reply_markup)
            if media_type in ("animation", "gif"):
                return await bot.send_animation(chat_id, file_id, caption=caption,
                                                parse_mode=ParseMode.HTML, reply_markup=reply_markup)
            return await bot.send_photo(chat_id, file_id, caption=caption,
                                        parse_mode=ParseMode.HTML, reply_markup=reply_markup)
    except Exception as e:
        log.warning("custom banner [%s]: %s", section_key, e)

    return await bot.send_message(chat_id, caption or f"<b>{BOT_NAME}</b>",
                                  parse_mode=ParseMode.HTML, reply_markup=reply_markup)


def set_section_banner(section_key: str, media_type: str, file_id: str) -> None:
    with db() as c:
        c.execute(
            "INSERT INTO section_banners(section_key,media_type,file_id,updated_at) "
            "VALUES(?,?,?,?) ON CONFLICT(section_key) DO UPDATE SET "
            "media_type=excluded.media_type, file_id=excluded.file_id, updated_at=excluded.updated_at",
            (section_key, media_type, file_id, now_ist().isoformat()),
        )


def restore_section_banner(section_key: str) -> None:
    with db() as c:
        c.execute("DELETE FROM section_banners WHERE section_key=?", (section_key,))


