def help_category_kb(category: str) -> InlineKeyboardMarkup:
    with db() as c:
        rows = c.execute(
            "SELECT command, description FROM help_entries WHERE category=? ORDER BY id",
            (category,),
        ).fetchall()
    kb_rows = []
    for r in rows:
        cmd = r["command"]
        kb_rows.append([
            styled_button(f"{cmd} — {(r['description'] or '')[:28]}",
                          f"help:item:{category}:{cmd.replace('/', '')}", style="primary")
        ])
