# ============================================================
#                    CALLBACK ROUTER
# ============================================================
async def callbacks(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if not query:
        return
    user = query.from_user
    data = (query.data or "").strip()

    await safe_answer(query)

    if get_var("maintenance", "0") == "1" and user and not is_main_admin(user.id):
        await safe_answer(query, "Bot is under maintenance.", show_alert=True)
        return

    try:
        await _route_callback(update, context, data)
        return
    except ApplicationHandlerStop:
        raise
    except Exception as e:
        log.error("Callback error %s: %s\n%s", data, e, traceback.format_exc())

    chat_id = query.message.chat_id if query.message else None
    if not chat_id:
        return
    try:
        await safe_edit_or_send(
            update, context,
            panel("Navigation Error", "<tg-emoji emoji-id=\"6314237837977847753\">😡</tg-emoji> " + sb("That panel could not be opened."),
                  "<tg-emoji emoji-id=\"6314192865375291243\">😘</tg-emoji> " + sb("The main menu is still available below.")),
            main_menu_kb(get_var("bot_username", "")),
        )
    except Exception as e2:
        log.warning("callback recovery: %s", e2)


async def _route_callback(update: Update, context: ContextTypes.DEFAULT_TYPE, data: str) -> None:
    query = update.callback_query
    user = query.from_user

    # --- Navigation ---
    if data in ("menu:home", "home", "close"):
        await _nav_home(update, context); return
    if data == "menu:help":
        await _nav_help(update, context); return
    if data == "menu:group":
        await _nav_group_hub(update, context); return
    if data == "menu:channel":
        await _nav_channel_hub(update, context); return
    if data == "menu:clone":
        await _nav_clone(update, context); return
    if data == "help:hidden":
        await _nav_hidden(update, context); return
    if data.startswith("help:panel:"):
        await handle_help_panel_callback(update, context, data); return
    if data.startswith("help:"):
        await _help_dispatch(update, context, data); return
    if data == "a:home":
        await _nav_admin_home(update, context); return

    # Backward-compatible admin menu callbacks (admin:*) route to admin handlers.
    # The current admin keyboard uses this namespace, while the handler expects a:*.
    if data.startswith("admin:"):
        await handle_admin_callback(update, context, "a:" + data.split(":", 1)[1]); return

    # --- Feature namespaces ---
    if data.startswith("font:"):
        await handle_font_callback(update, context, data); return
    if data.startswith("talk:"):
        await handle_talk_owner_callback(update, context, data); return
    if data.startswith("op:"):
        await handle_operator_callback(update, context, data); return
    if data.startswith("bc:"):
        await handle_broadcast_callback(update, context, data); return
    if data.startswith("a:"):
        await handle_admin_callback(update, context, data); return
    if data.startswith("banner:"):
        await handle_banner_callback(update, context, data); return
    if data.startswith("g:"):
        await handle_group_callback(update, context, data); return
    if data.startswith("w:"):
        await handle_whisper_callback(update, context, data); return
    if data.startswith("rep:"):
        await handle_reputation_callback(update, context, data); return
    if data.startswith("c:") or data.startswith("ch:"):
        await handle_channel_callback(update, context, data); return
    if data.startswith("fj:"):
        await handle_force_join_callback(update, context, data); return
    if data.startswith("r:") or data.startswith("report:"):
        await handle_report_callback(update, context, data); return
    if data.startswith("f:"):
        await handle_file_callback(update, context, data); return
    if data.startswith("rate:"):
        await handle_rate_callback(update, context, data); return
    if data.startswith("poll:"):
        await handle_poll_callback(update, context, data); return

    log.debug("unhandled callback: %s", data)
    await safe_edit_or_send(
        update, context,
        panel("Unknown Action", "<tg-emoji emoji-id=\"6062026539334109188\">😻</tg-emoji> " + sb("That action is unavailable."),
              "<tg-emoji emoji-id=\"6095920948060358845\">👩‍🚀</tg-emoji> " + sb("Return home and try again.")),
        InlineKeyboardMarkup([[styled_button("🏠 Home", "menu:home", style="primary")]]),
    )


