async def force_join_verify_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    user = update.effective_user
    chat = update.effective_chat
    if not query or not user or not chat:
        raise ApplicationHandlerStop
    try:
        await query.answer()
    except Exception:
        pass
    try:
        if is_main_admin(user.id):
            missing = []
        else:
            missing = await check_force_join(context.bot, int(user.id))
        if missing:
            rows = []
            row = []
            for ch in missing:
                title = ch.get("title") or "Channel"
                url = ch.get("url") or ch.get("ref") or get_link("owner")
                row.append(styled_button("🪐 " + str(title)[:28], url=url, style="primary"))
                if len(row) == 2:
                    rows.append(row); row = []
            if row:
                rows.append(row)
            rows.append([styled_button("🕊️ Verify", "fj:verify_new", style="success")])
            await safe_edit_or_send(
                update, context,
                panel("Access Restricted",
                      "<tg-emoji emoji-id=\"6314220842792257477\">🥰</tg-emoji> " + sb("You have not completed all required channels."),
                      "<tg-emoji emoji-id=\"6062160684047665430\">✅</tg-emoji> " + sb("Complete the remaining channels, then press <tg-emoji emoji-id=\"6314471789141427686\">🇬🇮</tg-emoji> Verify.")),
                InlineKeyboardMarkup(rows),
            )
            raise ApplicationHandlerStop
        try:
            await safe_delete(context.bot, chat.id, query.message.message_id)
        except Exception:
            pass
        uname = get_var("bot_username", "")
        caption = panel(
            "<tg-emoji emoji-id=\"6120688813275616207\">✅</tg-emoji> Advanced Telegram Management System",
            "<tg-emoji emoji-id=\"6061973170070489249\">🏈</tg-emoji> " + sb("Moderation and Group Control"),
            "<tg-emoji emoji-id=\"6264621426586683135\">👬</tg-emoji> " + sb("Utilities Filters and Telegram Tools"),
            "<tg-emoji emoji-id=\"6064454772109346955\">⚾️</tg-emoji> " + sb("Channel Management Center"),
            "",
            "<tg-emoji emoji-id=\"6226475313770006633\">🥙</tg-emoji> " + sb("Fast") + " • " + sb("Stable") + " • " + sb("Professional"),
            "<tg-emoji emoji-id=\"6226523271374833462\">🐗</tg-emoji> " + sb("Select Helps And Commands to open the directory."),
        )
        await send_section_banner(context.bot, chat.id, "main",
                                  caption=caption, reply_markup=main_menu_kb(uname))
    except ApplicationHandlerStop:
        raise
    except Exception as e:
        log.error("fj verify: %s\n%s", e, traceback.format_exc())
        try:
            await query.answer("Verification failed. Try again.", show_alert=True)
        except Exception:
            pass
    finally:
        raise ApplicationHandlerStop


