def list_user_managed_groups(user_id: int):
    with db() as c:
        try:
            if is_main_admin(user_id):
                return c.execute(
                    "SELECT chat_id, title, username FROM managed_chats "
                    "WHERE chat_type IN ('group','supergroup') ORDER BY title LIMIT 40"
                ).fetchall()
            return c.execute(
                "SELECT m.chat_id, m.title, m.username FROM managed_chats m "
                "INNER JOIN managed_group_access a ON a.chat_id=m.chat_id "
                "WHERE a.user_id=? AND m.chat_type IN ('group','supergroup') ORDER BY m.title LIMIT 40",
                (user_id,),
            ).fetchall()
        except Exception:
            return []


def list_owned_channels(user_id: int) -> List[Any]:
    with db() as c:
        return c.execute(
            "SELECT channel_id, title, username, enabled FROM managed_channels "
            "WHERE added_by_user_id=? AND COALESCE(status,'active')='active' ORDER BY title",
            (user_id,),
        ).fetchall()


async def is_group_admin(bot, chat_id: int, user_id: int) -> bool:
    if is_main_admin(user_id):
        return True
    try:
        m = await bot.get_chat_member(chat_id, user_id)
        return m.status in (ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER,
                            "creator", "administrator")
    except Exception:
        return False


async def authorized_for_group(bot, user_id: int, chat_id: int) -> bool:
    if is_main_admin(user_id):
        return True
    try:
        return await is_group_admin(bot, chat_id, user_id)
    except Exception:
        return False


async def authorized_for_channel(bot, user_id: int, channel_id: int) -> bool:
    if is_main_admin(user_id):
        return True
    if not channel_id:
        return False
    try:
        m = await bot.get_chat_member(channel_id, user_id)
        return m.status in (ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER,
                            "administrator", "creator")
    except Exception:
        return False


async def is_channel_owner(bot, user_id: Optional[int], channel_id: int) -> bool:
    """Owner = Main Admin OR the user who registered this channel."""
    if user_id is None or not channel_id:
        return False
    if is_main_admin(user_id):
        return True
    with db() as c:
        row = c.execute(
            "SELECT added_by_user_id FROM managed_channels WHERE channel_id=?",
            (int(channel_id),),
        ).fetchone()
    try:
        return bool(row and row["added_by_user_id"] and int(row["added_by_user_id"]) == int(user_id))
    except Exception:
        return False


async def is_channel_owner_strict(bot, user_id: Optional[int], channel_id: int) -> bool:
    """Live Telegram admin + registered owner, both verified."""
    if user_id is None or not channel_id:
        return False
    if is_main_admin(user_id):
        return True
    with db() as c:
        row = c.execute(
            "SELECT added_by_user_id FROM managed_channels WHERE channel_id=?",
            (int(channel_id),),
        ).fetchone()
    try:
        if not row or not row["added_by_user_id"] or int(row["added_by_user_id"]) != int(user_id):
            return False
    except Exception:
        return False
    try:
        m = await bot.get_chat_member(channel_id, user_id)
        return m.status in (ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER,
                            "administrator", "creator")
    except Exception:
        return False


def is_operator(user_id: int) -> bool:
    try:
        with db() as c:
            r = c.execute("SELECT 1 FROM operators WHERE user_id=? AND status='active'",
                          (int(user_id),)).fetchone()
            return bool(r)
    except Exception:
        return False


def cflag(channel_id: int, key: str, default: str = "off") -> str:
    with db() as c:
        r = c.execute("SELECT value FROM channel_flags WHERE channel_id=? AND key=?",
                      (channel_id, key)).fetchone()
        return r["value"] if r else default


def set_cflag(channel_id: int, key: str, value: str) -> None:
    with db() as c:
        c.execute(
            "INSERT INTO channel_flags(channel_id,key,value) VALUES(?,?,?) "
            "ON CONFLICT(channel_id,key) DO UPDATE SET value=excluded.value",
            (channel_id, key, str(value)),
        )


