async def check_force_join(bot, user_id: int) -> List[Dict[str, str]]:
    """Real membership for public channels; or pending-request for private."""
    missing: List[Dict[str, str]] = []
    with db() as c:
        try:
            rows = c.execute(
                "SELECT * FROM force_join WHERE COALESCE(enabled,1)=1 "
                "ORDER BY COALESCE(display_order,0), id"
            ).fetchall()
        except Exception:
            rows = c.execute("SELECT * FROM force_join").fetchall()

    for r in rows:
        ref = r["chat_ref"]
        try:
            cid = int(r["channel_id"]) if r["channel_id"] is not None else None
        except Exception:
            cid = None
        try:
            is_private = bool(r["is_private"])
        except Exception:
            is_private = False
        title = (r["custom_button_name"] if "custom_button_name" in r.keys() else None) or r["title"] or str(ref)
        join_url = (r["join_url"] if "join_url" in r.keys() else None) or (
            ref if str(ref).startswith("http") else f"https://t.me/{str(ref).lstrip('@')}"
        )
        try:
            member_ok = False
            if cid:
                try:
                    m = await bot.get_chat_member(int(cid), int(user_id))
                    member_ok = getattr(m, "status", None) in (
                        ChatMemberStatus.MEMBER, ChatMemberStatus.ADMINISTRATOR,
                        ChatMemberStatus.OWNER, "member", "administrator", "creator",
                    )
                except Exception:
                    member_ok = False
            if member_ok:
                continue
            if is_private and cid:
                pending = False
                try:
                    with db() as c:
                        rq = c.execute(
                            "SELECT status FROM force_join_requests WHERE user_id=? AND channel_id=? "
                            "ORDER BY id DESC LIMIT 1",
                            (int(user_id), int(cid)),
                        ).fetchone()
                    pending = bool(rq and str(rq["status"] or "").lower() == "pending")
                except Exception:
                    pass
                if pending:
                    continue
                missing.append({"ref": str(ref), "title": title, "url": join_url, "private": "1"})
                continue
            check_ref = cid if cid is not None else ref
            chat = await bot.get_chat(check_ref)
            m = await bot.get_chat_member(chat.id, user_id)
            if getattr(m, "status", None) not in (
                ChatMemberStatus.MEMBER, ChatMemberStatus.ADMINISTRATOR,
                ChatMemberStatus.OWNER, "member", "administrator", "creator",
            ):
                missing.append({"ref": str(ref), "title": title, "url": join_url})
        except Exception as e:
            log.warning("force_join check %s: %s", ref, e)
            missing.append({"ref": str(ref), "title": title, "url": join_url,
                            "private": "1" if is_private else "0"})
    return missing


