async def handle_report_callback(update: Update, context: ContextTypes.DEFAULT_TYPE, data: str) -> None:
    query = update.callback_query
    user = query.from_user
    parts = data.split(":")
    sub = parts[1] if len(parts) > 1 else ""

    if sub == "start":
        token = secrets.token_hex(8)
        PENDING[user.id] = {"action": "report_await_link", "token": token,
                            "started_at": now_ist().isoformat(),
                            "chat_scope": "private"}
        await safe_edit_or_send(
            update, context,
            panel("Report Content",
                  "<tg-emoji emoji-id=\"6314174306821605245\">😡</tg-emoji> " + sb("Send the Telegram Group/Channel post link."),
                  "<tg-emoji emoji-id=\"6064207472187410089\">✅</tg-emoji> " + sb("Example") + " <tg-emoji emoji-id=\"6316794301296675025\">👎</tg-emoji> https://t.me/channelname/123",
                  "<tg-emoji emoji-id=\"6316470533777000299\">👍</tg-emoji> " + sb("Bot verifies the link, then asks for reason."),
                  "<tg-emoji emoji-id=\"6314237837977847753\">💕</tg-emoji> " + sb("Reports go to bot admins, not Telegram.")),
            InlineKeyboardMarkup([[styled_button("⛓ Cancel", "help:hidden", style="danger")]]),
        )
        return

    if sub == "reason" and len(parts) >= 4:
        token = parts[2]
        code = parts[3]
        st = PENDING.get(user.id) or {}
        if st.get("action") != "report_await_reason" or st.get("token") != token:
            await safe_answer(query, "Session expired.", show_alert=True)
            PENDING.pop(user.id, None); return
        reasons = {"spam": "Spam", "scam": "Scam / Fraud",
                   "adult": "Inappropriate Content", "abuse": "Abuse / Harassment",
                   "other": "Other"}
        if code not in reasons:
            await safe_answer(query, "Invalid reason.", show_alert=True); return
        if code == "other":
            PENDING[user.id] = {**st, "action": "report_await_custom_reason", "reason_code": code}
            await safe_edit_or_send(
                update, context,
                panel("Custom Reason", "<tg-emoji emoji-id=\"6314192865375291243\">✅</tg-emoji> " + sb("Send a short description of the issue.")),
                InlineKeyboardMarkup([[styled_button("⛓ Cancel", "help:hidden", style="danger")]]),
            )
            return
        await _finalize_link_report(update, context, user, st, reasons[code])
        return
