# ============================================================
#                    ANTI-RAID
# ============================================================
_raid_joins: Dict[int, list] = {}


def get_anti_raid(chat_id: int) -> dict:
    with db() as c:
        try:
            r = c.execute("SELECT * FROM anti_raid WHERE chat_id=?", (chat_id,)).fetchone()
            if r:
                return dict(r)
        except Exception:
            pass
    return {"enabled": 0, "join_threshold": 8, "window_seconds": 30, "action": "mute"}


def set_anti_raid(chat_id: int, **kwargs) -> None:
    cur = get_anti_raid(chat_id)
    cur.update({k: v for k, v in kwargs.items() if v is not None})
    with db() as c:
        c.execute(
            "INSERT INTO anti_raid(chat_id,enabled,join_threshold,window_seconds,action,updated_at) "
            "VALUES(?,?,?,?,?,?) ON CONFLICT(chat_id) DO UPDATE SET "
            "enabled=excluded.enabled, join_threshold=excluded.join_threshold, "
            "window_seconds=excluded.window_seconds, action=excluded.action, "
            "updated_at=excluded.updated_at",
            (chat_id, int(cur.get("enabled") or 0), int(cur.get("join_threshold") or 8),
             int(cur.get("window_seconds") or 30), cur.get("action") or "mute",
             now_ist().isoformat()),
        )


async def anti_raid_on_join(bot, chat_id: int, user) -> None:
    cfg = get_anti_raid(chat_id)
    if not int(cfg.get("enabled") or 0):
        return
    now = time.time()
    bucket = _raid_joins.setdefault(chat_id, [])
    bucket.append(now)
    window = int(cfg.get("window_seconds") or 30)
    _raid_joins[chat_id] = [t for t in bucket if now - t < window]
    thr = int(cfg.get("join_threshold") or 8)
    if len(_raid_joins[chat_id]) < thr:
        return
    action = (cfg.get("action") or "mute").lower()
    try:
        if action == "kick":
            await bot.ban_chat_member(chat_id, user.id)
            await bot.unban_chat_member(chat_id, user.id)
        elif action == "ban":
            await bot.ban_chat_member(chat_id, user.id)
        else:
            until = datetime.now(IST) + timedelta(minutes=30)
            await bot.restrict_chat_member(
                chat_id, user.id,
                permissions=ChatPermissions(can_send_messages=False),
                until_date=until,
            )
        mod_log(chat_id, f"anti_raid_{action}", user.id, 0, f"thr={thr}/window={window}")
        _raid_joins[chat_id] = []
        try:
            await bot.send_message(
                chat_id,
                panel("Anti-Raid", "<tg-emoji emoji-id=\"6062026539334109188\">⚡</tg-emoji> " + sb("Rapid joins detected. Protection triggered."),
                      f"🎚 Threshold {thr}/{window}s"),
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
    except Exception as e:
        log.warning("anti_raid action: %s", e)


# ============================================================
#                    ANTI-NUKE
# ============================================================
_nuke_events: Dict[int, list] = {}


async def anti_nuke_chat_member(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    cm = update.chat_member
    if not cm or not cm.chat:
        return
    chat_id = cm.chat.id
    if gget(chat_id, "anti_nuke", "off") != "on":
        return
    actor = cm.from_user
    if not actor or is_main_admin(actor.id):
        return
    old_s = cm.old_chat_member.status if cm.old_chat_member else None
    new_s = cm.new_chat_member.status if cm.new_chat_member else None
    dangerous = False
    if old_s in (ChatMemberStatus.ADMINISTRATOR, "administrator") and new_s not in (
        ChatMemberStatus.ADMINISTRATOR, "administrator"
    ):
        dangerous = True
    if new_s in (ChatMemberStatus.BANNED, "kicked"):
        dangerous = True
    if not dangerous:
        return
    now = time.time()
    bucket = _nuke_events.setdefault(chat_id, [])
    bucket.append(now)
    _nuke_events[chat_id] = [t for t in bucket if now - t < 30]
    threshold = int(gget(chat_id, "anti_nuke_threshold", "5") or 5)
    if len(_nuke_events[chat_id]) >= threshold:
        try:
            await context.bot.promote_chat_member(
                chat_id, actor.id,
                can_manage_chat=False, can_delete_messages=False, can_restrict_members=False,
                can_promote_members=False, can_change_info=False,
                can_invite_users=False, can_pin_messages=False,
            )
            mod_log(chat_id, "anti_nuke_demote", actor.id, 0,
                    f"events={len(_nuke_events[chat_id])}")
            await context.bot.send_message(
                chat_id,
                panel("Anti-Nuke", "<tg-emoji emoji-id=\"6095920948060358845\">⚡</tg-emoji> " + sb("Dangerous mass admin actions detected."),
                      f"🎖 Actor restricted: {mention_user(actor)}"),
                parse_mode=ParseMode.HTML,
            )
            _nuke_events[chat_id] = []
        except Exception as e:
            log.warning("anti_nuke: %s", e)


