def _delete_reason_cfg(chat_id: int, chat_type: str) -> Dict[str, Any]:
    ct = "channel" if chat_type in ("channel", ChatType.CHANNEL) else "group"
    with db() as c:
        r = c.execute(
            "SELECT * FROM delete_reason_config WHERE chat_id=? AND chat_type=?",
            (chat_id, ct),
        ).fetchone()
    if not r:
        return {"enabled": 1, "auto_delete_seconds": 10}
    return {"enabled": int(r["enabled"] or 0), "auto_delete_seconds": int(r["auto_delete_seconds"] or 10)}


def set_delete_reason_cfg(chat_id: int, chat_type: str, enabled=None, auto_delete_seconds=None) -> None:
    ct = "channel" if chat_type in ("channel", ChatType.CHANNEL) else "group"
    cur = _delete_reason_cfg(chat_id, ct)
    if enabled is not None:
        cur["enabled"] = int(enabled)
    if auto_delete_seconds is not None:
        cur["auto_delete_seconds"] = max(3, min(int(auto_delete_seconds), 600))
    with db() as c:
        c.execute(
            "INSERT INTO delete_reason_config(chat_id,chat_type,enabled,auto_delete_seconds,updated_at) "
            "VALUES(?,?,?,?,?) ON CONFLICT(chat_id,chat_type) DO UPDATE SET "
            "enabled=excluded.enabled, auto_delete_seconds=excluded.auto_delete_seconds, "
            "updated_at=excluded.updated_at",
            (chat_id, ct, cur["enabled"], cur["auto_delete_seconds"], now_ist().isoformat()),
        )


