def get_graveyard_cfg(chat_id: int) -> Dict[str, Any]:
    with db() as c:
        r = c.execute("SELECT * FROM graveyard_config WHERE chat_id=?", (chat_id,)).fetchone()
    if not r:
        return {"enabled": 0, "graveyard_channel_id": None}
    return {"enabled": int(r["enabled"] or 0),
            "graveyard_channel_id": r["graveyard_channel_id"]}


async def archive_to_graveyard(context, source_chat_id: int, msg,
                               reason: str, author_id: Optional[int]) -> None:
    cfg = get_graveyard_cfg(source_chat_id)
    if not int(cfg.get("enabled") or 0):
        return
    gid = cfg.get("graveyard_channel_id")
    if not gid:
        return
    try:
        preview_text = (msg.text or msg.caption or "")[:200] if msg else ""
        media_type = None
        media_file_id = None
        if msg:
            if msg.photo:
                media_type, media_file_id = "photo", msg.photo[-1].file_id
            elif msg.video:
                media_type, media_file_id = "video", msg.video.file_id
            elif msg.animation:
                media_type, media_file_id = "animation", msg.animation.file_id
            elif msg.document:
                media_type, media_file_id = "document", msg.document.file_id
            elif msg.audio:
                media_type, media_file_id = "audio", msg.audio.file_id
            elif msg.voice:
                media_type, media_file_id = "voice", msg.voice.file_id
            elif msg.sticker:
                media_type, media_file_id = "sticker", msg.sticker.file_id

        author_disp = f"<code>{author_id}</code>" if author_id else "Unknown"
        header = panel(
            "Graveyard Archive",
            f"🏰 " + sb("Source") + f" ➜ <code>{source_chat_id}</code>",
            f"🗑️ " + sb("Reason") + f" ➜ {html_escape(reason)}",
            f"👤 " + sb("Author") + f" ➜ {author_disp}",
            f"😋 " + sb("Time") + f" ➜ {now_ist().strftime('%Y-%m-%d %H:%M:%S')}",
        )
        caption = (header + "\n\n" + preview_text) if preview_text else header

        sent = None
        try:
            if media_type == "photo":
                sent = await context.bot.send_photo(gid, media_file_id, caption=caption, parse_mode=ParseMode.HTML)
            elif media_type == "video":
                sent = await context.bot.send_video(gid, media_file_id, caption=caption, parse_mode=ParseMode.HTML)
            elif media_type == "animation":
                sent = await context.bot.send_animation(gid, media_file_id, caption=caption, parse_mode=ParseMode.HTML)
            elif media_type == "document":
                sent = await context.bot.send_document(gid, media_file_id, caption=caption, parse_mode=ParseMode.HTML)
            elif media_type == "audio":
                sent = await context.bot.send_audio(gid, media_file_id, caption=caption, parse_mode=ParseMode.HTML)
            elif media_type == "voice":
                sent = await context.bot.send_voice(gid, media_file_id, caption=caption, parse_mode=ParseMode.HTML)
            elif media_type == "sticker":
                sent = await context.bot.send_sticker(gid, media_file_id)
                try:
                    await context.bot.send_message(gid, caption, parse_mode=ParseMode.HTML)
                except Exception:
                    pass
            else:
                sent = await context.bot.send_message(gid, caption, parse_mode=ParseMode.HTML)
        except Exception as e:
            log.warning("graveyard send failed: %s", e)
            return

        with db() as c:
            c.execute(
                "INSERT INTO graveyard_archive(source_chat_id,source_message_id,graveyard_channel_id,"
                "graveyard_message_id,reason,author_id,content_preview,media_type,media_file_id,archived_at) "
                "VALUES(?,?,?,?,?,?,?,?,?,?)",
                (source_chat_id, getattr(msg, "message_id", 0), gid,
                 getattr(sent, "message_id", 0) if sent else 0,
                 reason, author_id or 0, preview_text, media_type or "", media_file_id or "",
                 now_ist().isoformat()),
            )
    except Exception as e:
        log.warning("archive_to_graveyard: %s", e)


