def get_adult_filter_cfg(chat_id: int, chat_type: str) -> Dict[str, Any]:
    ct = "channel" if chat_type in ("channel", ChatType.CHANNEL) else "group"
    with db() as c:
        r = c.execute("SELECT * FROM adult_filter_config WHERE chat_id=? AND chat_type=?",
                      (chat_id, ct)).fetchone()
    return {"enabled": int(r["enabled"] or 0)} if r else {"enabled": 0}


def set_adult_filter(chat_id: int, chat_type: str, enabled: int) -> None:
    ct = "channel" if chat_type in ("channel", ChatType.CHANNEL) else "group"
    with db() as c:
        c.execute(
            "INSERT INTO adult_filter_config(chat_id,chat_type,enabled,updated_at) "
            "VALUES(?,?,?,?) ON CONFLICT(chat_id,chat_type) DO UPDATE SET "
            "enabled=excluded.enabled, updated_at=excluded.updated_at",
            (chat_id, ct, int(enabled), now_ist().isoformat()),
        )
        if int(enabled):
            existing = c.execute(
                "SELECT COUNT(*) AS n FROM adult_filter_words WHERE chat_id=? AND chat_type=?",
                (chat_id, ct),
            ).fetchone()
            if int(existing["n"] or 0) == 0:
                for w in _ADULT_DEFAULT_WORDS:
                    c.execute(
                        "INSERT OR IGNORE INTO adult_filter_words(chat_id,chat_type,word) VALUES(?,?,?)",
                        (chat_id, ct, w),
                    )


def list_adult_words(chat_id: int, chat_type: str) -> List[str]:
    ct = "channel" if chat_type in ("channel", ChatType.CHANNEL) else "group"
    with db() as c:
        rows = c.execute(
            "SELECT word FROM adult_filter_words WHERE chat_id=? AND chat_type=? ORDER BY word",
            (chat_id, ct),
        ).fetchall()
    return [r["word"] for r in rows]


def is_adult_content(text: str, words: List[str]) -> Optional[str]:
    if not text:
        return None
    t = text.lower()
    for w in words:
        if w and w in t:
            return w
    return None


