def get_reputation(chat_id: int, user_id: int) -> int:
    with db() as c:
        r = c.execute("SELECT score FROM reputation WHERE chat_id=? AND user_id=?",
                      (chat_id, user_id)).fetchone()
    return int(r["score"] or 0) if r else 0


def bump_reputation(chat_id: int, user_id: int, delta: int,
                    reason: str = "", by_id: int = 0) -> int:
    with db() as c:
        cur = c.execute("SELECT score FROM reputation WHERE chat_id=? AND user_id=?",
                        (chat_id, user_id)).fetchone()
        new = int(cur["score"] or 0) + int(delta) if cur else int(delta)
        c.execute(
            "INSERT INTO reputation(chat_id,user_id,score,updated_at) VALUES(?,?,?,?) "
            "ON CONFLICT(chat_id,user_id) DO UPDATE SET score=excluded.score, "
            "updated_at=excluded.updated_at",
            (chat_id, user_id, new, now_ist().isoformat()),
        )
        c.execute(
            "INSERT INTO reputation_events(chat_id,user_id,delta,reason,by_id,created_at) "
            "VALUES(?,?,?,?,?,?)",
            (chat_id, user_id, delta, reason, by_id, now_ist().isoformat()),
        )
    try:
        if new >= 50 and not is_trusted(chat_id, user_id):
            add_trusted(chat_id, user_id, 0)
        if new <= 0 and is_trusted(chat_id, user_id):
            remove_trusted(chat_id, user_id)
    except Exception:
        pass
    return new


async def reputation_react_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """+rep / -rep reply-based text commands inside groups."""
    msg = update.message
    if not msg or not msg.text or msg.chat.type not in (ChatType.GROUP, ChatType.SUPERGROUP):
        return
    low = msg.text.strip().lower()
    if not (low.startswith("+rep") or low.startswith("-rep")):
        return
    if gget(msg.chat_id, "reputation_enabled", "off") != "on":
        return
    target = None
    if msg.reply_to_message and msg.reply_to_message.from_user:
        target = msg.reply_to_message.from_user
    if not target:
        return
    delta = 1 if low.startswith("+rep") else -1
    new_score = bump_reputation(msg.chat_id, target.id, delta,
                                reason="react", by_id=msg.from_user.id if msg.from_user else 0)
    try:
        await msg.reply_text(
            panel("Reputation",
                  f"👤 {mention_user(target)}",
                  f"⭐ " + sb("Score") + f" ➜ {new_score}"),
            parse_mode=ParseMode.HTML,
        )
    except Exception:
        pass


# ============================================================
#                    MEMBER TEMPLATE FORMAT
# ============================================================
def format_member_template(template: str, user, chat, member_count: int = 0,
                           extra: Optional[Dict[str, str]] = None) -> str:
    now = now_ist()
    name = html_escape(getattr(user, "full_name", None) or getattr(user, "first_name", None) or "User")
    username = f"@{user.username}" if getattr(user, "username", None) else "No Username"
    mention = f'<a href="tg://user?id={user.id}">{name}</a>'
    data = {
        "name": name,
        "user_id": str(user.id),
        "username": html_escape(username),
        "mention": mention,
        "group_name": html_escape(chat.title or "Group"),
        "member_count": str(member_count or 0),
        "language": getattr(user, "language_code", None) or "en",
        "join_date": now.strftime("%d %b %Y"),
        "join_time": now.strftime("%I:%M %p"),
        "leave_date": now.strftime("%d %b %Y"),
        "leave_time": now.strftime("%I:%M %p"),
        "duration": (extra or {}).get("duration", "—"),
        "role": (extra or {}).get("role", "Member"),
        "bot": BOT_NAME,
    }
    if extra:
        for k, v in extra.items():
            data[k] = str(v) if v is not None else ""
    out = template
    for k, v in data.items():
        out = out.replace("{" + k + "}", str(v))
    return out


# ============================================================
#                    ON CHAT MEMBER (welcome / goodbye / discovery)
# ============================================================
async def on_chat_member(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    # MY_CHAT_MEMBER = bot's own membership change
    my_result = update.my_chat_member
    if my_result and my_result.chat and my_result.chat.type in (
        ChatType.GROUP, ChatType.SUPERGROUP, ChatType.CHANNEL, "group", "supergroup", "channel"
    ):
        mchat = my_result.chat
        mnew = my_result.new_chat_member
        mnew_status = mnew.status if mnew else None
        mchat_type = (
            "supergroup" if mchat.type in (ChatType.SUPERGROUP, "supergroup")
            else "channel" if mchat.type in (ChatType.CHANNEL, "channel")
            else "group"
        )
        if mnew_status in (ChatMemberStatus.MEMBER, ChatMemberStatus.ADMINISTRATOR,
                           ChatMemberStatus.OWNER, "member", "administrator", "creator"):
            if mchat_type == "channel":
                try:
                    if not cflag(mchat.id, "bot_added_at", ""):
                        set_cflag(mchat.id, "bot_added_at", now_ist().isoformat())
                except Exception:
                    pass
            try:
                _record_discovered(mchat.id, mchat_type, mchat.title,
                                   getattr(mchat, "username", None), "my_chat_member")
            except Exception:
                pass

            # Send channel onboarding only when the bot is newly promoted to admin.
            # Independent persistent flags prevent duplicate messages on repeated updates.
            if mchat_type == "channel" and mnew_status in (
                ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER, "administrator", "creator"
            ):
                mold = my_result.old_chat_member
                mold_status = getattr(mold, "status", None) if mold else None
                was_admin = mold_status in (
                    ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER, "administrator", "creator"
                )
                if not was_admin:
                    try:
                        if not cflag(mchat.id, "channel_bot_online_sent", ""):
                            channel_title = html_escape(getattr(mchat, "title", None) or "Channel")
                            channel_username = (getattr(mchat, "username", None) or "").strip().lstrip("@")
                            channel_url = f"https://t.me/{channel_username}" if channel_username else ""
                            channel_label = (f'<a href="{html_escape(channel_url)}">{channel_title}</a>'
                                             if channel_url else channel_title)
                            online_text = "\n\n".join([
                                "<blockquote><tg-emoji emoji-id=\"6154532210675288074\">🇬🇳</tg-emoji> <b>BOT ONLINE</b></blockquote>",
                                f"<blockquote>📡 𝑪𝒉𝒂𝒏𝒏𝒆𝒍: {channel_label}</blockquote>",
                                "<blockquote><tg-emoji emoji-id=\"6152044763185940460\">🇬🇾</tg-emoji> 𝑩𝒐𝒕 𝒊𝒔 𝒂𝒄𝒕𝒊𝒗𝒆 𝒂𝒏𝒅 𝒓𝒆𝒂𝒅𝒚 𝒕𝒐 𝒎𝒂𝒏𝒂𝒈𝒆 𝒕𝒉𝒊𝒔 𝒄𝒉𝒂𝒏𝒏𝒆𝒍.</blockquote>",
                            ])
                            try:
                                await context.bot.send_message(
                                    chat_id=mchat.id, text=online_text, parse_mode=ParseMode.HTML,
                                    disable_web_page_preview=True,
                                )
                            except TimedOut:
                                # Delivery may have succeeded; avoid sending a duplicate online notice.
                                set_cflag(mchat.id, "channel_bot_online_sent", "1")
                            else:
                                set_cflag(mchat.id, "channel_bot_online_sent", "1")

                        if not cflag(mchat.id, "channel_congratulations_sent", ""):
                            try:
                                current_count = await context.bot.get_chat_member_count(mchat.id)
                            except Exception:
                                current_count = 0
                            congrats_text = (
                                f"🎉 𝑪𝒐𝒏𝒈𝒓𝒂𝒕𝒖𝒍𝒂𝒕𝒊𝒐𝒏𝒔! 𝑩𝒐𝒕 𝒊𝒔 𝒏𝒐𝒘 𝒂𝒅𝒎𝒊𝒏 𝒊𝒏 {html_escape(getattr(mchat, 'title', None) or 'your channel')}."
                            )
                            try:
                                await _send_milestone_congratulations(
                                    context.bot, mchat.id, congrats_text,
                                    max(0, int(current_count)), member_count=current_count,
                                )
                            except TimedOut:
                                # Delivery status is unknown; do not retry and create a duplicate.
                                set_cflag(mchat.id, "channel_congratulations_sent", "1")
                            else:
                                set_cflag(mchat.id, "channel_congratulations_sent", "1")
                    except Exception as e:
                        log.warning("channel onboarding messages failed for %s: %s", mchat.id, e)
        elif mnew_status in (ChatMemberStatus.LEFT, ChatMemberStatus.BANNED, "left", "kicked"):
            try:
                with db() as c:
                    c.execute("UPDATE discovered_chats SET status='left', last_seen=? WHERE chat_id=?",
                              (now_ist().isoformat(), mchat.id))
            except Exception:
                pass
        return

    result = update.chat_member
    if not result:
        return
    chat = result.chat

    # Force-Join private-channel request state sync
    if chat and chat.type in (ChatType.CHANNEL, "channel"):
        try:
            new_member = result.new_chat_member
            target_user = getattr(new_member, "user", None)
            new_status = getattr(new_member, "status", None)
            if target_user:
                valid = new_status in (ChatMemberStatus.MEMBER, ChatMemberStatus.ADMINISTRATOR,
                                       ChatMemberStatus.OWNER, "member", "administrator", "creator")
                left = new_status in (ChatMemberStatus.LEFT, ChatMemberStatus.BANNED, "left", "kicked")
                with db() as c:
                    fj = c.execute(
                        "SELECT id FROM force_join WHERE channel_id=? AND is_private=1 LIMIT 1",
                        (int(chat.id),),
                    ).fetchone()
                    if fj:
                        if valid:
                            c.execute(
                                "UPDATE force_join_requests SET status='approved', "
                                "approved_at=COALESCE(approved_at,?), updated_at=? "
                                "WHERE user_id=? AND channel_id=?",
                                (now_ist().isoformat(), now_ist().isoformat(),
                                 int(target_user.id), int(chat.id)),
                            )
                        elif left:
                            c.execute(
                                "UPDATE force_join_requests SET status='left', updated_at=? "
                                "WHERE user_id=? AND channel_id=?",
                                (now_ist().isoformat(), int(target_user.id), int(chat.id)),
                            )
        except Exception as e:
            log.warning("fj sync: %s", e)
        return

    if not chat or chat.type not in (ChatType.GROUP, ChatType.SUPERGROUP):
        return
    old = result.old_chat_member
    new = result.new_chat_member
    user = new.user
    if not user or user.is_bot:
        return
    old_s = old.status if old else None
    new_s = new.status if new else None

    joined = new_s in (ChatMemberStatus.MEMBER, ChatMemberStatus.RESTRICTED, "member", "restricted") \
             and old_s in (ChatMemberStatus.LEFT, ChatMemberStatus.BANNED, "left", "kicked", None)
    left = new_s in (ChatMemberStatus.LEFT, ChatMemberStatus.BANNED, "left", "kicked") \
           and old_s in (ChatMemberStatus.MEMBER, ChatMemberStatus.RESTRICTED,
                         ChatMemberStatus.ADMINISTRATOR, "member", "restricted", "administrator")

    try:
        count = await context.bot.get_chat_member_count(chat.id)
    except Exception:
        count = 0

    if joined:
        try:
            await anti_raid_on_join(context.bot, chat.id, user)
        except Exception as e:
            log.warning("anti_raid join: %s", e)

    if joined and get_var("welcome_enabled", "on") != "off":
        if gget(chat.id, "welcome", "on") == "off":
            return
        tmpl = gget(chat.id, "welcome_text", "") or get_msg("group_welcome_message", GROUP_WELCOME_DEFAULT)
        text = format_member_template(tmpl, user, chat, count, {"role": "Member"})
        if "<blockquote>" not in text:
            text = quote_panel(text, brand=True)
        await send_section_banner(context.bot, chat.id, "welcome",
                                  caption=text, reply_markup=brand_buttons())
        return

    if left and get_var("goodbye_enabled", "on") != "off":
        if gget(chat.id, "goodbye", "on") == "off":
            return
        tmpl = gget(chat.id, "goodbye_text", "") or get_msg("group_goodbye_message", GROUP_GOODBYE_DEFAULT)
        text = format_member_template(tmpl, user, chat, count,
                                      {"role": "Former Member", "duration": "—"})
        if "<blockquote>" not in text:
            text = quote_panel(text, brand=True)
        await send_section_banner(context.bot, chat.id, "goodbye",
                                  caption=text, reply_markup=brand_buttons())
        return


def _record_discovered(chat_id: int, chat_type: str, title, username, source: str) -> None:
    if not chat_id or chat_type not in ("group", "supergroup", "channel"):
        return
    now = now_ist().isoformat()
    with db() as c:
        r = c.execute("SELECT title, username, added_by_user_id FROM discovered_chats WHERE chat_id=?",
                      (chat_id,)).fetchone()
        if r:
            c.execute(
                "UPDATE discovered_chats SET last_seen=?, title=?, username=?, chat_type=?, status='active' "
                "WHERE chat_id=?",
                (now, title or r["title"] or "", username if username is not None else (r["username"] or ""),
                 chat_type, chat_id),
            )
        else:
            c.execute(
                "INSERT INTO discovered_chats(chat_id,chat_type,title,username,first_seen,last_seen,status,source) "
                "VALUES(?,?,?,?,?,?,?,?)",
                (chat_id, chat_type, title or "", username or "", now, now, "active", source),
            )


# ============================================================
#                    JOIN REQUEST HANDLER
# ============================================================
async def on_join_request(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles chat join requests. Priority:
    1. If auto_join_accept is ON for this chat → approve immediately.
    2. If private Force-Join channel → record pending for later membership checks.
    3. Fall back to join_request_mode (manual / auto_approve / auto_decline)."""
    req = update.chat_join_request
    if not req:
        return
    user = getattr(req, "from_user", None)
    if not user:
        return
    chat = req.chat
    chat_id = int(chat.id)
    chat_type = "channel" if chat.type in (ChatType.CHANNEL, "channel") else "group"
    now = now_ist().isoformat()

    # 1. Auto-join-accept ON → approve incoming pending requests up to configured cap.
    if get_auto_join_accept(chat_id, chat_type):
        try:
            limit = gget(chat_id, "auto_join_limit", "Unlimited") if chat_type == "group" else "Unlimited"
            accepted = int(gget(chat_id, "auto_join_accepted_count", "0") or 0) if chat_type == "group" else 0
            if limit != "Unlimited" and accepted >= int(limit):
                log_action(int(user.id), "auto_join_accept_limit_reached", f"{chat_id}:{limit}")
                return  # leave request pending; never exceed configured limit
            await req.approve()
            if chat_type == "group":
                gset(chat_id, "auto_join_accepted_count", str(accepted + 1))
            log_action(int(user.id), "auto_join_accept", f"{chat_id}:approved:{accepted + 1}")
        except Exception as e:
            log.warning("auto_join_accept approve failed %s/%s: %s", chat_id, user.id, e)
        return

    # 2. Private force-join channel → record pending
    if chat_type == "channel":
        try:
            with db() as c:
                fj = c.execute(
                    "SELECT title, is_private FROM force_join WHERE channel_id=? AND COALESCE(enabled,1)=1",
                    (chat_id,),
                ).fetchone()
                if fj and int(fj["is_private"] or 0):
                    c.execute(
                        "INSERT INTO force_join_requests(user_id,channel_id,channel_name,status,"
                        "requested_at,approved_at,updated_at) VALUES(?,?,?,?,?,?,?) "
                        "ON CONFLICT(user_id,channel_id) DO UPDATE SET channel_name=excluded.channel_name, "
                        "status='pending', requested_at=excluded.requested_at, approved_at=NULL, "
                        "updated_at=excluded.updated_at",
                        (int(user.id), chat_id, fj["title"] or chat.title or str(chat_id),
                         "pending", now, None, now),
                    )
                    log_action(int(user.id), "private_join_request", f"{chat_id}:pending")
                    return
        except Exception as e:
            log.warning("fj request record: %s", e)

    # 3. Fall back to per-group join_request_mode
    mode = gget(chat_id, "join_request_mode", "manual")
    try:
        if mode == "auto_approve":
            await req.approve()
            log_action(0, "join_auto_approve", f"{chat_id}:{user.id}")
        elif mode == "auto_decline":
            await req.decline()
            log_action(0, "join_auto_decline", f"{chat_id}:{user.id}")
    except Exception as e:
        log.warning("join_request: %s", e)


# ============================================================
#                    GROUP PROTECTION RUNTIME
# ============================================================
_spam_bucket: Dict[str, list] = {}


async def group_protection_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    if not msg or not msg.chat or msg.chat.type not in (ChatType.GROUP, ChatType.SUPERGROUP):
        return
    user = msg.from_user
    if not user or user.is_bot:
        return
    chat_id = msg.chat_id
    if is_main_admin(user.id):
        return
    try:
        if await is_group_admin(context.bot, chat_id, user.id):
            return
    except Exception:
        pass
    if is_trusted(chat_id, user.id):
        return

    # Anti-forward
    if get_anti_forward(chat_id, "group") and (
        getattr(msg, "forward_origin", None) is not None or getattr(msg, "forward_date", None) is not None
    ):
        try:
            await msg.delete()
            await post_delete_reason(context, chat_id, "group", "anti_forward", user.id)
            try:
                await archive_to_graveyard(context, chat_id, msg, "Anti-Forward", user.id)
            except Exception:
                pass
        except Exception as e:
            log.warning("anti-forward delete: %s", e)
        return

    # 18+ filter
    af_cfg = get_adult_filter_cfg(chat_id, "group")
    if int(af_cfg.get("enabled") or 0):
        body = msg.text or msg.caption or ""
        words = list_adult_words(chat_id, "group")
        hit = is_adult_content(body, words)
        if hit:
            try:
                await msg.delete()
                await post_delete_reason(context, chat_id, "group", "adult_filter", user.id)
                try:
                    await archive_to_graveyard(context, chat_id, msg, f"18+ ({hit})", user.id)
                except Exception:
                    pass
            except Exception as e:
                log.warning("18+ delete: %s", e)
            return

    # Word filter
    if gget(chat_id, "word_filter", "off") == "on":
        body = (msg.text or msg.caption or "").lower()
        raw_words = gget(chat_id, "word_list", "")
        wl = [w.strip().lower() for w in raw_words.split(",") if w.strip()]
        for w in wl:
            if w and w in body:
                try:
                    await msg.delete()
                    await post_delete_reason(context, chat_id, "group", "word_filter", user.id)
                    await archive_to_graveyard(context, chat_id, msg, f"Word: {w}", user.id)
                except Exception:
                    pass
                return

    # Content locks
    locks = {
        "photo": bool(msg.photo),
        "video": bool(msg.video),
        "animation": bool(msg.animation),
        "document": bool(msg.document),
        "audio": bool(msg.audio),
        "voice": bool(msg.voice),
        "sticker": bool(msg.sticker),
        "links": bool(msg.entities and any(e.type in ("url", "text_link") for e in (msg.entities or []))),
    }
    for key, present in locks.items():
        if not present:
            continue
        if gget(chat_id, f"lock_{key}", "off") == "on":
            try:
                await msg.delete()
                await post_delete_reason(context, chat_id, "group", "content_lock", user.id)
                await archive_to_graveyard(context, chat_id, msg, f"Lock: {key}", user.id)
            except Exception as e:
                log.warning("group lock: %s", e)
            return

    # Link guard
    if gget(chat_id, "link_guard", "off") == "on":
        text = msg.text or msg.caption or ""
        if re.search(r"t\.me/|telegram\.me/|https?://", text, re.I):
            try:
                await msg.delete()
                await post_delete_reason(context, chat_id, "group", "link_guard", user.id)
                await archive_to_graveyard(context, chat_id, msg, "Link Guard", user.id)
            except Exception:
                pass
            return

    # Anti-spam / flood
    if gget(chat_id, "anti_spam", "off") == "on":
        key = f"{chat_id}:{user.id}"
        now = time.time()
        bucket = _spam_bucket.setdefault(key, [])
        bucket.append(now)
        _spam_bucket[key] = [t for t in bucket if now - t < 10]
        limit = int(gget(chat_id, "spam_limit", "6") or 6)
        if len(_spam_bucket[key]) > limit:
            try:
                await msg.delete()
                until = datetime.now(IST) + timedelta(minutes=5)
                await context.bot.restrict_chat_member(
                    chat_id, user.id,
                    permissions=ChatPermissions(can_send_messages=False),
                    until_date=until,
                )
                mod_log(chat_id, "antispam_mute", user.id, 0, "flood")
                await post_delete_reason(context, chat_id, "group", "anti_spam", user.id)
            except Exception as e:
                log.warning("antispam: %s", e)
            _spam_bucket[key] = []
            return


# ============================================================
#                    GROUP PAUSE HANDLER
# ============================================================
async def group_pause_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    if not msg or not msg.chat or msg.chat.type not in (ChatType.GROUP, ChatType.SUPERGROUP):
        return
    cid = msg.chat_id
    if gget(cid, "paused", "off") != "on":
        return
    user = msg.from_user
    if not user:
        return
    if getattr(user, "is_bot", False):
        return
    if is_main_admin(user.id):
        return
    try:
        if await is_group_admin(context.bot, cid, user.id):
            return
    except Exception:
        pass
    try:
        await msg.delete()
    except Exception:
        return
    text = panel(
        "Group Is Paused",
        "<tg-emoji emoji-id=\"6151953834433319012\">🤩</tg-emoji> " + sb("Posting Is Currently Paused."),
        "<tg-emoji emoji-id=\"6152265584634496632\">🤩</tg-emoji> " + sb("Please Do Not Send Messages Right Now."),
        "<tg-emoji emoji-id=\"6152103458209007684\">🤩</tg-emoji> " + sb("Wait Until The Group Is Unpaused."),
    )
    try:
        notice = await context.bot.send_message(cid, text, parse_mode=ParseMode.HTML)
        if context.job_queue:
            context.job_queue.run_once(
                _delete_notice_job, when=10,
                data={"chat_id": cid, "message_id": notice.message_id},
                name=f"grpause_{cid}_{notice.message_id}",
            )
    except Exception as e:
        log.warning("group pause notice: %s", e)
    raise ApplicationHandlerStop


