async def group_night_mode_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    if not msg or not msg.from_user or msg.chat.type not in (ChatType.GROUP, ChatType.SUPERGROUP):
        return
    cid = msg.chat_id
    if gget(cid, "night_mode", "off") != "on":
        return
    start = gget(cid, "night_start", "23:00") or "23:00"
    end = gget(cid, "night_end", "07:00") or "07:00"
    status = night_window_status(start, end)
    if not status["active"]:
        return
    if is_main_admin(msg.from_user.id):
        return
    try:
        if await is_group_admin(context.bot, cid, msg.from_user.id):
            return
    except Exception:
        pass
    if gget(cid, "night_delete", "on") != "on":
        return
    try:
        await msg.delete()
    except Exception:
        return
    title = html_escape(msg.chat.title or str(cid))
    text = panel(
        "Night Mode Active",
        f"🏰 " + sb("Group") + f" ➜ {title}",
        "<tg-emoji emoji-id=\"6154431420677752889\">🤩</tg-emoji> " + sb("Your message was removed."),
        f"⏳ " + sb("Night Mode Remaining") + f" ➜ {format_remaining(status['remaining'])}",
        f"🌘 " + sb("Ends") + f" ➜ {format_hhmm_display(end)}",
    )
    try:
        notice = await context.bot.send_message(cid, text, parse_mode=ParseMode.HTML)
        if context.job_queue:
            context.job_queue.run_once(
                _delete_notice_job, when=5,
                data={"chat_id": cid, "message_id": notice.message_id},
                name=f"grnight_{cid}_{notice.message_id}",
            )
    except Exception:
        pass
    raise ApplicationHandlerStop


# ============================================================
#                    CUSTOM COMMANDS
# ============================================================
async def custom_command_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    if not msg or not msg.text or msg.chat.type not in (ChatType.GROUP, ChatType.SUPERGROUP):
        return
    text = msg.text.strip()
    if not text.startswith("/"):
        return
    cmd = text.split()[0].split("@")[0].lower()
    builtins = {
        "/start", "/help", "/rehan", "/ban", "/mute", "/warn", "/kick",
        "/unban", "/unmute", "/unwarn", "/restrict", "/unrestrict",
        "/promote", "/demote", "/warns", "/del", "/whisper", "/report",
        "/done", "/cancel", "/tools", "/rules", "/setrules", "/slow", "/groupstats",
    }
    if cmd in builtins:
        return
    key = f"cmd_{cmd.lstrip('/')}"
    resp = gget(msg.chat_id, key, "")
    if resp:
        body = resp if "<blockquote>" in str(resp) else quote_panel(str(resp), brand=True)
        try:
            await msg.reply_text(body, parse_mode=ParseMode.HTML)
        except Exception:
            pass


# ============================================================
#                    @all MENTION
# ============================================================
async def handle_all_mention(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    if not msg or not msg.text or msg.chat.type not in (ChatType.GROUP, ChatType.SUPERGROUP):
        return
    if "@all" not in msg.text.lower():
        return
    user = update.effective_user
    if not user or not await is_group_admin(context.bot, msg.chat_id, user.id):
        return
    with db() as c:
        try:
            rows = c.execute("SELECT user_id, username, first_name FROM group_members WHERE chat_id=? LIMIT 200",
                             (msg.chat_id,)).fetchall()
        except Exception:
            rows = []
    if not rows:
        await msg.reply_text(panel("@all", "<tg-emoji emoji-id=\"6228782806424618433\">😓</tg-emoji> " + sb("No tracked members yet.")), parse_mode=ParseMode.HTML)
        return
    batch, size = [], 0
    for r in rows:
        uid = r["user_id"]
        name = html_escape((r["first_name"] or r["username"] or str(uid))[:32])
        piece = f'<a href="tg://user?id={uid}">🧿 {name}</a>'
        if size + len(piece) > 3200:
            await msg.reply_text(quote_panel("<tg-emoji emoji-id=\"6152434913720141300\">⚡</tg-emoji> " + sb("@all"), " ".join(batch), brand=True),
                                 parse_mode=ParseMode.HTML)
            batch, size = [], 0
        batch.append(piece); size += len(piece) + 1
    if batch:
        await msg.reply_text(quote_panel("<tg-emoji emoji-id=\"6154369208076470797\">😘</tg-emoji> " + sb("@all"), " ".join(batch), brand=True),
                             parse_mode=ParseMode.HTML)


# ============================================================
#                    TRACK GROUP MEMBER
# ============================================================
async def track_group_member(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    if not msg or not msg.from_user or msg.chat.type not in (ChatType.GROUP, ChatType.SUPERGROUP):
        return
    u = msg.from_user
    if u.is_bot:
        return
    try:
        with db() as c:
            c.execute(
                "INSERT INTO managed_chats(chat_id,chat_type,title,username,last_seen) VALUES(?,?,?,?,?) "
                "ON CONFLICT(chat_id) DO UPDATE SET last_seen=excluded.last_seen, "
                "title=COALESCE(excluded.title, managed_chats.title)",
                (msg.chat_id, msg.chat.type, msg.chat.title or "",
                 getattr(msg.chat, "username", None) or "", now_ist().isoformat()),
            )
    except Exception:
        pass
    try:
        _record_discovered(msg.chat_id, msg.chat.type, msg.chat.title,
                           getattr(msg.chat, "username", None), "group_message")
    except Exception:
        pass
    try:
        with db() as c:
            c.execute(
                "INSERT OR IGNORE INTO group_members(chat_id,user_id,username,first_name) VALUES(?,?,?,?)",
                (msg.chat_id, u.id, u.username or "", u.first_name or ""),
            )
    except Exception:
        pass


