# ============================================================
#                    NIGHT WATCH JOB (global)
# ============================================================
async def night_watch_job(context: ContextTypes.DEFAULT_TYPE) -> None:
    try:
        with db() as c:
            grows = c.execute("SELECT chat_id FROM group_settings WHERE key='night_mode' AND value='on'").fetchall()
            crows = c.execute("SELECT channel_id FROM channel_flags WHERE key='night_mode' AND value='on'").fetchall()
    except Exception as e:
        log.warning("night_watch load: %s", e)
        return

    for r in grows:
        cid = r["chat_id"]
        try:
            start = gget(cid, "night_start", "23:00") or "23:00"
            end = gget(cid, "night_end", "07:00") or "07:00"
            status = night_window_status(start, end)
            was = gget(cid, "night_active_state", "0") == "1"
            if status["active"] and not was:
                gset(cid, "night_active_state", "1")
                try:
                    title = (await context.bot.get_chat(cid)).title or str(cid)
                except Exception:
                    title = str(cid)
                text = panel(
                    "Group Night Mode",
                    f"🏰 " + sb("Group") + f" ➜ {html_escape(title)}",
                    "<tg-emoji emoji-id=\"6314095339552901161\">⚡</tg-emoji> " + sb("Status") + " <tg-emoji emoji-id=\"6314220842792257477\">🤩</tg-emoji> ACTIVE",
                    f"🕰️ " + sb("Start") + f" ➜ {format_hhmm_display(start)}",
                    f"🌘 " + sb("End") + f" ➜ {format_hhmm_display(end)}",
                    f"⏳ " + sb("Remaining") + f" ➜ {format_remaining(status['remaining'])}",
                )
                try:
                    await send_section_banner(context.bot, cid, "group_night", caption=text)
                except Exception:
                    pass
            elif not status["active"] and was:
                gset(cid, "night_active_state", "0")
        except Exception as e:
            log.warning("night_watch group %s: %s", cid, e)

    for r in crows:
        cid = r["channel_id"]
        try:
            start = cflag(cid, "night_start", "23:00") or "23:00"
            end = cflag(cid, "night_end", "07:00") or "07:00"
            status = night_window_status(start, end)
            was = cflag(cid, "night_active_state", "0") == "1"
            if status["active"] and not was:
                set_cflag(cid, "night_active_state", "1")
                try:
                    title = (await context.bot.get_chat(cid)).title or str(cid)
                except Exception:
                    title = str(cid)
                text = panel(
                    "Channel Night Mode",
                    f"📡 " + sb("Channel") + f" ➜ {html_escape(title)}",
                    "<tg-emoji emoji-id=\"6062160684047665430\">💸</tg-emoji> " + sb("Status") + " <tg-emoji emoji-id=\"6314471789141427686\">💳</tg-emoji> ACTIVE",
                    f"⏳ " + sb("Remaining") + f" ➜ {format_remaining(status['remaining'])}",
                )
                try:
                    await send_section_banner(context.bot, cid, "channel_night", caption=text)
                except Exception:
                    pass
            elif not status["active"] and was:
                set_cflag(cid, "night_active_state", "0")
        except Exception as e:
            log.warning("night_watch channel %s: %s", cid, e)


# ============================================================
#                    GROUP CALLBACK ROUTER
# ============================================================
async def handle_group_callback(update: Update, context: ContextTypes.DEFAULT_TYPE, data: str) -> None:
    query = update.callback_query
    user = query.from_user
    parts = data.split(":")
    kind = parts[1] if len(parts) > 1 else ""

    # --- Add Group ---
    if kind == "add":
        PENDING[user.id] = {"action": "group_add", "chat_scope": "private"}
        await safe_edit_or_send(
            update, context,
            panel("Add Group",
                  "<tg-emoji emoji-id=\"6080209558259631951\">⚡️</tg-emoji> " + sb("Send your Group Username or Group ID."),
                  "<tg-emoji emoji-id=\"6264621426586683135\">💸</tg-emoji> " + sb("Examples:") + " @mygroup · -1001234567890"),
            InlineKeyboardMarkup([[styled_button("⛓ Cancel", "menu:group", style="danger")]]),
            section_key="group_add",
        )
        return

    # --- Manage a group ---
    if kind == "manage" and len(parts) >= 3:
        try:
            cid = int(parts[2])
        except Exception:
            await safe_answer(query, "Invalid group.", show_alert=True); return
        if not await authorized_for_group(context.bot, user.id, cid):
            await safe_answer(query, "Not authorized.", show_alert=True); return
        context.user_data["sel_group"] = cid
        title = str(cid)
        try:
            ch = await context.bot.get_chat(cid)
            title = ch.title or title
        except Exception:
            pass
        st = lambda k, d="off": "ON" if gget(cid, k, d) == "on" else "OFF"
        auto_join = "ON" if get_auto_join_accept(cid, "group") else "OFF"
        await safe_edit_or_send(
            update, context,
            panel("Group Management",
                  f"🏰 {html_escape(title)}",
                  f"🔗 " + sb("Link Guard") + f" ➜ {st('link_guard')}",
                  f"🧯 " + sb("Anti-Spam") + f" ➜ {st('anti_spam')}",
                  f"🌙 " + sb("Night") + f" ➜ {st('night_mode')}",
                  f"🎯 " + sb("Auto Join Accept") + f" ➜ {auto_join}",
                  "<tg-emoji emoji-id=\"6062255727378958459\">🍏</tg-emoji> " + sb("Select a control below.")),
            InlineKeyboardMarkup([
                [styled_button(f"🔗 Link {st('link_guard')}", f"g:toggle:link_guard:{cid}", style="primary"),
                 styled_button(f"🧯 Spam {st('anti_spam')}", f"g:toggle:anti_spam:{cid}", style="primary")],
                [styled_button(f"🔒 Lock Photo {st('lock_photo')}", f"g:lock:photo:{cid}", style="primary"),
                 styled_button(f"🔒 Lock Video {st('lock_video')}", f"g:lock:video:{cid}", style="primary")],
                [styled_button(f"📄 Doc {st('lock_document')}", f"g:lock:document:{cid}", style="primary"),
                 styled_button(f"🔗 Links {st('lock_links')}", f"g:lock:links:{cid}", style="primary")],
                [styled_button(f"☢ Nuke {st('anti_nuke')}", f"g:toggle:anti_nuke:{cid}", style="danger"),
                 styled_button(f"🌙 Night {st('night_mode')}", f"g:night:{cid}", style="primary")],
                [styled_button("🐢 Slow 10s", f"g:slow:10:{cid}", style="primary"),
                 styled_button("🐢 Slow Off", f"g:slow:0:{cid}", style="danger")],
                [styled_button(f"📥 Join {gget(cid, 'join_request_mode', 'manual')}", f"g:joinmode:{cid}", style="primary"),
                 styled_button("📊 Stats", f"g:stats:{cid}", style="primary")],
                [styled_button(f"🎯 Auto Join Accept: {auto_join}", f"g:autojoin:{cid}",
                               style="success" if auto_join == "OFF" else "danger")],
                [styled_button(f"🔢 Accept Limit: {gget(cid, 'auto_join_limit', 'Unlimited')}", f"g:autojoinlimit:{cid}", style="primary")],
                [styled_button("✏️ Set Custom Limit", f"g:autojoincustom:{cid}", style="primary")],
                [styled_button("🧩 Custom Command", f"g:setcmd:{cid}", style="primary")],
                [styled_button("🗓 Scheduler", f"g:sched:{cid}", style="primary")],
                [styled_button("🛡 Anti-Raid", f"g:antiraid:{cid}", style="primary"),
                 styled_button("⭐ Reputation", f"g:reputation:{cid}", style="primary")],
                [styled_button("⚰️ Graveyard", f"g:graveyard:{cid}", style="primary"),
                 styled_button("🚫 18+ Filter", f"g:adult_filter:{cid}", style="danger")],
                [styled_button("🔁 Anti-Forward", f"g:antiforward:{cid}", style="primary"),
                 styled_button("🧾 Delete Reason", f"g:delete_reason:{cid}", style="primary")],
                [styled_button("🗑 Tombstone", f"g:tombstone:{cid}", style="primary"),
                 styled_button("🤫 Whisper", f"g:whisper:{cid}", style="primary")],
                [styled_button("📌 Auto-Pin", f"g:autopin:{cid}", style="primary")],
                [styled_button(f"⏸ Pause {st('paused')}", f"g:pause:{cid}", style="danger"),
                 styled_button("▶️ Unpause", f"g:unpause:{cid}", style="success")],
                [styled_button("📡 Group Broadcast", f"g:broadcast:{cid}", style="success")],
                [styled_button("↩️ Back", "menu:group", style="danger"),
                 styled_button("🏠 Home", "menu:home", style="primary")],
            ]),
        )
        return

    # --- Generic toggle ---
    if kind == "toggle" and len(parts) >= 4:
        key = parts[2]
        try:
            cid = int(parts[3])
        except Exception:
            return
        if not await authorized_for_group(context.bot, user.id, cid):
            await safe_answer(query, "Not authorized.", show_alert=True); return
        cur = gget(cid, key, "off")
        gset(cid, key, "on" if cur != "on" else "off")
        log_action(user.id, f"grp_{key}", f"{cid}:{gget(cid, key)}")
        await safe_answer(query, f"{key}: {gget(cid, key).upper()}")
        await _route_callback(update, context, f"g:manage:{cid}")
        return

    # --- Auto Join Accept toggle ---
    if kind == "autojoin" and len(parts) >= 3:
        try:
            cid = int(parts[2])
        except Exception:
            return
        if not await authorized_for_group(context.bot, user.id, cid):
            await safe_answer(query, "Not authorized.", show_alert=True); return
        cur = get_auto_join_accept(cid, "group")
        new_state = 0 if cur else 1
        set_auto_join_accept(cid, "group", new_state, updated_by=user.id)
        log_action(user.id, "auto_join_accept_group", f"{cid}:{new_state}")
        await safe_answer(query, f"Auto Join Accept {'ON' if new_state else 'OFF'}")
        await _route_callback(update, context, f"g:manage:{cid}")
        return

    # --- Auto Join Accept custom limit ---
    if kind == "autojoincustom" and len(parts) >= 3:
        try:
            cid = int(parts[2])
        except Exception:
            await safe_answer(query, "Invalid group.", show_alert=True); return
        if not await authorized_for_group(context.bot, user.id, cid):
            await safe_answer(query, "Not authorized.", show_alert=True); return
        PENDING[user.id] = {"action": "autojoin_custom_limit", "chat_id": cid,
                            "chat_scope": "private"}
        await safe_edit_or_send(
            update, context,
            panel("Custom Auto Join Limit",
                  "<tg-emoji emoji-id=\"6064454772109346955\">🛵</tg-emoji> Send a positive whole number, for example 250.",
                  "<tg-emoji emoji-id=\"6061973170070489249\">🙅‍♀️</tg-emoji> To use Unlimited, send: Unlimited",
                  "<tg-emoji emoji-id=\"6314174306821605245\">😠</tg-emoji> The limit applies to successful acceptances in this counter window."),
            InlineKeyboardMarkup([[styled_button("⛓ Cancel", f"g:manage:{cid}", style="danger")]]),
        )
        return

    # --- Auto Join Accept limit cycle ---
    if kind == "autojoinlimit" and len(parts) >= 3:
        try:
            cid = int(parts[2])
        except Exception:
            return
        if not await authorized_for_group(context.bot, user.id, cid):
            await safe_answer(query, "Not authorized.", show_alert=True); return
        options = ["10", "25", "50", "100", "Unlimited"]
