        try:
            new_value = options[(options.index(current) + 1) % len(options)]
        except ValueError:
            new_value = "10"
        gset(cid, "auto_join_limit", new_value)
        # Start a fresh accepted-count window when the limit is changed.
        gset(cid, "auto_join_accepted_count", "0")
        gset(cid, "auto_join_limit_started", now_ist().isoformat())
        await safe_answer(query, f"Auto Join Accept limit: {new_value}", show_alert=True)
        await _route_callback(update, context, f"g:manage:{cid}")
        return

