def consume_post_slot(channel_id: int, user_id: int, limit: int,
                      window_hours: int = 24) -> Tuple[bool, int, datetime]:
    """Atomic per-day (midnight IST reset) slot consumption."""
    now = now_ist()
    day_key = quota_day_key(now)
    next_midnight = (now + timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
    with db() as c:
        row = c.execute(
            "SELECT count FROM channel_post_counts WHERE channel_id=? AND user_id=? AND day=?",
            (channel_id, user_id, day_key),
        ).fetchone()
        cur = int(row["count"] or 0) if row else 0
        if cur >= limit:
            return False, cur, next_midnight
        new = cur + 1
        if row is None:
            c.execute(
                "INSERT INTO channel_post_counts(channel_id,user_id,day,count,window_start) "
                "VALUES(?,?,?,?,?)",
                (channel_id, user_id, day_key, new, now.isoformat()),
            )
        else:
            c.execute(
                "UPDATE channel_post_counts SET count=? WHERE channel_id=? AND user_id=? AND day=?",
                (new, channel_id, user_id, day_key),
            )
        return True, new, next_midnight


def consume_channel_delay(channel_id: int, admin_user_id: int,
                          delay_seconds: int) -> Tuple[bool, float]:
    now = now_ist()
    with db() as c:
        row = c.execute(
            "SELECT cooldown_until FROM channel_delay_cooldowns "
            "WHERE channel_id=? AND admin_user_id=?",
            (channel_id, admin_user_id),
        ).fetchone()
        cd = None
        if row and row["cooldown_until"]:
            try:
                cd = datetime.fromisoformat(row["cooldown_until"])
                if cd.tzinfo is None:
                    cd = cd.replace(tzinfo=IST)
            except Exception:
                cd = None
        if cd and now < cd:
            return False, (cd - now).total_seconds()
        new_until = now + timedelta(seconds=max(1, int(delay_seconds)))
        c.execute(
            "INSERT INTO channel_delay_cooldowns(channel_id,admin_user_id,last_post_at,cooldown_until) "
            "VALUES(?,?,?,?) ON CONFLICT(channel_id,admin_user_id) DO UPDATE SET "
            "last_post_at=excluded.last_post_at, cooldown_until=excluded.cooldown_until",
            (channel_id, admin_user_id, now.isoformat(), new_until.isoformat()),
        )
        return True, 0.0


async def _enforce_channel_delay(update, context, chat, post, user_id: int,
                                 username: str, delay_cfg: Dict[str, Any]) -> None:
    channel_id = chat.id
    delay_seconds = max(1, int(delay_cfg.get("delay_seconds") or 300))
    allowed, remaining = consume_channel_delay(channel_id, user_id, delay_seconds)
    if allowed:
        try:
            schedule_channel_message_deletion(context, channel_id, post.message_id,
                                              _post_time_ist(post), created_by=user_id)
        except Exception as e:
            log.warning("delay sched: %s", e)
        return
    try:
        await post.delete()
    except Exception as e:
        log.warning("delay delete: %s", e)
        return
    ch_name = html_escape(chat.title or str(channel_id))
    mention = f"@{html_escape(username)}" if username and username != "Unknown" else f"<code>{user_id}</code>"
    text = panel(
        "Delay Active",
        f"🏛 " + sb("Channel") + f" ➜ {ch_name}",
        f"🪪 " + sb("Poster") + f" ➜ {mention}",
        f"⏳ " + sb("Available after") + f" ➜ {format_remaining_delay(remaining)}",
        f"⏱ " + sb("Configured") + f" ➜ {format_remaining_delay(delay_seconds)}",
        "<tg-emoji emoji-id=\"6062180698595263993\">🤩</tg-emoji> " + sb("Please wait until your cooldown expires."),
    )
    try:
        notice = await send_section_banner(context.bot, channel_id, "delay", caption=text)
        if context.job_queue and notice:
            context.job_queue.run_once(
                _delete_notice_job, when=10,
                data={"chat_id": channel_id, "message_id": notice.message_id},
                name=f"chdelay_{channel_id}_{notice.message_id}",
            )
    except Exception as e:
        log.warning("delay notice: %s", e)


