def add_channel_word(channel_id: int, word: str) -> None:
    with db() as c:
        c.execute("INSERT OR IGNORE INTO channel_words(channel_id, word) VALUES(?,?)",
                  (channel_id, word.lower().strip()))


def list_channel_words(channel_id: int) -> List[str]:
    with db() as c:
        rows = c.execute("SELECT word FROM channel_words WHERE channel_id=? ORDER BY word",
                         (channel_id,)).fetchall()
    return [r["word"] for r in rows]


def clear_channel_words(channel_id: int) -> None:
    with db() as c:
        c.execute("DELETE FROM channel_words WHERE channel_id=?", (channel_id,))


def remove_channel_word(channel_id: int, word: str) -> None:
    with db() as c:
        c.execute("DELETE FROM channel_words WHERE channel_id=? AND word=?",
                  (channel_id, word.lower().strip()))


def get_channel_notice(channel_id: int, key: str, default: str = "") -> str:
    with db() as c:
        r = c.execute(
            "SELECT body, enabled FROM channel_notices WHERE channel_id=? AND notice_key=?",
            (channel_id, key),
        ).fetchone()
        if r and int(r["enabled"] or 0) == 1 and r["body"]:
            return r["body"]
        if r and int(r["enabled"] or 0) == 0:
            return ""
    return default or ""


def set_channel_notice(channel_id: int, key: str, body: str, enabled: int = 1) -> None:
    with db() as c:
        c.execute(
            "INSERT INTO channel_notices(channel_id,notice_key,enabled,body,updated_at) "
            "VALUES(?,?,?,?,?) ON CONFLICT(channel_id,notice_key) DO UPDATE SET "
            "body=excluded.body, enabled=excluded.enabled, updated_at=excluded.updated_at",
            (channel_id, key, enabled, body, now_ist().isoformat()),
        )


