# Every allowed emoji is in the default random pool.
DEFAULT_REACTION_POOL = sorted(ALLOWED_REACTION_EMOJIS)


def _clean_reaction_pool(value: Any) -> List[str]:
    if not value:
        return []
    raw = list(value) if isinstance(value, (list, tuple, set)) else str(value).replace(",", " ").split()
    out = []
    for item in raw:
        e = str(item).strip()
        if (e in ALLOWED_REACTION_EMOJIS or re.fullmatch(r"custom:[0-9]{5,30}", e)) and e not in out:
            out.append(e)
    return out


def _reaction_tokens_from_message(message) -> List[str]:
    """Extract ordinary reaction emoji and premium/custom emoji IDs from a message."""
    text = (getattr(message, "text", None) or getattr(message, "caption", None) or "").strip()
    tokens = _clean_reaction_pool(text)
    for entity in (getattr(message, "entities", None) or getattr(message, "caption_entities", None) or []):
        if getattr(entity, "type", None) == "custom_emoji":
            custom_id = getattr(entity, "custom_emoji_id", None)
            if custom_id:
                token = f"custom:{custom_id}"
                if token not in tokens:
                    tokens.append(token)
    return tokens


def _reaction_label(token: str) -> str:
    return f"✨ Premium Emoji ({token.split(':', 1)[1]})" if str(token).startswith("custom:") else str(token)


def get_auto_reaction_cfg(channel_id: int) -> Dict[str, Any]:
    with db() as c:
        r = c.execute("SELECT * FROM channel_auto_reaction WHERE channel_id=?",
                      (channel_id,)).fetchone()
    if not r:
        return {"enabled": 0, "reaction_emoji": "<tg-emoji emoji-id=\"6064403966941202396\">🤩</tg-emoji>", "reaction_mode": "fixed",
                "reaction_pool": " ".join(DEFAULT_REACTION_POOL)}
    d = dict(r)
    d.setdefault("reaction_mode", "fixed")
    if not d.get("reaction_pool"):
        d["reaction_pool"] = " ".join(DEFAULT_REACTION_POOL)
    return d


