def set_auto_reaction_cfg(channel_id: int, enabled=None, reaction_emoji=None,
                          updated_by=None, reaction_mode=None,
                          reaction_pool=None) -> None:
    cfg = get_auto_reaction_cfg(channel_id)
    if enabled is not None:
        cfg["enabled"] = int(enabled)
    if reaction_emoji is not None:
        cfg["reaction_emoji"] = reaction_emoji
    if reaction_mode is not None:
        cfg["reaction_mode"] = "random" if str(reaction_mode).lower() == "random" else "fixed"
    if reaction_pool is not None:
        pool = _clean_reaction_pool(reaction_pool)
        if not pool:
            pool = DEFAULT_REACTION_POOL
        cfg["reaction_pool"] = " ".join(pool)
    with db() as c:
        c.execute(
            "INSERT INTO channel_auto_reaction(channel_id,enabled,reaction_emoji,reaction_mode,"
            "reaction_pool,updated_at,updated_by) VALUES(?,?,?,?,?,?,?) "
            "ON CONFLICT(channel_id) DO UPDATE SET enabled=excluded.enabled, "
            "reaction_emoji=excluded.reaction_emoji, reaction_mode=excluded.reaction_mode, "
            "reaction_pool=excluded.reaction_pool, updated_at=excluded.updated_at, "
            "updated_by=excluded.updated_by",
            (channel_id, cfg["enabled"], cfg["reaction_emoji"],
             cfg.get("reaction_mode", "fixed"), cfg.get("reaction_pool", ""),
             now_ist().isoformat(), updated_by),
        )


