def _emotion_pick(text: str) -> str:
    if not text:
        return "❤️"
    t = text.lower()
    if any(w in t for w in ("congrats", "congratulation", "happy", "win", "won", "🎉", "🎊", "celebrat", "birthday")):
        return "🎉"
    if any(w in t for w in ("sad", "died", "passed away", "loss", "rip", "😢", "tragedy", "heartbroken")):
        return "😢"
    if any(w in t for w in ("lol", "lmao", "haha", "funny", "😂", "🤣", "joke")):
        return "😂"
    if any(w in t for w in ("angry", "furious", "outrage", "🤬", "hate", "disgusting")):
        return "😡"
    if any(w in t for w in ("wow", "amazing", "incredible", "omg", "shock", "😮", "surprise")):
        return "🤯"
    if any(w in t for w in ("love", "❤️", "❤", "adorable", "cute", "😍")):
        return "❤️"
    if any(w in t for w in ("fire", "hot", "🔥", "lit", "banger")):
        return "🔥"
    if any(w in t for w in ("thanks", "thank you", "grateful", "🙏")):
        return "🙏"
    if any(w in t for w in ("clap", "bravo", "well done", "👏")):
        return "👏"
    if any(w in t for w in ("pray", "hope", "🤲")):
        return "🙏"
    return "❤️"


def _choose_auto_reaction(cfg: Dict[str, Any], text: str = "",
                          emotion_on: bool = False) -> str:
    if emotion_on:
        return _emotion_pick(text)
    pool = _clean_reaction_pool(cfg.get("reaction_pool")) or DEFAULT_REACTION_POOL
    if str(cfg.get("reaction_mode") or "fixed").lower() == "random" and len(pool) >= 2:
        return random.choice(pool)
    return cfg.get("reaction_emoji") or (pool[0] if pool else "❤️")


async def apply_auto_reaction(bot, channel_id: int, message_id: int,
                              text: str = "") -> None:
    cfg = get_auto_reaction_cfg(channel_id)
    if not cfg.get("enabled"):
        return
    emotion_on = get_emotion_react_enabled(channel_id)
    emoji = _choose_auto_reaction(cfg, text, emotion_on)
    try:
        if str(emoji).startswith("custom:"):
            from telegram import ReactionTypeCustomEmoji
            reaction_obj = ReactionTypeCustomEmoji(custom_emoji_id=str(emoji).split(":", 1)[1])
        else:
            reaction_obj = ReactionTypeEmoji(emoji)
        await bot.set_message_reaction(
            chat_id=channel_id, message_id=message_id,
            reaction=[reaction_obj], is_big=False,
        )
    except Exception as e:
        err = str(e)
        if "REACTION_INVALID" in err.upper() or "Reaction_invalid" in err:
            try:
                set_auto_reaction_cfg(channel_id, enabled=0)
            except Exception:
                pass
            log.warning("[AUTO_REACTION_DISABLED] ch=%s invalid=%s", channel_id, emoji)


