def _post_time_ist(post) -> datetime:
    pt = getattr(post, "date", None)
    if pt is None:
        return now_ist()
    if pt.tzinfo is None:
        return pt.replace(tzinfo=UTC).astimezone(IST)
    return pt.astimezone(IST)


async def channel_msg_delete_job(context: ContextTypes.DEFAULT_TYPE) -> None:
    data = (context.job.data or {}) if context.job else {}
    channel_id = data.get("channel_id")
    message_id = data.get("message_id")
    job_id = data.get("job_id")
    if not channel_id or not message_id:
        return
    status = "pending"
    try:
        mark_bot_delete(channel_id, message_id)
        await context.bot.delete_message(chat_id=channel_id, message_id=message_id)
        status = "done"
    except BadRequest as e:
        if "not found" in str(e).lower():
            status = "done"
    except (RetryAfter, TimedOut, NetworkError):
        pass
    except Exception as e:
        log.debug("chdel job: %s", e)
    if job_id:
        try:
            with db() as c:
                c.execute("UPDATE channel_message_delete_jobs SET status=?, updated_at=? WHERE job_id=?",
                          (status, now_ist().isoformat(), job_id))
        except Exception:
            pass


def schedule_channel_message_deletion(context, channel_id: int, message_id: int,
                                      post_time: datetime, created_by: int = 0) -> None:
    ds = get_delete_schedule(channel_id)
    ad = get_auto_delete(channel_id)
    deadlines = []
    sources = []
    if int(ds.get("enabled") or 0):
        deadlines.append(post_time + timedelta(seconds=int(ds.get("duration_seconds") or 86400)))
        sources.append("delete_schedule")
    if int(ad.get("enabled") or 0):
        deadlines.append(post_time + timedelta(seconds=int(ad.get("duration_seconds") or 86400)))
        sources.append("auto_delete")
    if not deadlines:
        return
    delete_at = min(deadlines)
    if delete_at.tzinfo is None:
        delete_at = delete_at.replace(tzinfo=IST)
    feature_source = "+".join(sources)
    now = now_ist()
    delay = max(1, int((delete_at - now).total_seconds()))
    job_id = None
    with db() as c:
        existing = c.execute(
            "SELECT job_id, status, delete_at FROM channel_message_delete_jobs "
            "WHERE channel_id=? AND message_id=?",
            (channel_id, message_id),
        ).fetchone()
        if existing and existing["status"] == "pending":
            try:
                old_at = datetime.fromisoformat(existing["delete_at"])
                if old_at.tzinfo is None:
                    old_at = old_at.replace(tzinfo=IST)
                if delete_at >= old_at:
                    return
            except Exception:
                pass
            c.execute(
                "UPDATE channel_message_delete_jobs SET delete_at=?, feature_source=?, "
                "updated_at=? WHERE job_id=?",
                (delete_at.isoformat(), feature_source, now.isoformat(), existing["job_id"]),
            )
            job_id = existing["job_id"]
            if context and getattr(context, "job_queue", None):
                for job in context.job_queue.get_jobs_by_name(f"chdel_{channel_id}_{message_id}"):
                    try:
                        job.schedule_removal()
                    except Exception:
                        pass
        else:
            c.execute(
                "INSERT INTO channel_message_delete_jobs(channel_id,message_id,created_at,"
                "delete_at,feature_source,status,created_by,updated_at) "
                "VALUES(?,?,?,?,?,'pending',?,?) ON CONFLICT(channel_id,message_id) DO UPDATE SET "
                "delete_at=excluded.delete_at, feature_source=excluded.feature_source, "
                "status='pending', updated_at=excluded.updated_at",
                (channel_id, message_id, post_time.isoformat(), delete_at.isoformat(),
                 feature_source, created_by, now.isoformat()),
            )
            row = c.execute(
                "SELECT job_id FROM channel_message_delete_jobs WHERE channel_id=? AND message_id=?",
                (channel_id, message_id),
            ).fetchone()
            job_id = row["job_id"] if row else None
    if context and getattr(context, "job_queue", None) and job_id:
        context.job_queue.run_once(
            channel_msg_delete_job,
            when=delay,
            data={"channel_id": channel_id, "message_id": message_id, "job_id": job_id},
            name=f"chdel_{channel_id}_{message_id}",
        )


async def backfill_channel_deletion_jobs(context, channel_id: int) -> Tuple[int, int]:
    """When Auto Delete / Delete Schedule is enabled for a channel, scan the
    channel history and schedule deletion for existing posts.
    Returns (scheduled, skipped).

    Prefers Pyrogram (full history) when MTProto session is configured;
    otherwise falls back to channel_seen_messages (posts the bot has observed)."""
    ds = get_delete_schedule(channel_id)
    ad = get_auto_delete(channel_id)
    durations = []
    if int(ds.get("enabled") or 0):
        durations.append(int(ds.get("duration_seconds") or 86400))
    if int(ad.get("enabled") or 0):
        durations.append(int(ad.get("duration_seconds") or 86400))
    if not durations:
        return 0, 0
    duration = min(durations)

    posts: List[Tuple[int, datetime]] = []

    if MT_PROTO_API_ID and MT_PROTO_API_HASH and MT_PROTO_SESSION_STRING:
        client = None
        try:
            from pyrogram import Client
            client = Client(
                "rehan_backfill",
                api_id=int(MT_PROTO_API_ID),
                api_hash=str(MT_PROTO_API_HASH),
                session_string=str(MT_PROTO_SESSION_STRING),
                in_memory=True,
            )
            await client.start()
            async for m in client.get_chat_history(channel_id, limit=500):
                dt = getattr(m, "date", None)
                if dt is None:
                    continue
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=UTC)
                posts.append((int(m.id), dt.astimezone(IST)))
        except Exception as e:
            log.warning("backfill pyrogram failed ch=%s: %s", channel_id, e)
        finally:
            if client is not None:
                try:
                    await client.stop()
                except Exception:
                    pass

    if not posts:
        with db() as c:
            rows = c.execute(
                "SELECT message_id, seen_at FROM channel_seen_messages "
                "WHERE channel_id=? ORDER BY message_id DESC LIMIT 500",
                (channel_id,),
            ).fetchall()
        for r in rows:
            try:
                dt = datetime.fromisoformat(r["seen_at"])
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=IST)
                posts.append((int(r["message_id"]), dt))
            except Exception:
                pass

    if not posts:
        return 0, 0

    now = now_ist()
    scheduled = 0
    skipped = 0
    for mid, post_dt in posts:
        try:
            delete_at = post_dt + timedelta(seconds=duration)
            if delete_at.tzinfo is None:
                delete_at = delete_at.replace(tzinfo=IST)
            delay = (delete_at - now).total_seconds()
            if delay < 1:
                delay = 5
                delete_at = now + timedelta(seconds=5)

            job_id = None
            with db() as c:
                existing = c.execute(
                    "SELECT job_id, status FROM channel_message_delete_jobs "
                    "WHERE channel_id=? AND message_id=?",
                    (channel_id, mid),
                ).fetchone()
                if existing and existing["status"] == "done":
                    skipped += 1
                    continue
                if existing and existing["status"] == "pending":
                    c.execute(
                        "UPDATE channel_message_delete_jobs SET delete_at=?, feature_source=?, updated_at=? "
                        "WHERE job_id=?",
                        (delete_at.isoformat(), "backfill", now.isoformat(), existing["job_id"]),
                    )
                    job_id = existing["job_id"]
                else:
                    c.execute(
                        "INSERT INTO channel_message_delete_jobs"
                        "(channel_id,message_id,created_at,delete_at,feature_source,status,created_by,updated_at) "
                        "VALUES(?,?,?,?,?,'pending',?,?) "
                        "ON CONFLICT(channel_id,message_id) DO UPDATE SET "
                        "delete_at=excluded.delete_at, feature_source=excluded.feature_source, "
                        "status='pending', updated_at=excluded.updated_at",
                        (channel_id, mid, post_dt.isoformat(), delete_at.isoformat(),
                         "backfill", 0, now.isoformat()),
                    )
                    row = c.execute(
                        "SELECT job_id FROM channel_message_delete_jobs "
                        "WHERE channel_id=? AND message_id=?",
                        (channel_id, mid),
                    ).fetchone()
                    job_id = row["job_id"] if row else None

            if job_id and context and getattr(context, "job_queue", None):
                context.job_queue.run_once(
                    channel_msg_delete_job,
                    when=max(1, int(delay)),
                    data={"channel_id": channel_id, "message_id": mid, "job_id": job_id},
                    name=f"chdel_{channel_id}_{mid}",
                )
            scheduled += 1
        except Exception as e:
            log.warning("backfill job ch=%s mid=%s: %s", channel_id, mid, e)
            skipped += 1
    return scheduled, skipped


async def channel_delete_watchdog(context: ContextTypes.DEFAULT_TYPE) -> None:
    try:
        with db() as c:
            rows = c.execute(
                "SELECT job_id, channel_id, message_id, delete_at FROM channel_message_delete_jobs "
                "WHERE status='pending' AND delete_at <= ? ORDER BY delete_at ASC LIMIT 100",
                (now_ist().isoformat(),),
            ).fetchall()
        for row in rows:
            try:
                mark_bot_delete(row["channel_id"], row["message_id"])
                await context.bot.delete_message(chat_id=row["channel_id"],
                                                 message_id=row["message_id"])
                with db() as c:
                    c.execute("UPDATE channel_message_delete_jobs SET status='done', updated_at=? WHERE job_id=?",
                              (now_ist().isoformat(), row["job_id"]))
            except Exception:
                pass
    except Exception:
        log.exception("chdel watchdog")


