def mirror_channel_message(channel_id: int, message: Message) -> None:
    """Save a channel post so Report Protection can restore, and Delete-All can verify."""
    try:
        media_type = None
        file_id = None
        text_content = None
        caption = None
        if message.photo:
            media_type, file_id = "photo", message.photo[-1].file_id
            caption = message.caption or ""
        elif message.video:
            media_type, file_id = "video", message.video.file_id
            caption = message.caption or ""
        elif message.animation:
            media_type, file_id = "animation", message.animation.file_id
            caption = message.caption or ""
        elif message.document:
            media_type, file_id = "document", message.document.file_id
            caption = message.caption or ""
        elif message.audio:
            media_type, file_id = "audio", message.audio.file_id
            caption = message.caption or ""
        elif message.voice:
            media_type, file_id = "voice", message.voice.file_id
            caption = message.caption or ""
        elif message.video_note:
            media_type, file_id = "video_note", message.video_note.file_id
        elif message.sticker:
            media_type, file_id = "sticker", message.sticker.file_id
        elif message.text:
            text_content = message.text

        with db() as c:
            c.execute(
                "INSERT OR REPLACE INTO channel_mirror(channel_id, message_id, media_type, file_id, "
                "text_content, caption, post_date, saved_at, restore_count) VALUES(?,?,?,?,?,?,?,?, "
                "COALESCE((SELECT restore_count FROM channel_mirror WHERE channel_id=? AND message_id=?), 0))",
                (
                    channel_id, message.message_id, media_type, file_id,
                    text_content, caption,
                    message.date.isoformat() if message.date else None,
                    now_ist().isoformat(),
                    channel_id, message.message_id,
                ),
            )
    except Exception as e:
        log.warning("mirror_channel_message failed: %s", e)


def get_mirror(channel_id: int, message_id: int):
    with db() as c:
        return c.execute(
            "SELECT * FROM channel_mirror WHERE channel_id=? AND message_id=?",
            (int(channel_id), int(message_id)),
        ).fetchone()


def bump_restore_count(channel_id: int, message_id: int) -> None:
    with db() as c:
        c.execute(
            "UPDATE channel_mirror SET restore_count = COALESCE(restore_count,0)+1 "
            "WHERE channel_id=? AND message_id=?",
            (int(channel_id), int(message_id)),
        )


async def try_restore_channel_post(bot, channel_id: int, message_id: int) -> bool:
    """Restore a deleted channel post from mirror. Returns True on success."""
    row = get_mirror(channel_id, message_id)
    if not row:
        return False
    media_type = row["media_type"]
    file_id = row["file_id"]
    text_content = row["text_content"]
    caption = row["caption"] or ""
    try:
        if media_type == "photo" and file_id:
            await bot.send_photo(channel_id, file_id, caption=caption or None)
        elif media_type == "video" and file_id:
            await bot.send_video(channel_id, file_id, caption=caption or None)
        elif media_type == "animation" and file_id:
            await bot.send_animation(channel_id, file_id, caption=caption or None)
        elif media_type == "document" and file_id:
            await bot.send_document(channel_id, file_id, caption=caption or None)
        elif media_type == "audio" and file_id:
            await bot.send_audio(channel_id, file_id, caption=caption or None)
        elif media_type == "voice" and file_id:
            await bot.send_voice(channel_id, file_id, caption=caption or None)
        elif media_type == "video_note" and file_id:
            await bot.send_video_note(channel_id, file_id)
        elif media_type == "sticker" and file_id:
            await bot.send_sticker(channel_id, file_id)
        elif text_content:
            await bot.send_message(channel_id, text_content)
        else:
            return False
        bump_restore_count(channel_id, message_id)
        return True
    except Exception as e:
        log.warning("restore failed channel=%s msg=%s: %s", channel_id, message_id, e)
        return False


