def record_best_hour(channel_id: int, views: int) -> None:
    h = now_ist().hour
    try:
        with db() as c:
            r = c.execute(
                "SELECT total_views, total_posts FROM best_hour_data WHERE channel_id=? AND hour_ist=?",
                (channel_id, h),
            ).fetchone()
            if r:
                c.execute(
                    "UPDATE best_hour_data SET total_views=total_views+?, total_posts=total_posts+1, "
                    "last_updated=? WHERE channel_id=? AND hour_ist=?",
                    (int(views or 0), now_ist().isoformat(), channel_id, h),
                )
            else:
                c.execute(
                    "INSERT INTO best_hour_data(channel_id,hour_ist,total_views,total_posts,last_updated) "
                    "VALUES(?,?,?,1,?)",
                    (channel_id, h, int(views or 0), now_ist().isoformat()),
                )
    except Exception as e:
        log.debug("best_hour: %s", e)


def _channel_owner_id(channel_id: int) -> Optional[int]:
    with db() as c:
        r = c.execute("SELECT added_by_user_id FROM managed_channels WHERE channel_id=?",
                      (channel_id,)).fetchone()
    try:
        return int(r["added_by_user_id"]) if r and r["added_by_user_id"] else None
    except Exception:
        return None


async def per_post_analytics_dm_job(context: ContextTypes.DEFAULT_TYPE) -> None:
    data = context.job.data or {}
    channel_id = data.get("channel_id")
    message_id = data.get("message_id")
    if not channel_id or not message_id:
        return
    owner_id = _channel_owner_id(channel_id)
    if not owner_id:
        return
    with db() as c:
        r = c.execute(
            "SELECT owner_dm_sent FROM post_analytics WHERE channel_id=? AND message_id=?",
            (channel_id, message_id),
        ).fetchone()
        if not r or int(r["owner_dm_sent"] or 0):
            return
    views = 0
    try:
        views = await context.bot.get_chat_member_count(channel_id)
    except Exception:
        pass
    record_best_hour(channel_id, views)
    text = panel(
        "Post Analytics",
        f"📡 " + sb("Channel") + f" ➜ <code>{channel_id}</code>",
        f"📨 " + sb("Post") + f" ➜ <code>{message_id}</code>",
        f"👥 " + sb("Subs at check") + f" ➜ {views}",
        "<tg-emoji emoji-id=\"6061942014377724267\">🤩</tg-emoji> " + sb("Tap button for deeper stats."),
    )
    kb = InlineKeyboardMarkup([
        [styled_button("👑 Owner Analytics", f"c:analytics:{channel_id}:{message_id}", style="primary")],
    ])
    try:
        await context.bot.send_message(owner_id, text, parse_mode=ParseMode.HTML, reply_markup=kb)
        with db() as c:
            c.execute(
                "UPDATE post_analytics SET owner_dm_sent=1, views_at_24h=? WHERE channel_id=? AND message_id=?",
                (views, channel_id, message_id),
            )
    except Exception as e:
        log.debug("analytics DM: %s", e)


