try:
    from PIL import Image, ImageDraw, ImageFont, ImageFilter
    _PIL_OK = True
except Exception:
    _PIL_OK = False


def get_post_card_cfg(channel_id: int) -> Dict[str, Any]:
    with db() as c:
        r = c.execute("SELECT * FROM post_card_config WHERE channel_id=?", (channel_id,)).fetchone()
    if not r:
        return {"enabled": 0, "style": "minimal", "color": "#1f6feb"}
    return {"enabled": int(r["enabled"] or 0), "style": r["style"] or "minimal",
            "color": r["color"] or "#1f6feb"}


def set_post_card_cfg(channel_id: int, enabled=None, style=None, color=None) -> None:
    cur = get_post_card_cfg(channel_id)
    if enabled is not None:
        cur["enabled"] = int(enabled)
    if style is not None and style in ("minimal", "bold", "dark", "gradient"):
        cur["style"] = style
    if color is not None and re.match(r"^#[0-9a-fA-F]{6}$", color):
        cur["color"] = color
    with db() as c:
        c.execute(
            "INSERT INTO post_card_config(channel_id,enabled,style,color,updated_at) "
            "VALUES(?,?,?,?,?) ON CONFLICT(channel_id) DO UPDATE SET "
            "enabled=excluded.enabled, style=excluded.style, color=excluded.color, "
            "updated_at=excluded.updated_at",
            (channel_id, cur["enabled"], cur["style"], cur["color"], now_ist().isoformat()),
        )


def _hex_to_rgb(h: str) -> Tuple[int, int, int]:
    h = h.lstrip("#")
    return int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)


def _make_post_card(text: str, channel_title: str, style: str,
                    color_hex: str, brand: str = "") -> Optional[bytes]:
    if not _PIL_OK:
        return None
    try:
        W, H = 1080, 1080
        img = Image.new("RGB", (W, H), (15, 15, 20))
        d = ImageDraw.Draw(img)
        base = _hex_to_rgb(color_hex or "#1f6feb")
        if style == "gradient":
            for y in range(H):
                t = y / H
                r = int(base[0] * (1 - t) + 10 * t)
                g = int(base[1] * (1 - t) + 10 * t)
                b = int(base[2] * (1 - t) + 40 * t)
                d.line([(0, y), (W, y)], fill=(r, g, b))
        elif style == "dark":
            d.rectangle([(0, 0), (W, H)], fill=(10, 10, 15))
            d.rectangle([(0, 0), (W, 12)], fill=base)
        elif style == "bold":
            d.rectangle([(0, 0), (W, H)], fill=base)
        else:
            d.rectangle([(0, 0), (W, H)], fill=(245, 245, 245))
            d.rectangle([(0, 0), (14, H)], fill=base)

        def _font(size: int):
            candidates = [
                "/system/fonts/NotoSans-Regular.ttf",
                "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
                "/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf",
            ]
            for p in candidates:
                if os.path.exists(p):
                    try:
                        return ImageFont.truetype(p, size)
                    except Exception:
                        continue
            return ImageFont.load_default()

        quote_color = base if style == "minimal" else (255, 255, 255)
        try:
            d.text((60, 40), "“", font=_font(180), fill=quote_color)
        except Exception:
            pass

        body_font = _font(46)
        fg = (25, 25, 30) if style == "minimal" else (245, 245, 250)
        margin = 100
        max_w = W - margin * 2
        y = 280
        for raw_line in (text or "").split("\n"):
            words = raw_line.split(" ")
            line = ""
            for w in words:
                test = (line + " " + w).strip()
                try:
                    tw = d.textlength(test, font=body_font)
                except Exception:
                    tw = len(test) * 22
                if tw > max_w and line:
                    d.text((margin, y), line, font=body_font, fill=fg)
                    y += 62
                    line = w
                    if y > H - 220:
                        break
                else:
                    line = test
            if y > H - 220:
                break
            if line:
                d.text((margin, y), line, font=body_font, fill=fg)
                y += 62
            if y > H - 220:
                break

        foot_font = _font(32)
        footer_left = channel_title[:40]
        footer_right = brand or "REHAN CODEX"
        foot_color = (80, 80, 90) if style == "minimal" else (230, 230, 240)
        d.text((margin, H - 140), footer_left, font=foot_font, fill=foot_color)
        try:
            fr_w = d.textlength(footer_right, font=foot_font)
        except Exception:
            fr_w = len(footer_right) * 16
        d.text((W - margin - fr_w, H - 140), footer_right, font=foot_font, fill=foot_color)

        buf = io.BytesIO()
        img.save(buf, "PNG", optimize=True)
        return buf.getvalue()
    except Exception as e:
        log.warning("post_card: %s", e)
        return None


