def get_stale_cfg(channel_id: int) -> Dict[str, Any]:
    with db() as c:
        r = c.execute("SELECT * FROM stale_cleanup_config WHERE channel_id=?",
                      (channel_id,)).fetchone()
    if not r:
        return {"enabled": 0, "age_days": 7, "min_views": 100}
    return {"enabled": int(r["enabled"] or 0),
            "age_days": int(r["age_days"] or 7),
            "min_views": int(r["min_views"] or 100)}


def set_stale_cfg(channel_id: int, enabled=None, age_days=None, min_views=None) -> None:
    cur = get_stale_cfg(channel_id)
    if enabled is not None:
        cur["enabled"] = int(enabled)
    if age_days is not None:
        cur["age_days"] = max(1, min(int(age_days), 90))
    if min_views is not None:
        cur["min_views"] = max(1, int(min_views))
    with db() as c:
        c.execute(
            "INSERT INTO stale_cleanup_config(channel_id,enabled,age_days,min_views,updated_at) "
            "VALUES(?,?,?,?,?) ON CONFLICT(channel_id) DO UPDATE SET "
            "enabled=excluded.enabled, age_days=excluded.age_days, min_views=excluded.min_views, "
            "updated_at=excluded.updated_at",
            (channel_id, cur["enabled"], cur["age_days"], cur["min_views"], now_ist().isoformat()),
        )


async def stale_cleanup_job(context: ContextTypes.DEFAULT_TYPE) -> None:
    try:
        with db() as c:
            rows = c.execute("SELECT * FROM stale_cleanup_config WHERE enabled=1").fetchall()
        for r in rows:
            cid = int(r["channel_id"])
            age = int(r["age_days"] or 7)
            cutoff = now_ist() - timedelta(days=age)
            with db() as c:
                jobs = c.execute(
                    "SELECT j.job_id, j.message_id FROM channel_message_delete_jobs j "
                    "LEFT JOIN channel_mirror m ON m.channel_id=j.channel_id AND m.message_id=j.message_id "
                    "WHERE j.channel_id=? AND j.status='pending' "
                    "AND COALESCE(m.post_date, j.created_at) < ?",
                    (cid, cutoff.isoformat()),
                ).fetchall()
            for j in jobs:
                try:
                    mark_bot_delete(cid, int(j["message_id"]))
                    await context.bot.delete_message(chat_id=cid, message_id=int(j["message_id"]))
                    with db() as c:
                        c.execute("UPDATE channel_message_delete_jobs SET status='done' WHERE job_id=?",
                                  (j["job_id"],))
                except Exception:
                    pass
    except Exception:
        log.exception("stale cleanup")


async def mirror_channel_post(context, channel_id: int, post) -> None:
    with db() as c:
        r = c.execute("SELECT value FROM channel_flags WHERE channel_id=? AND key='mirror_target'",
                      (channel_id,)).fetchone()
    if not r or not r["value"]:
        return
    try:
        target = int(r["value"])
    except Exception:
        return
    try:
        sent = await context.bot.copy_message(chat_id=target, from_chat_id=channel_id,
                                              message_id=post.message_id)
        if sent:
            BROADCAST_SKIP_PAUSE.add((target, sent.message_id))
    except Exception as e:
        log.debug("mirror: %s", e)


# Celebrate the channel's current size once when milestone tracking first sees it,
# then celebrate each crossed 100-member threshold. Every 500 is a bigger celebration.
_MILESTONE_STEP = 100
_BIG_MILESTONE_STEP = 500


def _milestone_plain_len(markup: str) -> int:
    """Length Telegram will count for a caption: tags removed, entities decoded, UTF-16 units."""
    import html as _html
    plain = _html.unescape(re.sub(r"<[^>]+>", "", markup or ""))
    return len(plain.encode("utf-16-le")) // 2


def _milestone_restore_baseline(channel_id: int, count: int) -> Optional[int]:
    """If the first celebration was already sent, return a safe baseline instead of repeating it."""
    try:
        if not cflag(channel_id, "milestone_initial_sent_at", ""):
            return None
        best = 0
        try:
            best = int(cflag(channel_id, "milestone_last_sent", "") or 0)
        except (TypeError, ValueError):
            best = 0
        with db() as c:
            r = c.execute(
                "SELECT MAX(milestone) AS m FROM subscriber_milestones "
                "WHERE channel_id=? AND celebrated_at IS NOT NULL AND celebrated_at<>''",
                (int(channel_id),),
            ).fetchone()
        if r and r["m"]:
            best = max(best, int(r["m"]))
        return best if best > 0 else int(count)
    except Exception:
        return None


async def _send_milestone_congratulations(bot, channel_id: int, caption: str, milestone_value: int,
                                          member_count: Optional[int] = None) -> Optional[Message]:
    """Post the milestone announcement for the actual channel with a banner/logo.

    Banner order: configured milestone banner -> the channel's own profile photo ->
    configured global banner -> the bot's profile photo -> plain text.
    """
    # ---- actual channel details (title / public link / existing invite link) ----
    title = ""
    username = ""
    invite = ""
    channel_photo_id = None
    try:
        chat = await bot.get_chat(channel_id)
        title = (getattr(chat, "title", None) or "").strip()
        username = (getattr(chat, "username", None) or "").strip().lstrip("@")
        invite = (getattr(chat, "invite_link", None) or "").strip()
        photo = getattr(chat, "photo", None)
        channel_photo_id = getattr(photo, "big_file_id", None) if photo else None
    except Exception as e:
        log.debug("milestone channel details unavailable for %s: %s", channel_id, e)
    if not title or not username:
        try:
            with db() as c:
                row = c.execute("SELECT title, username FROM managed_channels WHERE channel_id=?",
                                (int(channel_id),)).fetchone()
            if row:
                title = title or (row["title"] or "").strip()
                username = username or (row["username"] or "").strip().lstrip("@")
        except Exception:
            pass
    title = title or "Channel"
    if username:
        channel_link = f"https://t.me/{username}"
    elif invite.startswith("http"):
        channel_link = invite          # an existing invite link only; never invent one
    else:
        channel_link = ""

    # ---- display counts as the lower 50-member band (e.g. 406 -> 400+) ----
    def _member_band(value: int) -> str:
        value = max(0, int(value))
        band = (value // 50) * 50
        return f"{band:,}+"

    milestone = _member_band(milestone_value)
    try:
        members = _member_band(await bot.get_chat_member_count(channel_id))
    except Exception:
        members = _member_band(member_count) if member_count else milestone

    if channel_link:
        safe_link = html_escape(channel_link).replace('"', "&quot;")
        channel_mention = f'<a href="{safe_link}">{html_escape(title)}</a>'
    else:
        channel_mention = html_escape(title)
    manager_mention = f'<a href="{BOT_PROMO_URL}">@RehanManage_Bot</a>'
    dev_name = (DEV_USERNAME or "@RehanCodex").strip().lstrip("@") or "RehanCodex"
    dev_mention = f'<a href="https://t.me/{html_escape(dev_name)}">@{html_escape(dev_name)}</a>'

    # Every paragraph is its own blockquote, separated by a blank line.
    paragraphs = [
        '<tg-emoji emoji-id="6226302114918828194">🤩</tg-emoji> <tg-emoji emoji-id="6226395994313983714">🤩</tg-emoji> 𝑪𝑶𝑵𝑮𝑹𝑨𝑻𝑼𝑳𝑨𝑻𝑰𝑶𝑵𝑺! <tg-emoji emoji-id="6228821207727212391">🤩</tg-emoji>',
        f'🏆 𝒀𝑶𝑼𝑹 𝑪𝑯𝑨𝑵𝑵𝑬𝑳 𝑯𝑨𝑺 𝑹𝑬𝑨𝑪𝑯𝑬𝑫 {html_escape(milestone)} 𝑴𝑬𝑴𝑩𝑬𝑹𝑺!',
        f'📡 𝑪𝒉𝒂𝒏𝒏𝒆𝒍: {channel_mention}',
        f'👥 𝑪𝒖𝒓𝒓𝒆𝒏𝒕 𝑴𝒆𝒎𝒃𝒆𝒓𝒔: {html_escape(members)}',
        '<tg-emoji emoji-id="6226428825043994471">🤩</tg-emoji> 𝑻𝒉𝒂𝒏𝒌 𝒚𝒐𝒖 𝒇𝒐𝒓 𝒃𝒆𝒊𝒏𝒈 𝒑𝒂𝒓𝒕 𝒐𝒇 𝒕𝒉𝒊𝒔 𝒋𝒐𝒖𝒓𝒏𝒆𝒚! 𝑲𝒆𝒆𝒑 𝒈𝒓𝒐𝒘𝒊𝒏𝒈 𝒂𝒏𝒅 𝒂𝒄𝒉𝒊𝒆𝒗𝒊𝒏𝒈 𝒏𝒆𝒘 𝒎𝒊𝒍𝒆𝒔𝒕𝒐𝒏𝒆𝒔.',
        f'👑 𝑪𝒉𝒂𝒏𝒏𝒆𝒍 𝑴𝒂𝒏𝒂𝒈𝒆𝒓: {manager_mention} — 𝑨𝒍𝒘𝒂𝒚𝒔 𝑷𝒓𝒐𝒕𝒆𝒄𝒕 &amp; 𝑴𝒂𝒏𝒂𝒈𝒆',
        f'🜲 𝑫𝒆𝒗 {dev_mention}',
    ]
    message_html = "\n\n".join(f"<blockquote>{p}</blockquote>" for p in paragraphs)
    fits_caption = _milestone_plain_len(message_html) <= 1024

    # ---- banner candidates, best first ----
    candidates: List[Tuple[str, str]] = []   # (media_type, file_id or "__dl__:<file_id>")
    try:
        with db() as c:
            r = c.execute("SELECT media_type, file_id FROM section_banners WHERE section_key=?",
                          ("subscriber_milestone",)).fetchone()
        if r and r["file_id"]:
            candidates.append((r["media_type"] or "photo", r["file_id"]))
    except Exception as e:
        log.debug("milestone configured banner lookup failed: %s", e)
    if channel_photo_id:
        candidates.append(("photo", channel_photo_id))
        candidates.append(("photo", "__dl__:" + channel_photo_id))
    try:
        gfid = get_var("global_banner_file_id", "")
        if gfid:
            candidates.append((get_var("global_banner_media_type", "photo") or "photo", gfid))
    except Exception:
        pass
    bot_photo_loaded = False

    async def _send_media(kind: str, ref: str, cap: Optional[str]):
        if ref.startswith("__dl__:"):
            tg_file = await bot.get_file(ref[7:])
            ref = bytes(await tg_file.download_as_bytearray())
            kind = "photo"
        kw = {"chat_id": channel_id}
        if cap:
            kw.update(caption=cap, parse_mode=ParseMode.HTML)
        if kind == "video":
            return await bot.send_video(video=ref, **kw)
        if kind in ("animation", "gif"):
            return await bot.send_animation(animation=ref, **kw)
        return await bot.send_photo(photo=ref, **kw)

    idx = 0
    while idx < len(candidates) or not bot_photo_loaded:
        if idx >= len(candidates):
            # last resort image: the bot's own profile photo
            bot_photo_loaded = True
            try:
                me = await bot.get_me()
                pp = await bot.get_user_profile_photos(user_id=me.id, limit=1)
                if pp and pp.photos and pp.photos[0]:
                    candidates.append(("photo", pp.photos[0][-1].file_id))
            except Exception as e:
                log.debug("milestone bot-logo fallback unavailable: %s", e)
            if idx >= len(candidates):
                break
        kind, ref = candidates[idx]
        idx += 1
        try:
            if fits_caption:
                try:
                    return await _send_media(kind, ref, message_html)
                except BadRequest as e:
                    if "caption" not in str(e).lower():
                        raise
                    log.warning("milestone caption rejected for %s; sending banner and text separately", channel_id)
            sent_banner = await _send_media(kind, ref, None)
            # Caption too long: banner first, then the complete message separately.
            try:
                return await bot.send_message(chat_id=channel_id, text=message_html,
                                              parse_mode=ParseMode.HTML, disable_web_page_preview=True)
            except TimedOut:
                raise
            except Exception as e:
                log.warning("milestone text after banner failed for %s: %s; retrying once", channel_id, e)
                return await bot.send_message(chat_id=channel_id, text=message_html,
                                              parse_mode=ParseMode.HTML, disable_web_page_preview=True)
        except TimedOut:
            raise   # delivery unknown: do not try other candidates (would risk a duplicate)
        except Exception as e:
            log.warning("milestone banner send failed for %s (%s); trying next fallback: %s",
                        channel_id, ref[:12] if isinstance(ref, str) else "bytes", e)

    # No usable banner: send the complete announcement as text.
    return await bot.send_message(
        chat_id=channel_id, text=message_html, parse_mode=ParseMode.HTML,
        disable_web_page_preview=True,
    )


async def _check_subscriber_milestone_locked(context, channel_id: int) -> None:
    try:
        count = int(await context.bot.get_chat_member_count(channel_id))
    except Exception as e:
        log.debug("milestone count unavailable for %s: %s", channel_id, e)
        return

    # Guard: if same count was already celebrated in last 2 hours, skip
    last_count = cflag(channel_id, "milestone_last_count", "0")
    last_at = cflag(channel_id, "milestone_last_sent_at", "")
    try:
        if last_count == str(count) and last_at:
            from datetime import datetime as _dt, timedelta as _td
            _last_dt = _dt.fromisoformat(last_at)
            if _last_dt.tzinfo is None:
                _last_dt = _last_dt.replace(tzinfo=IST)
            if now_ist() - _last_dt < _td(hours=2):
                return
    except Exception:
        pass

    # Only post milestone notices for channels explicitly managed in this bot.
    try:
        with db() as c:
            managed = c.execute(
                "SELECT title FROM managed_channels WHERE channel_id=? "
                "AND COALESCE(status,'active')='active' AND COALESCE(enabled,1)=1",
                (int(channel_id),),
            ).fetchone()
        if not managed:
            return
        channel_title = (managed["title"] or "").strip()
    except Exception as e:
        log.debug("milestone managed-channel lookup failed for %s: %s", channel_id, e)
        return

    baseline_raw = cflag(channel_id, "milestone_baseline", "")
    if not baseline_raw:
        # If the first celebration was already sent, never repeat it (e.g. after a baseline reset).
        restored = _milestone_restore_baseline(channel_id, count)
        if restored is not None:
            set_cflag(channel_id, "milestone_baseline", str(restored))
            return
        # First check: congratulate the actual current count instead of incorrectly
        # announcing an old threshold such as 100 when the channel already has 200.
        # Set baseline EARLY to prevent duplicate sends if job re-fires
        set_cflag(channel_id, "milestone_baseline", str(count))
        set_cflag(channel_id, "milestone_initial_sent_at", now_ist().isoformat())

        big = count > 0 and count % _BIG_MILESTONE_STEP == 0
        title = (f"🏆 BIG MILESTONE — {count:,} SUBSCRIBERS!" if big
                 else f"🎉 FIRST CELEBRATION — {count:,} SUBSCRIBERS!")
        text = panel(
            title,
            f"📡 {sb('Channel')} ➜ {html_escape(channel_title or str(channel_id))}",
            f"👥 {sb('Current Members')} ➜ {count:,}",
            ("<tg-emoji emoji-id=\"6226313346258306844\">👋</tg-emoji> " + sb("An incredible milestone — thank you for growing together!")
             if big else "<tg-emoji emoji-id=\"6228518567151667249\">😠</tg-emoji> " + sb("Thanks for being part of this journey!")),
        )
        try:
            try:
                sent = await _send_milestone_congratulations(context.bot, channel_id, text, count,
                                                             member_count=count)
            except TimedOut:
                sent = True  # delivery unknown; do not retry and risk a duplicate
            if not sent:
                return
            set_cflag(channel_id, "milestone_last_count", str(count))
            set_cflag(channel_id, "milestone_last_sent_at", now_ist().isoformat())
            # Treat every already-reached 100-step as part of the baseline, so the
            # next run won't send a backlog of false/old celebrations.
            with db() as c:
                for reached in range(_MILESTONE_STEP, (count // _MILESTONE_STEP) * _MILESTONE_STEP + 1,
                                     _MILESTONE_STEP):
                    c.execute(
                        "INSERT INTO subscriber_milestones(channel_id,milestone,celebrated_at) "
                        "VALUES(?,?,?) ON CONFLICT(channel_id,milestone) DO NOTHING",
                        (int(channel_id), reached, now_ist().isoformat()),
                    )
        except Exception as e:
            log.warning("milestone initial post failed for %s; will retry: %s", channel_id, e)
        return

    try:
        baseline = max(0, int(baseline_raw))
    except (TypeError, ValueError):
        # Recover a damaged value safely: reset to current count with one first notice.
        set_cflag(channel_id, "milestone_baseline", "")
        return

    # Use absolute hundreds (300, 400, 500...) after the initial count. Do not
    # replay thresholds at/below the baseline, and only mark a threshold after a
    # successful Telegram send so timeouts don't permanently lose celebrations.
    next_threshold = ((baseline // _MILESTONE_STEP) + 1) * _MILESTONE_STEP
    try:
        last_sent = int(cflag(channel_id, "milestone_last_sent", "") or 0)
    except (TypeError, ValueError):
        last_sent = 0
    for milestone in range(next_threshold, (count // _MILESTONE_STEP) * _MILESTONE_STEP + 1,
                           _MILESTONE_STEP):
        with db() as c:
            prior = c.execute(
                "SELECT celebrated_at FROM subscriber_milestones WHERE channel_id=? AND milestone=?",
                (int(channel_id), milestone),
            ).fetchone()
        if prior and prior["celebrated_at"]:
            continue
        if milestone <= last_sent:
            continue

        is_big = milestone % _BIG_MILESTONE_STEP == 0
        title = (f"🏆 BIG MILESTONE — {milestone:,} SUBSCRIBERS!" if is_big
                 else f"🎉 {milestone:,} SUBSCRIBERS REACHED!")
        text = panel(
            title,
            f"📡 {sb('Channel')} ➜ {html_escape(channel_title or str(channel_id))}",
            f"🎯 {sb('Milestone')} ➜ {milestone:,}",
            f"👥 {sb('Current Members')} ➜ {count:,}",
            ("<tg-emoji emoji-id=\"6226543702534260736\">☕️</tg-emoji> " + sb("Amazing growth! Thank you for being part of this community!")
             if is_big else "<tg-emoji emoji-id=\"6316802577698654299\">👻</tg-emoji> " + sb("Thank you for helping this community grow!")),
        )
        try:
            try:
                sent = await _send_milestone_congratulations(context.bot, channel_id, text, milestone,
                                                             member_count=count)
            except TimedOut:
                sent = True  # delivery unknown; mark as sent so it is never duplicated
            if not sent:
                break
            with db() as c:
                c.execute(
                    "INSERT INTO subscriber_milestones(channel_id,milestone,celebrated_at) "
                    "VALUES(?,?,?) ON CONFLICT(channel_id,milestone) DO UPDATE SET "
                    "celebrated_at=excluded.celebrated_at",
                    (int(channel_id), milestone, now_ist().isoformat()),
                )
            # Persist the most recent successful threshold to prevent any legacy
            # baseline reset from making the bot replay old milestones.
            set_cflag(channel_id, "milestone_last_sent", str(milestone))
            set_cflag(channel_id, "milestone_last_count", str(count))
            set_cflag(channel_id, "milestone_last_sent_at", now_ist().isoformat())
            last_sent = milestone
        except Exception as e:
            log.warning("milestone post failed for %s at %s; will retry: %s",
                        channel_id, milestone, e)
            break


_MILESTONE_CHECK_LOCKS: Dict[int, asyncio.Lock] = {}


async def check_subscriber_milestone(context, channel_id: int) -> None:
    """Serialize milestone checks per channel to avoid duplicate celebrations."""
    cid = int(channel_id)
    lock = _MILESTONE_CHECK_LOCKS.get(cid)
    if lock is None:
        lock = asyncio.Lock()
        _MILESTONE_CHECK_LOCKS[cid] = lock
    async with lock:
        await _check_subscriber_milestone_locked(context, cid)


# ============================================================
#                    CUSTOM POST CREATOR
# ============================================================
async def publish_custom_post(context, draft_id: int) -> None:
    with db() as c:
        r = c.execute("SELECT * FROM custom_post_drafts WHERE id=?", (draft_id,)).fetchone()
        if not r or r["status"] != "draft":
            return
    cid = int(r["channel_id"])
    try:
        sent = None
        if r["media_type"] == "photo":
            sent = await context.bot.send_photo(cid, r["media_file_id"],
                                                caption=r["caption"] or None, parse_mode=ParseMode.HTML)
        elif r["media_type"] == "video":
            sent = await context.bot.send_video(cid, r["media_file_id"],
                                                caption=r["caption"] or None, parse_mode=ParseMode.HTML)
        elif r["media_type"] == "animation":
            sent = await context.bot.send_animation(cid, r["media_file_id"],
                                                    caption=r["caption"] or None, parse_mode=ParseMode.HTML)
        elif r["media_type"] == "document":
            sent = await context.bot.send_document(cid, r["media_file_id"],
                                                   caption=r["caption"] or None, parse_mode=ParseMode.HTML)
        else:
            sent = await context.bot.send_message(cid, r["text_body"] or "", parse_mode=ParseMode.HTML)
        with db() as c:
            c.execute(
                "UPDATE custom_post_drafts SET status='published', published_message_id=? WHERE id=?",
                (sent.message_id if sent else 0, draft_id),
            )
        if sent:
            BROADCAST_SKIP_PAUSE.add((cid, sent.message_id))
    except Exception as e:
        log.warning("publish custom: %s", e)


async def custom_post_publish_job(context: ContextTypes.DEFAULT_TYPE) -> None:
    did = (context.job.data or {}).get("draft_id")
    if did:
        await publish_custom_post(context, int(did))


# ============================================================
#                    CHANNEL POST HANDLER
# ============================================================
async def channel_post_limit_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    post = update.channel_post
    if not post:
        return
    chat = post.chat
    if not chat or chat.type != ChatType.CHANNEL:
        return
    channel_id = chat.id
    post_time = _post_time_ist(post)

    # Mirror for restore + delete-all
    try:
        mirror_channel_message(channel_id, post)
    except Exception as e:
        log.warning("mirror: %s", e)

    try:
        with db() as c:
            c.execute(
                "INSERT OR IGNORE INTO channel_seen_messages(channel_id,message_id,seen_at) VALUES(?,?,?)",
                (channel_id, post.message_id, post_time.isoformat()),
            )
    except Exception:
        pass

    try:
        _record_discovered(channel_id, "channel", chat.title,
                           getattr(chat, "username", None), "channel_post")
    except Exception:
        pass

    owner_id = _channel_owner_id(channel_id)
    poster = post.from_user
    is_owner = bool(poster and owner_id and poster.id == owner_id)
    is_admin_poster = bool(poster and is_main_admin(poster.id))

    # Post insurance + analytics
    try:
        save_post_insurance(channel_id, post.message_id, post)
        if poster:
            record_admin_activity(channel_id, poster.id, post.message_id)
        if context.job_queue:
            context.job_queue.run_once(
                per_post_analytics_dm_job,
                when=24 * 3600,
                data={"channel_id": channel_id, "message_id": post.message_id},
                name=f"analytics_{channel_id}_{post.message_id}",
            )
    except Exception as e:
        log.debug("post insurance: %s", e)

    # Mirror backup
    try:
        await mirror_channel_post(context, channel_id, post)
    except Exception:
        pass

    # ---- OWNER + MAIN ADMIN BYPASS ----
    # Owner and Main Admin are unrestricted on their own channel posts.
    # Report Protection still runs for them (independent subsystem).
    if is_owner or is_admin_poster:
        try:
            schedule_channel_message_deletion(context, channel_id, post.message_id,
                                              post_time, created_by=(poster.id if poster else 0))
        except Exception:
            pass
        # Auto-react still applies for owner posts (they enabled it)
        bot_id = getattr(context.bot, "id", None)
        is_bot_post = bool(poster and (getattr(poster, "is_bot", False) or (bot_id and poster.id == bot_id)))
        if (channel_id, post.message_id) in BROADCAST_SKIP_PAUSE:
            is_bot_post = True
        if not is_bot_post:
            try:
                await apply_auto_reaction(context.bot, channel_id, post.message_id,
                                          text=(post.text or post.caption or ""))
            except Exception:
                pass
        try:
            await check_subscriber_milestone(context, channel_id)
        except Exception:
            pass
        return

    # Pause
    if cflag(channel_id, "paused", "off") == "on":
        bot_id = getattr(context.bot, "id", None)
        is_bot_post = bool(poster and (getattr(poster, "is_bot", False) or (bot_id and poster.id == bot_id)))
        if (channel_id, post.message_id) in BROADCAST_SKIP_PAUSE:
            is_bot_post = True
        if not is_bot_post:
            try:
                mark_bot_delete(channel_id, post.message_id)
                await post.delete()
                await post_delete_reason(context, channel_id, "channel", "channel_pause",
                                         poster.id if poster else None)
            except Exception:
                pass
            return

    # Anti-forward
    if get_anti_forward(channel_id, "channel") and (
        getattr(post, "forward_origin", None) is not None or getattr(post, "forward_date", None) is not None
    ):
        try:
            mark_bot_delete(channel_id, post.message_id)
            await post.delete()
            await post_delete_reason(context, channel_id, "channel", "anti_forward",
                                     poster.id if poster else None)
        except Exception:
            pass
        return

    # 18+ filter
    af = get_adult_filter_cfg(channel_id, "channel")
    if int(af.get("enabled") or 0):
        body = post.text or post.caption or ""
        hit = is_adult_content(body, list_adult_words(channel_id, "channel"))
        if hit:
            try:
                mark_bot_delete(channel_id, post.message_id)
                await post.delete()
                await post_delete_reason(context, channel_id, "channel", "adult_filter",
                                         poster.id if poster else None)
            except Exception:
                pass
            return

    # Content locks
    def _locked(k: str) -> bool:
        return get_var(f"chlock_{channel_id}_{k}", "on") == "off"

    blocked = None
    if post.photo and _locked("photo"):
        blocked = "Photo"
    elif post.video and _locked("video"):
        blocked = "Video"
    elif post.animation and _locked("animation"):
        blocked = "GIF"
    elif post.audio and _locked("audio"):
        blocked = "Audio"
    elif post.voice and _locked("voice"):
        blocked = "Voice"
    elif post.document and _locked("document"):
        blocked = "Document"
    elif post.text and _locked("text"):
        blocked = "Text"
    elif post.text and ("http://" in post.text or "https://" in post.text) and _locked("links"):
        blocked = "Links"
    if blocked:
        try:
            mark_bot_delete(channel_id, post.message_id)
            await post.delete()
            await post_delete_reason(context, channel_id, "channel", "content_lock",
                                     poster.id if poster else None)
        except Exception:
            pass
        return

    # Night mode
    if cflag(channel_id, "night_mode", "off") == "on":
        start = cflag(channel_id, "night_start", "23:00") or "23:00"
        end = cflag(channel_id, "night_end", "07:00") or "07:00"
        st = night_window_status(start, end)
        bot_id = getattr(context.bot, "id", None)
        skip = False
        if poster and (getattr(poster, "is_bot", False) or (bot_id and poster.id == bot_id)):
            skip = True
        if (channel_id, post.message_id) in BROADCAST_SKIP_PAUSE:
            skip = True
        if st["active"] and not skip:
            try:
                mark_bot_delete(channel_id, post.message_id)
                await post.delete()
                await post_delete_reason(context, channel_id, "channel", "night_mode",
                                         poster.id if poster else None)
            except Exception:
                return
            return

    # Auto-reaction
    bot_id = getattr(context.bot, "id", None)
    is_bot_post = bool(poster and (getattr(poster, "is_bot", False) or (bot_id and poster.id == bot_id)))
    if (channel_id, post.message_id) in BROADCAST_SKIP_PAUSE:
        is_bot_post = True
    if not is_bot_post:
        try:
            await apply_auto_reaction(context.bot, channel_id, post.message_id,
                                      text=(post.text or post.caption or ""))
        except Exception:
            pass

    # Word filter
    if cflag(channel_id, "word_filter", "off") == "on":
        body = (post.text or post.caption or "").lower()
        for w in list_channel_words(channel_id):
            if w and w in body:
                try:
                    mark_bot_delete(channel_id, post.message_id)
                    await post.delete()
                    await post_delete_reason(context, channel_id, "channel", "channel_word",
                                             poster.id if poster else None)
                except Exception:
                    pass
                return

    # Delay enforcement
    delay_cfg = get_channel_delay_cfg(channel_id)
    if delay_cfg.get("enabled"):
        uid = poster.id if poster else -abs(int(channel_id))
        uname = (poster.username or poster.first_name or str(uid)) if poster else (chat.title or "Channel")
        await _enforce_channel_delay(update, context, chat, post, uid, uname, delay_cfg)
        return

    # Post limit
    cfg = get_post_limit_cfg(channel_id)
    if not cfg.get("enabled"):
        try:
            schedule_channel_message_deletion(context, channel_id, post.message_id,
                                              post_time, created_by=(poster.id if poster else 0))
        except Exception:
            pass
        return

    try:
        limit = max(1, int(cfg.get("daily_limit") or 2))
    except Exception:
        limit = 2
    uid = poster.id if poster else -abs(int(channel_id))
    uname = (poster.username or poster.first_name or str(uid)) if poster else (chat.title or "Channel")

    allowed, used, reset_at = consume_post_slot(channel_id, uid, limit)
    if allowed:
        try:
            schedule_channel_message_deletion(context, channel_id, post.message_id,
                                              post_time, created_by=(poster.id if poster else 0))
        except Exception:
            pass
        return

    try:
        mark_bot_delete(channel_id, post.message_id)
        await post.delete()
        await post_delete_reason(context, channel_id, "channel", "post_limit",
                                 poster.id if poster else None)
    except Exception:
        return


