def duration_preset_kb(prefix: str, cid: int, current_secs: int,
                        include_seconds: bool = False,
                        custom_cb: Optional[str] = None) -> InlineKeyboardMarkup:
    """Reusable preset grid for any duration field.
    prefix -> callback form: prefix:cid:seconds
    custom_cb -> callback for custom text entry (optional)."""
    if include_seconds:
        presets = [
            ("5s", 5), ("10s", 10), ("30s", 30), ("1m", 60),
            ("5m", 300), ("15m", 900), ("30m", 1800), ("1h", 3600),
            ("6h", 21600), ("12h", 43200), ("1d", 86400), ("2d", 172800),
            ("3d", 259200), ("7d", 604800), ("14d", 1209600), ("30d", 2592000),
        ]
    else:
        presets = [
            ("1m", 60), ("5m", 300), ("10m", 600), ("30m", 1800),
            ("1h", 3600), ("6h", 21600), ("12h", 43200), ("1d", 86400),
            ("2d", 172800), ("3d", 259200), ("7d", 604800), ("14d", 1209600),
            ("30d", 2592000),
        ]
    rows = []
    row = []
    per_row = 4 if include_seconds else 3
    for label, secs in presets:
        style = "success" if int(current_secs or 0) == secs else "primary"
        row.append(styled_button(label, f"{prefix}:{cid}:{secs}", style=style))
        if len(row) == per_row:
            rows.append(row); row = []
    if row:
        rows.append(row)
    if custom_cb:
        rows.append([styled_button("Custom Time", custom_cb, style="success")])
    return InlineKeyboardMarkup(rows)


