def channels_grid_kb(channels, page: int, cb_prefix: str, back_cb: str,
                     page_size: int = 9) -> InlineKeyboardMarkup:
    total = len(channels)
    pages = max(1, (total + page_size - 1) // page_size)
    page = max(1, min(page, pages))
    start = (page - 1) * page_size
    items = channels[start:start + page_size]
    rows = []
    row = []
    for ch in items:
        title = (ch["title"] or ch["username"] or str(ch["channel_id"]))[:14]
        row.append(styled_button(f"📡 {title}", f"c:open:{ch['channel_id']}", style="primary"))
        if len(row) == 3:
            rows.append(row); row = []
    if row:
        rows.append(row)
    if not items:
        rows.append([styled_button("🧭 No channels here yet", back_cb, style="primary")])
    if pages > 1:
        nav = []
        if page > 1:
            nav.append(styled_button("◀️ Prev", f"{cb_prefix}:{page-1}", style="primary"))
        nav.append(styled_button(f"Page {page}/{pages}", f"{cb_prefix}:{page}", style="primary"))
        if page < pages:
            nav.append(styled_button("Next ▶️", f"{cb_prefix}:{page+1}", style="primary"))
        rows.append(nav)
    rows.append([styled_button("⛓ Back", back_cb, style="danger")])
    return InlineKeyboardMarkup(rows)


