def get_report_protection(chat_id: int, chat_type: str) -> Dict[str, Any]:
    """Report Protection is always ON. Returns enabled=1 unconditionally."""
    ct = "channel" if (chat_type or "").lower() in ("channel", "Channel") else "group"
    return {
        "chat_id": int(chat_id), "chat_type": ct,
        "enabled": 1, "duplicate_on": 1, "notify_mode": "always",
    }


def set_report_protection(chat_id: int, chat_type: str, **kwargs) -> None:
    """No-op — protection is always enabled."""
    return


def build_report_detected_panel(channel_title: str, channel_id: int,
                                reporter, post_id: int, action: str,
                                post_link: str = "") -> str:
    name = ""
    uname = ""
    uid = ""
    if reporter is not None:
        try:
            name = (getattr(reporter, "first_name", None) or "") + (
                " " + (getattr(reporter, "last_name", "") or "") if getattr(reporter, "last_name", None) else ""
            )
            uname = f"@{getattr(reporter, 'username', '')}" if getattr(reporter, "username", None) else ""
            uid = str(getattr(reporter, "id", ""))
        except Exception:
            pass
    if reporter is None:
        reporter_disp = "Unknown (Telegram-native)"
    else:
        reporter_disp = uname or name or (f"id:{uid}" if uid else "Unknown")
        if uid:
            reporter_disp = f"{reporter_disp} ({uid})"
    lines = [
        f"📡 " + sb("Channel") + f" ➜ {html_escape(channel_title or str(channel_id))}",
        f"👤 " + sb("Reporter") + f" ➜ {html_escape(reporter_disp)}",
        f"📨 " + sb("Post ID") + f" ➜ <code>{post_id}</code>",
        f"🛡 " + sb("Action") + f" ➜ {html_escape(action)}",
        f"😋 " + sb("Time") + f" ➜ {now_ist().strftime('%Y-%m-%d %H:%M:%S IST')}",
    ]
    if post_link:
        lines.insert(3, f"🔗 " + sb("Post") + f" ➜ {html_escape(post_link[:120])}")
    body = "\n".join(lines)
    return (
        "<tg-emoji emoji-id=\"6314095339552901161\">🤓</tg-emoji> <b>" + sb("New Report Detected") + "</b>\n\n"
        + f"<blockquote>{body}</blockquote>\n\n"
        + f"<blockquote>{get_brand_line()}</blockquote>"
    )


