def _count_recent_restores(chat_id: int, hours: int = 24) -> int:
    cutoff = (now_ist() - timedelta(hours=hours)).isoformat()
    try:
        with db() as c:
            r = c.execute(
                "SELECT COUNT(*) AS n FROM logs "
                "WHERE ts >= ? AND action='report_protection_restore' AND detail LIKE ?",
                (cutoff, f"%:{int(chat_id)}:%"),
            ).fetchone()
        return int(r["n"] or 0) if r else 0
    except Exception:
        return 0


def _restore_counts_bundle(chat_id: int) -> Dict[str, int]:
    """Return {'24h': n, '7d': n, '30d': n} for the chat."""
    return {
        "24h": _count_recent_restores(chat_id, hours=24),
        "7d": _count_recent_restores(chat_id, hours=24 * 7),
        "30d": _count_recent_restores(chat_id, hours=24 * 30),
    }


def _last_report_category(chat_id: int) -> str:
    """Read the last known report reason for this chat. Only bot /report
    flows set this — Telegram-native reports are unknowable."""
    try:
        return cflag(int(chat_id), "last_report_category", "native") or "native"
    except Exception:
        return "native"


def _set_last_report_category(chat_id: int, category: str) -> None:
    try:
        set_cflag(int(chat_id), "last_report_category", str(category or "unknown"))
    except Exception:
        pass


def build_channel_saved_notice(chat_title: str, bot_username: str,
                               counts: Dict[str, int]) -> str:
    """Screenshot-style saved notice with day/week/month counts."""
