    # --- Auto-Pin toggle ---
    if kind == "autopin" and len(parts) >= 3:
        try:
            cid = int(parts[2])
        except Exception:
            return
        if not await authorized_for_channel(context.bot, user.id, cid):
            return
        cur = get_auto_pin(cid)
        set_auto_pin(cid, 0 if cur else 1)
        await safe_answer(query, f"Auto-Pin {'OFF' if cur else 'ON'}")
        await _route_callback(update, context, f"c:open:{cid}")
        return

    # --- Pause / Unpause ---
    if kind == "pause" and len(parts) >= 3:
        try:
            cid = int(parts[2])
        except Exception:
            return
        if not await authorized_for_channel(context.bot, user.id, cid):
            return
        if cflag(cid, "paused", "off") == "on":
            await safe_answer(query, "Already paused.", show_alert=True); return
        now = now_ist()
        set_cflag(cid, "paused", "on")
        set_cflag(cid, "paused_by", str(user.id))
        set_cflag(cid, "paused_by_name",
                  getattr(user, "full_name", None) or user.first_name or str(user.id))
        set_cflag(cid, "paused_at", now.isoformat())
        log_action(user.id, "channel_pause", str(cid))
        log_admin_activity(user.id, "channel_pause", f"ch={cid}", cid)
        try:
            await notify_admin_activity(context.bot, user.id, "channel_pause", f"chat={cid}")
        except Exception:
            pass
        try:
            await send_channel_pause_notice(
                context.bot, cid,
                getattr(user, "full_name", None) or user.first_name or str(user.id),
            )
        except Exception:
            pass
        await safe_answer(query, "Channel paused + notice sent.")
        await _route_callback(update, context, f"c:open:{cid}")
        return

    if kind == "unpause" and len(parts) >= 3:
        try:
            cid = int(parts[2])
        except Exception:
            return
        if not await authorized_for_channel(context.bot, user.id, cid):
            return
        try:
            with db() as c:
                rows = c.execute("SELECT message_id FROM channel_paused_posts WHERE channel_id=?",
                                 (cid,)).fetchall()
            for row in rows:
                try:
                    await context.bot.delete_message(cid, int(row["message_id"]))
                except Exception:
                    pass
            with db() as c:
                c.execute("DELETE FROM channel_paused_posts WHERE channel_id=?", (cid,))
        except Exception:
            pass
        set_cflag(cid, "paused", "off")
        log_action(user.id, "channel_unpause", str(cid))
        await safe_answer(query, "Channel unpaused.")
        await _route_callback(update, context, f"c:open:{cid}")
        return

    # --- Night mode ---
