async def handle_help_panel_callback(update: Update, context: ContextTypes.DEFAULT_TYPE, data: str) -> None:
    query = update.callback_query
    parts = data.split(":")
    ctx = parts[2] if len(parts) > 2 else "channel"
    entries = PANEL_HELP.get(ctx, PANEL_HELP.get("channel", []))
    if not entries:
        await safe_answer(query, "No help available.", show_alert=True)
        return
    body_lines = []
    for name, desc in entries:
        body_lines.append(f"<b>{name}</b>")
        body_lines.append(f"  {desc}")
    body = "\n".join(body_lines)
    text = (
        f"🛰️ <b>{sb('Help')} - {sb(ctx.title())}</b>\n\n"
        f"<blockquote>{body}</blockquote>\n\n"
        f"<blockquote>{get_brand_line()}</blockquote>"
    )
    back_cb = {
        "channel": "ch:manage",
        "group": "menu:group",
        "admin": "a:home",
        "report": "menu:help",
    }.get(ctx, "menu:home")
    await safe_edit_or_send(
        update, context, text,
        InlineKeyboardMarkup([[styled_button("Back", back_cb, style="primary")]]),
    )


async def handle_font_callback(update: Update, context: ContextTypes.DEFAULT_TYPE, data: str) -> None:
    query = update.callback_query
    user = query.from_user
    if not is_main_admin(user.id):
        await safe_answer(query, "Owner only.", show_alert=True); return
    parts = data.split(":")
    if len(parts) < 2:
        return
    sub = parts[1]

    if sub == "slot" and len(parts) >= 3:
        slot = parts[2]
        if slot not in ("message", "button"):
            return
        await safe_edit_or_send(
            update, context,
            panel("Choose Font Style",
                  f"🎯 " + sb("Slot") + f" ➜ {slot}",
                  f"💬 " + sb("Current") + f" ➜ {FONT_STYLE_LABELS.get(get_font_slot(slot), '?')}",
                  "<tg-emoji emoji-id=\"6154507785196275515\">✔️</tg-emoji> " + sb("Pick a style below.")),
            font_style_picker_kb(slot),
        )
        return

    if sub == "set" and len(parts) >= 4:
        slot, style = parts[2], parts[3]
        if slot not in ("message", "button") or style not in FONT_STYLE_KEYS:
            await safe_answer(query, "Invalid.", show_alert=True); return
        set_font_slot(slot, style)
        try:
            with db() as c:
                c.execute(
                    "INSERT INTO font_settings(key,value,updated_at) VALUES(?,?,?) "
                    "ON CONFLICT(key) DO UPDATE SET value=excluded.value, "
                    "updated_at=excluded.updated_at",
                    (slot, style, now_ist().isoformat()),
                )
        except Exception:
            pass
        log_action(user.id, "font_set", f"{slot}={style}")
        await safe_answer(query, f"{slot} font → {style}")
        await _route_callback(update, context, f"font:slot:{slot}")
        return

    if sub == "preview":
        preview_lines = ["<tg-emoji emoji-id=\"6154660969499854908\">😘</tg-emoji> " + sb("Font Preview")]
        for key in FONT_STYLE_KEYS[:8]:
            label = FONT_STYLE_LABELS.get(key, key)
            preview_lines.append(f"• {_apply_font_style(label, key)}")
        await safe_edit_or_send(
            update, context,
            panel("Font Preview", *preview_lines),
            InlineKeyboardMarkup([[styled_button("↩️ Back", "a:font_menu", style="danger")]]),
        )
        return

    if sub == "reset":
        set_font_slot("message", "small_caps")
        set_font_slot("button", "small_caps")
        try:
            with db() as c:
                c.execute("UPDATE font_settings SET value='small_caps', updated_at=? WHERE key='message'",
                          (now_ist().isoformat(),))
                c.execute("UPDATE font_settings SET value='small_caps', updated_at=? WHERE key='button'",
                          (now_ist().isoformat(),))
        except Exception:
            pass
        log_action(user.id, "font_reset", "")
        await safe_answer(query, "Fonts reset to default.", show_alert=True)
        await _route_callback(update, context, "a:font_menu")
        return


