async def handle_talk_owner_callback(update: Update, context: ContextTypes.DEFAULT_TYPE, data: str) -> None:
    query = update.callback_query
    user = query.from_user
    if data == "talk:start":
        PENDING[user.id] = {"action": "talk_owner_compose", "chat_scope": "private"}
        await safe_edit_or_send(
            update, context,
            panel("Talk Owner",
                  "<tg-emoji emoji-id=\"6152469685775370640\">✅</tg-emoji> " + sb("Send your message now."),
                  "<tg-emoji emoji-id=\"6062180698595263993\">✔️</tg-emoji> " + sb("It goes directly to the main admin."),
                  "<tg-emoji emoji-id=\"6064403966941202396\">✅</tg-emoji> " + sb("One-way for you — reply comes back as bot DM.")),
            InlineKeyboardMarkup([[styled_button("⛓ Cancel", "menu:home", style="danger")]]),
        )
        return
    if data.startswith("talk:reply:"):
        try:
            thread_id = int(data.split(":")[2])
        except Exception:
            return
        if not is_main_admin(user.id):
            await safe_answer(query, "Owner only.", show_alert=True); return
        PENDING[user.id] = {"action": "talk_owner_reply", "thread_id": thread_id}
        with db() as c:
            r = c.execute("SELECT * FROM talk_owner_threads WHERE id=?", (thread_id,)).fetchone()
        if not r:
            await safe_answer(query, "Thread not found.", show_alert=True); return
        await safe_edit_or_send(
            update, context,
            panel("Reply to User",
                  f"🪪 " + sb("User ID") + f" ➜ <code>{r['user_id']}</code>",
                  f"📝 " + sb("Original") + f" ➜ {html_escape(str(r['body'] or '')[:200])}",
                  "<tg-emoji emoji-id=\"6061942014377724267\">✅</tg-emoji> " + sb("Send your reply now.")),
            InlineKeyboardMarkup([[styled_button("⛓ Cancel", "a:home", style="danger")]]),
        )
        return


async def deliver_talk_owner_message(context, user, body: str) -> None:
    admin_id = MAIN_ADMIN_ID
    if not admin_id:
        return
    with db() as c:
        cur = c.execute(
            "INSERT INTO talk_owner_threads(user_id,user_msg_id,admin_msg_id,body,status,created_at) "
            "VALUES(?,?,?,?,?,?)",
            (user.id, 0, 0, body[:2000], "open", now_ist().isoformat()),
        )
        tid = cur.lastrowid
    uname_disp = f"@{user.username}" if getattr(user, "username", None) else "No Username"
    text = panel(
        "Talk Owner — New Message",
        f"👤 " + sb("From") + f" ➜ {mention_user(user)}",
        f"🪪 " + sb("User ID") + f" ➜ <code>{user.id}</code>",
        f"🔗 " + sb("Username") + f" ➜ {html_escape(uname_disp)}",
        f"😋 " + sb("Time") + f" ➜ {now_ist().strftime('%Y-%m-%d %H:%M:%S')}",
        "",
        html_escape(body[:1500]),
    )
    kb = InlineKeyboardMarkup([
        [styled_button("💬 Reply", f"talk:reply:{tid}", style="success")],
    ])
    try:
        sent = await context.bot.send_message(admin_id, text, parse_mode=ParseMode.HTML, reply_markup=kb)
        with db() as c:
            c.execute("UPDATE talk_owner_threads SET admin_msg_id=? WHERE id=?",
                      (sent.message_id if sent else 0, tid))
    except Exception as e:
        log.warning("talk_owner delivery: %s", e)


