def operator_count() -> int:
    with db() as c:
        return int(c.execute("SELECT COUNT(*) n FROM operators WHERE status='active'").fetchone()["n"])


def operator_user_count(op_id: int) -> int:
    with db() as c:
        return int(c.execute("SELECT COUNT(*) n FROM operator_users WHERE operator_id=?",
                             (int(op_id),)).fetchone()["n"])


def operator_ref_for(op_id: int) -> Optional[str]:
    with db() as c:
        r = c.execute("SELECT token FROM operator_refs WHERE operator_id=? ORDER BY created_at DESC LIMIT 1",
                      (int(op_id),)).fetchone()
        return r["token"] if r else None


def create_operator(user_id: int, added_by: int) -> str:
    token = "op_" + secrets.token_urlsafe(10).replace("-", "_").replace("~", "_")[:18]
    now = datetime.now(UTC).isoformat()
    with db() as c:
        c.execute("INSERT OR REPLACE INTO operators(user_id,added_by,created_at,status) "
                  "VALUES(?,?,?,'active')", (int(user_id), int(added_by), now))
        c.execute("DELETE FROM operator_refs WHERE operator_id=?", (int(user_id),))
        c.execute("INSERT INTO operator_refs(token,operator_id,created_at) VALUES(?,?,?)",
                  (token, int(user_id), now))
    return token


def get_operator(user_id: int):
    with db() as c:
        return c.execute("SELECT * FROM operators WHERE user_id=? AND status='active'",
                         (int(user_id),)).fetchone()


def operator_by_token(token: str):
    with db() as c:
        return c.execute(
            "SELECT o.* FROM operator_refs r JOIN operators o ON o.user_id=r.operator_id "
            "WHERE r.token=? AND o.status='active'",
            (token,),
        ).fetchone()


def add_operator_user(op_id: int, user_id: int) -> bool:
    if int(op_id) == int(user_id) or is_main_admin(int(user_id)):
        return False
    with db() as c:
        cur = c.execute(
            "INSERT OR IGNORE INTO operator_users(operator_id,user_id,first_seen) VALUES(?,?,?)",
            (int(op_id), int(user_id), now_ist().isoformat()),
        )
        return cur.rowcount > 0


def operator_banner_link(bot_username: str, token: str) -> str:
    if not bot_username:
        return ""
    return f"https://t.me/{bot_username.lstrip('@')}?start={token}"


def operator_welcome_text(op, bot_username: str) -> str:
    count = operator_user_count(op["user_id"])
    link = operator_banner_link(bot_username, operator_ref_for(op["user_id"]) or "")
    return panel(
        "Operator Panel",
        "<tg-emoji emoji-id=\"6226302114918828194\">🕺</tg-emoji> " + sb("Congratulations! You are now an Operator."),
        "<tg-emoji emoji-id=\"6226395994313983714\">❤️</tg-emoji> " + sb("Users Added") + f" ➜ {count}",
        "<tg-emoji emoji-id=\"6228821207727212391\">☕️</tg-emoji> " + sb("Your Operator Link") + f" ➜ <code>{html_escape(link)}</code>",
        "<tg-emoji emoji-id=\"6226428825043994471\">😎</tg-emoji> " + sb("Force Join and Brand Tag management are unavailable to Operators."),
        "<tg-emoji emoji-id=\"6226313346258306844\">😭</tg-emoji> " + sb("The protected Brand Tag remains controlled by the Main Admin."),
        brand=False,
    )


async def handle_operator_callback(update: Update, context: ContextTypes.DEFAULT_TYPE, data: str) -> None:
    query = update.callback_query
    user = query.from_user
    if not is_operator(user.id) and not is_main_admin(user.id):
        await safe_answer(query, "Operator access required.", show_alert=True); return
    parts = data.split(":")
    act = parts[1] if len(parts) > 1 else ""

    if act in ("force_join", "forcejoin", "brandtag", "brand_tag", "brand_tag_edit", "brand_tag_remove"):
        await safe_answer(query, "Restricted to Main Admin.", show_alert=True); return

    if act == "panel":
        await safe_edit_or_send(
            update, context,
            operator_welcome_text(get_operator(user.id), get_var("bot_username", "")),
            operator_panel_kb(),
        )
        return

    if act == "link":
        token = operator_ref_for(user.id)
        link = operator_banner_link(get_var("bot_username", ""), token or "")
        kb = []
        if link.startswith("http"):
            kb.append([styled_button("🌐 Open Link", url=link, style="primary")])
        else:
            kb.append([styled_button("⚠️ Not configured", "op:panel", style="danger")])
        kb.append([styled_button("⛓ Back", "op:panel", style="danger")])
        await safe_edit_or_send(
            update, context,
            panel("My Operator Link",
                  "<tg-emoji emoji-id=\"6228518567151667249\">✅</tg-emoji> " + sb("Share this link to add users under your Operator account."),
                  f"<code>{html_escape(link)}</code>"),
            InlineKeyboardMarkup(kb),
        )
        return

    if act == "stats":
        await safe_edit_or_send(
            update, context,
            panel("Operator Statistics",
                  f"👥 " + sb("Users Added") + f" ➜ {operator_user_count(user.id)}",
                  f"🧩 " + sb("Total Operators") + f" ➜ {operator_count()}"),
            InlineKeyboardMarkup([[styled_button("Back", "op:panel", style="danger")]]),
        )
        return

    if act == "users":
        with db() as c:
            rows = c.execute(
                "SELECT user_id, first_seen FROM operator_users WHERE operator_id=? "
                "ORDER BY first_seen DESC LIMIT 100",
                (user.id,),
            ).fetchall()
        lines = [f"👥 " + sb("My Users") + f" ➜ {len(rows)}", ""]
        for r in rows[:80]:
            lines.append(f"• <code>{r['user_id']}</code> · {html_escape(str(r['first_seen'])[:19])}")
        if not rows:
            lines.append("<tg-emoji emoji-id=\"6226543702534260736\">🥺</tg-emoji> " + sb("No users yet."))
        await safe_edit_or_send(
            update, context,
            panel("My Users", *lines),
            InlineKeyboardMarkup([[styled_button("Back", "op:panel", style="danger")]]),
        )
        return

    if act == "welcome":
        PENDING[user.id] = {"action": "operator_welcome", "chat_scope": "private"}
        op = get_operator(user.id)
        current = (op["welcome_message"] if op and op["welcome_message"]
                   else get_var("welcome_message", ""))
        await safe_edit_or_send(
            update, context,
            panel("Operator Welcome Message",
                  "<tg-emoji emoji-id=\"6316802577698654299\">✅</tg-emoji> " + sb("Send the new welcome message."),
                  f"📝 " + sb("Current") + f" ➜ <code>{html_escape(current[:400])}</code>"),
            InlineKeyboardMarkup([[styled_button("Cancel", "op:panel", style="danger")]]),
        )
        return

    if act in ("broadcast", "forward"):
        PENDING[user.id] = {"action": "operator_broadcast", "forwarded": act == "forward",
                            "chat_scope": "private"}
        mode = "forward (as-is)" if act == "forward" else "copy"
        await safe_edit_or_send(
            update, context,
            panel("Operator Broadcast",
                  f"🎞 " + sb("Mode") + f" ➜ {mode}",
                  "<tg-emoji emoji-id=\"6251044120135994563\">🤔</tg-emoji> " + sb("Send the message or media to broadcast to your users.")),
            InlineKeyboardMarkup([[styled_button("Cancel", "op:panel", style="danger")]]),
        )
        return


