def _list_registered_group_ids() -> List[int]:
    with db() as c:
        try:
            rows = c.execute(
                "SELECT chat_id FROM managed_chats WHERE chat_type IN ('group','supergroup') "
                "AND COALESCE(status,'active')='active'"
            ).fetchall()
        except Exception:
            rows = []
    return [int(r["chat_id"]) for r in rows]


def _list_registered_channel_ids() -> List[int]:
    with db() as c:
        try:
            rows = c.execute(
                "SELECT channel_id FROM managed_channels WHERE "
                "COALESCE(status,'active')='active' AND COALESCE(enabled,1)=1"
            ).fetchall()
        except Exception:
            rows = []
    return [int(r["channel_id"]) for r in rows]


def list_bot_user_ids() -> List[int]:
    with db() as c:
        try:
            rows = c.execute("SELECT user_id FROM users WHERE COALESCE(status,'active') != 'blocked'").fetchall()
        except Exception:
            rows = c.execute("SELECT user_id FROM users").fetchall()
    return [int(r["user_id"]) for r in rows]


def count_bot_users() -> int:
    with db() as c:
        try:
            return int(c.execute("SELECT COUNT(*) AS n FROM users").fetchone()["n"])
        except Exception:
            return 0


def get_bc_cfg(key: str) -> int:
    with db() as c:
        r = c.execute(f"SELECT {key} FROM broadcast_config WHERE id=1").fetchone()
    return int(r[key]) if r and r[key] is not None else 0


def set_bc_cfg(key: str, value: int) -> None:
    with db() as c:
        c.execute(f"UPDATE broadcast_config SET {key}=?, updated_at=? WHERE id=1",
                  (int(value), now_ist().isoformat()))


def _snapshot_broadcast_message(msg) -> Optional[Dict[str, Any]]:
    if msg.photo:
        return {"media_type": "photo", "file_id": msg.photo[-1].file_id, "caption": msg.caption or ""}
    if msg.video:
        return {"media_type": "video", "file_id": msg.video.file_id, "caption": msg.caption or ""}
    if msg.animation:
        return {"media_type": "animation", "file_id": msg.animation.file_id, "caption": msg.caption or ""}
    if msg.document:
        return {"media_type": "document", "file_id": msg.document.file_id, "caption": msg.caption or ""}
    if msg.audio:
        return {"media_type": "audio", "file_id": msg.audio.file_id, "caption": msg.caption or ""}
    if msg.voice:
        return {"media_type": "voice", "file_id": msg.voice.file_id, "caption": msg.caption or ""}
    if msg.video_note:
        return {"media_type": "video_note", "file_id": msg.video_note.file_id, "caption": ""}
    if msg.sticker:
        return {"media_type": "sticker", "file_id": msg.sticker.file_id, "caption": ""}
    if msg.text:
        return {"media_type": "text", "text": msg.text, "caption": ""}
    return None


def _apply_brand_quote(text: str, media_caption: bool = False) -> str:
    if not text:
        return get_brand_line() or ""
    marker = _brand_marker()
    stripped = text.strip()
    if marker and marker in stripped:
        return stripped
    body = f"<blockquote>{stripped}</blockquote>" if not media_caption else stripped
    brand = get_brand_line()
    if brand:
        return f"{body}\n\n<blockquote>{brand}</blockquote>"
    return body


async def _deliver_broadcast_payload(bot, target_chat_id: int, payload: Dict[str, Any],
                                     apply_brand: bool = True,
                                     apply_quote: bool = True,
                                     native_forward: bool = False,
                                     forward_from: Optional[Tuple[int, int]] = None) -> Tuple[str, Optional[str]]:
    media_type = payload.get("media_type") or "text"
    file_id = payload.get("file_id")
    caption = payload.get("caption") or ""
    body = payload.get("text") or ""
    sent = None

    if native_forward and forward_from:
        try:
            sent = await bot.forward_message(
                chat_id=target_chat_id,
                from_chat_id=forward_from[0],
                message_id=forward_from[1],
            )
            if sent:
                BROADCAST_SKIP_PAUSE.add((int(target_chat_id), int(sent.message_id)))
                try:
                    _broadcast_mark(int(target_chat_id), int(sent.message_id), 0)
                except Exception:
                    pass
            return "forward", None
        except RetryAfter as e:
            return "retry", f"Rate limited. Retry after {getattr(e, 'retry_after', '?')}s."
        except Exception as e:
            return "error", str(e)[:200]

    if media_type == "text" and body:
        body = apply_pool_to_text(body)
        if apply_brand or apply_quote:
            body = _apply_brand_quote(body, media_caption=False)

    new_caption = caption
    if media_type != "text" and new_caption:
        new_caption = apply_pool_to_text(new_caption)
    if media_type != "text" and caption:
        brand = get_brand_line() if apply_brand else ""
        if apply_quote:
            new_caption = f"<blockquote>{caption}</blockquote>"
            if brand:
                new_caption += f"\n\n<blockquote>{brand}</blockquote>"
        elif brand:
            new_caption = f"{caption}\n\n{brand}"

    try:
        if media_type == "photo" and file_id:
            sent = await bot.send_photo(target_chat_id, file_id, caption=new_caption or None,
                                        parse_mode=ParseMode.HTML if new_caption else None)
        elif media_type == "video" and file_id:
            sent = await bot.send_video(target_chat_id, file_id, caption=new_caption or None,
                                        parse_mode=ParseMode.HTML if new_caption else None)
        elif media_type == "animation" and file_id:
            sent = await bot.send_animation(target_chat_id, file_id, caption=new_caption or None,
                                            parse_mode=ParseMode.HTML if new_caption else None)
        elif media_type == "document" and file_id:
            sent = await bot.send_document(target_chat_id, file_id, caption=new_caption or None,
                                           parse_mode=ParseMode.HTML if new_caption else None)
        elif media_type == "audio" and file_id:
            sent = await bot.send_audio(target_chat_id, file_id, caption=new_caption or None,
                                        parse_mode=ParseMode.HTML if new_caption else None)
        elif media_type == "voice" and file_id:
            sent = await bot.send_voice(target_chat_id, file_id, caption=new_caption or None,
                                        parse_mode=ParseMode.HTML if new_caption else None)
        elif media_type == "video_note" and file_id:
            sent = await bot.send_video_note(target_chat_id, file_id)
        elif media_type == "sticker" and file_id:
            sent = await bot.send_sticker(target_chat_id, file_id)
        elif media_type == "text" and body:
            sent = await bot.send_message(target_chat_id, body, parse_mode=ParseMode.HTML,
                                          disable_web_page_preview=False)
        else:
            return "unknown", "Unsupported or empty content."
        if sent is not None:
            try:
                BROADCAST_SKIP_PAUSE.add((int(target_chat_id), int(sent.message_id)))
            except Exception:
                pass
            # Mark as broadcast for reply tracking
            try:
                is_ch = 1 if int(target_chat_id) < 0 and str(target_chat_id).startswith("-100") else 0
                _broadcast_mark(int(target_chat_id), int(sent.message_id), is_ch)
            except Exception:
                pass
            try:
                # Auto-pin if enabled and target is a channel
                if get_bc_cfg("auto_pin_channels") and int(target_chat_id) < 0:
                    await pin_broadcast_message(bot, int(target_chat_id), int(sent.message_id))
            except Exception:
                pass
        return media_type, None
    except RetryAfter as e:
        return "retry", f"Rate limited. Retry after {getattr(e, 'retry_after', '?')}s."
    except (Forbidden, BadRequest, TelegramError) as e:
        return "error", str(e)[:200]
    except Exception as e:
        return "error", str(e)[:200]


async def handle_broadcast_callback(update: Update, context: ContextTypes.DEFAULT_TYPE, data: str) -> None:
    query = update.callback_query
    user = query.from_user
    if not (is_main_admin(user.id) or is_operator(user.id)):
        await safe_answer(query, "Access denied.", show_alert=True); return
    parts = data.split(":")
    act = parts[1] if len(parts) > 1 else ""

    if act == "dest" and len(parts) >= 3:
        key = parts[2]
        st = PENDING.get(user.id) or {}
        if st.get("action") != "broadcast_dest":
            st = {"action": "broadcast_dest", "dest_users": True,
                  "dest_groups": True, "dest_channels": True}
        flag = f"dest_{key}"
        st[flag] = not bool(st.get(flag))
        PENDING[user.id] = st
        u_count = count_bot_users()
        g_count = len(_list_registered_group_ids())
        c_count = len(_list_registered_channel_ids())
        await safe_edit_or_send(
            update, context,
            panel("Global Broadcast",
                  "<tg-emoji emoji-id=\"6316611803841299970\">✅</tg-emoji> " + sb("Select destination(s)."),
                  f"👤 " + sb("Bot Users") + f" ➜ {u_count}",
                  f"🏰 " + sb("Bot Groups") + f" ➜ {g_count}",
                  f"📡 " + sb("Bot Channels") + f" ➜ {c_count}",
                  "<tg-emoji emoji-id=\"6314095339552901161\">🇺🇿</tg-emoji> " + sb("Toggle destinations, then Continue.")),
            global_broadcast_dest_kb(bool(st.get("dest_users")), bool(st.get("dest_groups")),
                                     bool(st.get("dest_channels"))),
        )
        return

    if act == "continue":
        st = PENDING.get(user.id) or {}
        du = bool(st.get("dest_users")); dg = bool(st.get("dest_groups")); dc = bool(st.get("dest_channels"))
        if not (du or dg or dc):
            await safe_answer(query, "Select at least one.", show_alert=True); return
        PENDING[user.id] = {"action": "broadcast_compose", "dest_users": du,
                            "dest_groups": dg, "dest_channels": dc}
        lines = ["<tg-emoji emoji-id=\"6314220842792257477\">👋</tg-emoji> " + sb("Compose one message for selected destinations.")]
        if du:
            lines.append(f"👤 " + sb("Bot Users") + f" ➜ {count_bot_users()}")
        if dg:
            lines.append(f"🏰 " + sb("Bot Groups") + f" ➜ {len(_list_registered_group_ids())}")
        if dc:
            lines.append(f"📡 " + sb("Bot Channels") + f" ➜ {len(_list_registered_channel_ids())}")
        lines.append("<tg-emoji emoji-id=\"6062160684047665430\">🍿</tg-emoji> " + sb("Send text or media now. You'll confirm before send."))
        lines.append("<tg-emoji emoji-id=\"6314471789141427686\">😠</tg-emoji> " + sb("Forwarded message keeps original header."))
        await safe_edit_or_send(
            update, context,
            panel("Global Broadcast", *lines),
            InlineKeyboardMarkup([[styled_button("⛓ Cancel", "a:global_broadcast", style="danger")]]),
        )
        return

    if act == "refresh_emoji":
        st = PENDING.get(user.id) or {}
        if st.get("action") != "broadcast_confirm":
            await safe_answer(query, "Nothing to refresh.", show_alert=True); return
        payload = st.get("payload") or {}
        # Re-apply emoji pool to text/caption
        if payload.get("media_type") == "text":
            payload["text"] = apply_pool_to_text(payload.get("text", ""))
        else:
            payload["caption"] = apply_pool_to_text(payload.get("caption", ""))
        st["payload"] = payload
        PENDING[user.id] = st
        pool = list_emoji_pool()
        await safe_answer(query, f"Refreshed with {len(pool)} emoji from pool.", show_alert=True)
        return

    if act == "go":
        st = PENDING.get(user.id) or {}
        payload = st.get("payload")
        if st.get("action") != "broadcast_confirm" or not payload:
            PENDING.pop(user.id, None)
            await safe_answer(query, "Nothing to send. Compose again.", show_alert=True)
            await _route_callback(update, context, "a:global_broadcast")
            return
        du = bool(st.get("dest_users")); dg = bool(st.get("dest_groups")); dc = bool(st.get("dest_channels"))
        native_forward = bool(st.get("native_forward"))
        forward_from = st.get("forward_from")
        apply_brand = bool(st.get("apply_brand", 1))
        apply_quote = bool(st.get("apply_quote", 1))
        uids = list_bot_user_ids() if du else []
        gids = _list_registered_group_ids() if dg else []
        cids = _list_registered_channel_ids() if dc else []

        u_sent = u_fail = g_sent = g_fail = c_sent = c_fail = 0

        async def _one(cid: int) -> Optional[str]:
            kind, err = await _deliver_broadcast_payload(
                context.bot, cid, payload,
                apply_brand=apply_brand, apply_quote=apply_quote,
                native_forward=native_forward, forward_from=forward_from,
            )
            if err and kind == "retry":
                try:
                    m = re.search(r"(\d+(?:\.\d+)?)", err)
                    wait = float(m.group(1)) if m else 1.5
                    wait = min(max(wait, 0.5), 30.0)
                    await asyncio.sleep(wait)
                    kind, err = await _deliver_broadcast_payload(
                        context.bot, cid, payload,
                        apply_brand=apply_brand, apply_quote=apply_quote,
                        native_forward=native_forward, forward_from=forward_from,
                    )
                except Exception:
                    pass
            return err

        for uid in uids:
            err = await _one(uid)
            if err:
                u_fail += 1
            else:
                u_sent += 1
            await asyncio.sleep(0.05)
        for gid in gids:
            err = await _one(gid)
            if err:
                g_fail += 1
            else:
                g_sent += 1
            await asyncio.sleep(0.05)
        for cid in cids:
            err = await _one(cid)
            if err:
                c_fail += 1
            else:
                c_sent += 1
            await asyncio.sleep(0.05)

        PENDING.pop(user.id, None)
        log_action(user.id, "global_broadcast",
                   f"u{u_sent}/{len(uids)} g{g_sent}/{len(gids)} c{c_sent}/{len(cids)}")
        lines = ["<tg-emoji emoji-id=\"6080209558259631951\">👩‍❤️‍👨</tg-emoji> " + sb("Broadcast Complete")]
        if du:
            lines.append(f"👤 " + sb("Users") + f" ✅ {u_sent}  ❌ {u_fail}")
        if dg:
            lines.append(f"🏰 " + sb("Groups") + f" ✅ {g_sent}  ❌ {g_fail}")
        if dc:
            lines.append(f"📡 " + sb("Channels") + f" ✅ {c_sent}  ❌ {c_fail}")
        lines.append(f"📊 " + sb("Total sent") + f" ➜ {u_sent + g_sent + c_sent}")
        await safe_edit_or_send(
            update, context,
            panel("Broadcast Complete", *lines[1:]),
            InlineKeyboardMarkup([
                [styled_button("📣 Broadcast Again", "a:global_broadcast", style="success")],
                [styled_button("↩️ Back", "a:home", style="danger"),
                 styled_button("🏠 Home", "menu:home", style="primary")],
            ]),
        )
        return


# ============================================================
#                    BOT IDENTITY HELPERS
# ============================================================
_bot_self_client = None
_bot_self_lock: Optional[asyncio.Lock] = None


def _bot_self_get_lock() -> asyncio.Lock:
    global _bot_self_lock
    if _bot_self_lock is None:
        _bot_self_lock = asyncio.Lock()
    return _bot_self_lock


async def get_bot_self_client():
    """Pyrogram client logged in as the BOT itself (bot_token).
    Only used for bot-self operations like profile photo change."""
    global _bot_self_client
    if not (MT_PROTO_API_ID and MT_PROTO_API_HASH and BOT_TOKEN):
        return None
    if _bot_self_client is not None:
        try:
            if _bot_self_client.is_connected:
                return _bot_self_client
        except Exception:
            pass
    async with _bot_self_get_lock():
        if _bot_self_client is not None:
            try:
                if _bot_self_client.is_connected:
                    return _bot_self_client
            except Exception:
                pass
        try:
            from pyrogram import Client as _PC
            c = _PC(
                "rehan_bot_self",
                api_id=int(MT_PROTO_API_ID),
                api_hash=str(MT_PROTO_API_HASH),
                bot_token=str(BOT_TOKEN),
                in_memory=True,
                no_updates=True,
            )
            await c.start()
            _bot_self_client = c
            log.info("[BOT_SELF] MTProto client online")
            return c
        except Exception as e:
            log.warning("[BOT_SELF] start failed: %s", e)
            _bot_self_client = None
            return None


async def stop_bot_self_client() -> None:
    global _bot_self_client
    if _bot_self_client is not None:
        try:
            await _bot_self_client.stop()
        except Exception:
            pass
        _bot_self_client = None


async def _upload_bot_profile_photo(photo_bytes: bytes) -> Tuple[bool, str]:
    client = await get_bot_self_client()
    if not client:
        return False, "MTProto not configured or login failed"
    try:
        await client.set_profile_photo(photo=io.BytesIO(photo_bytes))
        return True, "ok"
    except Exception as e:
        return False, str(e)[:200]


def _stats_snapshot() -> Dict[str, int]:
    with db() as c:
        users_n = int(c.execute("SELECT COUNT(*) AS n FROM users").fetchone()["n"])
        files_n = int(c.execute("SELECT COUNT(*) AS n FROM files WHERE status='active'").fetchone()["n"])
        ch_n = int(c.execute("SELECT COUNT(*) AS n FROM managed_channels").fetchone()["n"])
        warns_n = int(c.execute("SELECT COUNT(*) AS n FROM warnings").fetchone()["n"])
        logs_n = int(c.execute("SELECT COUNT(*) AS n FROM logs").fetchone()["n"])
        reg_groups_n = int(c.execute(
            "SELECT COUNT(DISTINCT chat_id) AS n FROM managed_group_access"
        ).fetchone()["n"])
        disc_g_n = int(c.execute(
            "SELECT COUNT(*) AS n FROM discovered_chats "
            "WHERE chat_type IN ('group','supergroup') AND status='active'"
        ).fetchone()["n"])
        disc_c_n = int(c.execute(
            "SELECT COUNT(*) AS n FROM discovered_chats "
            "WHERE chat_type='channel' AND status='active'"
        ).fetchone()["n"])
        tot_g = int(c.execute(
            "SELECT COUNT(*) AS n FROM ("
            "SELECT chat_id FROM managed_group_access "
            "UNION "
            "SELECT chat_id FROM discovered_chats WHERE chat_type IN ('group','supergroup') AND status='active'"
            ")"
        ).fetchone()["n"])
        tot_c = int(c.execute(
            "SELECT COUNT(*) AS n FROM ("
            "SELECT channel_id AS chat_id FROM managed_channels "
            "UNION "
            "SELECT chat_id FROM discovered_chats WHERE chat_type='channel' AND status='active'"
            ")"
        ).fetchone()["n"])
    return {"users": users_n, "files": files_n, "channels": ch_n, "warns": warns_n,
            "logs": logs_n, "reg_groups": reg_groups_n, "disc_groups": disc_g_n,
            "disc_channels": disc_c_n, "total_groups": tot_g, "total_channels": tot_c}


