# ============================================================
#                    BANNER MANAGER
# ============================================================
async def handle_banner_callback(update: Update, context: ContextTypes.DEFAULT_TYPE, data: str) -> None:
    query = update.callback_query
    user = query.from_user
    if not is_main_admin(user.id):
        await safe_answer(query, "Owner only.", show_alert=True); return
    parts = data.split(":")
    sub = parts[1] if len(parts) > 1 else ""

    if sub == "cat" and len(parts) >= 3:
        cat = parts[2]
        await safe_edit_or_send(
            update, context,
            panel("Banner Manager", f"🎨 " + sb(cat.title() + " Screens")),
            banner_cat_kb(cat),
        )
        return

    if sub == "section" and len(parts) >= 3:
        key = parts[2]
        await safe_edit_or_send(
            update, context,
            panel(f"Section Banner — {key}",
                  "<tg-emoji emoji-id=\"6064403966941202396\">🆘</tg-emoji> " + sb("Change, preview or restore the default banner.")),
            banner_section_kb(key),
        )
        return

    if sub == "change" and len(parts) >= 3:
        key = parts[2]
        PENDING[user.id] = {"action": "banner_upload", "section": key}
        await safe_edit_or_send(
            update, context,
            panel(f"Change Banner — {key}",
                  "<tg-emoji emoji-id=\"6061942014377724267\">🛑</tg-emoji> " + sb("Send a Photo, Video or GIF/Animation."),
                  "<tg-emoji emoji-id=\"6226302114918828194\">🔸</tg-emoji> " + sb("Captions on uploads are ignored.")),
            InlineKeyboardMarkup([[styled_button("✖ Cancel", "a:banner_mgr", style="danger")]]),
        )
        return

    if sub == "preview" and len(parts) >= 3:
        key = parts[2]
        try:
            await safe_delete(context.bot, query.message.chat_id, query.message.message_id)
        except Exception:
            pass
        if key == "global":
            gfid = get_var("global_banner_file_id", "")
            gtype = get_var("global_banner_media_type", "photo") or "photo"
            if gfid:
                try:
                    if gtype == "video":
                        await context.bot.send_video(query.message.chat_id, gfid,
                                                     caption="<b>Preview — Global</b>",
                                                     parse_mode=ParseMode.HTML)
                    elif gtype in ("animation", "gif"):
                        await context.bot.send_animation(query.message.chat_id, gfid,
                                                         caption="<b>Preview — Global</b>",
                                                         parse_mode=ParseMode.HTML)
                    else:
                        await context.bot.send_photo(query.message.chat_id, gfid,
                                                     caption="<b>Preview — Global</b>",
                                                     parse_mode=ParseMode.HTML)
                    return
                except Exception:
                    pass
            await send_section_banner(context.bot, query.message.chat_id, "global",
                                      caption="<b>Preview — Global (default)</b>")
            return
        await send_section_banner(
            context.bot, query.message.chat_id, key,
            caption=f"<b>Preview — {html_escape(key)}</b>",
            reply_markup=InlineKeyboardMarkup([
                [styled_button("⛓ Back", f"banner:section:{key}", style="primary")]
            ]),
        )
        return

    if sub in ("restore", "remove") and len(parts) >= 3:
        key = parts[2]
        if key == "global":
            set_var("global_banner_file_id", "")
            set_var("global_banner_media_type", "")
        else:
            restore_section_banner(key)
        log_action(user.id, "banner_restore", key)
        await safe_answer(query, "Default restored.", show_alert=True)
        await _route_callback(update, context, f"banner:section:{key}")
        return


