async def handle_force_join_callback(update: Update, context: ContextTypes.DEFAULT_TYPE, data: str) -> None:
    query = update.callback_query
    user = query.from_user
    parts = data.split(":")
    sub = parts[1] if len(parts) > 1 else ""

    if sub == "verify_new":
        await force_join_verify_callback(update, context)
        return

    if not is_main_admin(user.id):
        await safe_answer(query, "Owner only.", show_alert=True); return

    if sub == "admin_toggle":
        cur = get_var("force_join_enabled", "on")
        set_var("force_join_enabled", "off" if cur == "on" else "on")
        log_action(user.id, "force_join_toggle", get_var("force_join_enabled"))
        await _route_callback(update, context, "a:force_join")
        return

    if sub == "admin_add":
        PENDING[user.id] = {"action": "fj_add_channel"}
        await safe_edit_or_send(
            update, context,
            panel("Add Force Join Channel",
                  "<tg-emoji emoji-id=\"6226395994313983714\">⚡️</tg-emoji> " + sb("Send channel @username, invite link, or -100 ID."),
                  "<tg-emoji emoji-id=\"6228821207727212391\">🆕</tg-emoji> " + sb("Bot must be admin there.")),
            InlineKeyboardMarkup([[styled_button("⛓ Cancel", "a:force_join", style="danger")]]),
        )
        return

    if sub == "admin_add_private":
        PENDING[user.id] = {"action": "fj_add_private_channel"}
        await safe_edit_or_send(
            update, context,
            panel("Add Private Channel",
                  "<tg-emoji emoji-id=\"6226428825043994471\">🆕</tg-emoji> " + sb("Send: -100CHANNEL_ID | Join Request invite link."),
                  "<tg-emoji emoji-id=\"6226313346258306844\">🇧🇿</tg-emoji> " + sb("Format:") + " <code>-1001234567890 | https://t.me/+xxxx</code>"),
            InlineKeyboardMarkup([[styled_button("⛓ Cancel", "a:force_join", style="danger")]]),
        )
        return

    if sub == "admin_list":
        with db() as c:
            rows = c.execute("SELECT * FROM force_join ORDER BY COALESCE(display_order,0), id").fetchall()
        rows_kb = []
        for r in rows:
            rid = r["id"]
            title = (r["title"] or r["chat_ref"] or str(rid))[:24]
            rows_kb.append([
                styled_button(f"🪐 {title}", f"fj:admin_item:{rid}", style="primary"),
                styled_button("🗑", f"fj:admin_del:{rid}", style="danger"),
            ])
        rows_kb.append([styled_button("⛓ Back", "a:force_join", style="primary")])
        await safe_edit_or_send(
            update, context,
            panel("Manage Channels", "<tg-emoji emoji-id=\"6228518567151667249\">🆕</tg-emoji> " + sb("Select a channel.")),
            InlineKeyboardMarkup(rows_kb),
        )
        return

    if sub == "admin_item" and len(parts) >= 3:
        try:
            rid = int(parts[2])
        except Exception:
            return
        with db() as c:
            r = c.execute("SELECT * FROM force_join WHERE id=?", (rid,)).fetchone()
        if not r:
            await safe_answer(query, "Not found.", show_alert=True); return
        en = "ON" if (r["enabled"] if "enabled" in r.keys() and r["enabled"] is not None else 1) else "OFF"
        btn = (r["custom_button_name"] if "custom_button_name" in r.keys()
               and r["custom_button_name"] else (r["title"] or "Channel"))
        await safe_edit_or_send(
            update, context,
            panel("Force Join Channel",
                  f"🪐 " + sb("Label") + f" ➜ {html_escape(str(btn))}",
                  f"🔗 " + sb("Ref") + f" ➜ {html_escape(r['chat_ref'] or '')}",
                  f"⚡ " + sb("Enabled") + f" ➜ {en}"),
            InlineKeyboardMarkup([
                [styled_button("Rename Button", f"fj:admin_rename:{rid}", style="primary")],
                [styled_button("⬆", f"fj:admin_up:{rid}", style="primary"),
                 styled_button("⬇", f"fj:admin_down:{rid}", style="primary"),
                 styled_button(f"Toggle {en}", f"fj:admin_enable:{rid}", style="success")],
                [styled_button("🗑 Remove", f"fj:admin_del:{rid}", style="danger")],
                [styled_button("⛓ Back", "fj:admin_list", style="primary")],
            ]),
        )
        return

    if sub == "admin_rename" and len(parts) >= 3:
        try:
            rid = int(parts[2])
        except Exception:
            return
        PENDING[user.id] = {"action": "fj_rename", "id": rid}
        await safe_edit_or_send(
            update, context,
            panel("Edit Button Name", "<tg-emoji emoji-id=\"6226543702534260736\">🆓</tg-emoji> " + sb("Send new button label.")),
            InlineKeyboardMarkup([[styled_button("⛓ Cancel", "fj:admin_list", style="danger")]]),
        )
        return

    if sub == "admin_enable" and len(parts) >= 3:
        try:
            rid = int(parts[2])
        except Exception:
            return
        with db() as c:
            row = c.execute("SELECT enabled FROM force_join WHERE id=?", (rid,)).fetchone()
            cur = int(row["enabled"]) if row and row["enabled"] is not None else 1
            c.execute("UPDATE force_join SET enabled=? WHERE id=?", (0 if cur else 1, rid))
        await _route_callback(update, context, "fj:admin_list")
        return

    if sub in ("admin_up", "admin_down") and len(parts) >= 3:
        try:
            rid = int(parts[2])
        except Exception:
            return
        delta = -1 if sub == "admin_up" else 1
        with db() as c:
            row = c.execute("SELECT display_order FROM force_join WHERE id=?", (rid,)).fetchone()
            order = int(row["display_order"] or 0) if row else 0
            c.execute("UPDATE force_join SET display_order=? WHERE id=?", (order + delta, rid))
        await _route_callback(update, context, "fj:admin_list")
        return

    if sub == "admin_del" and len(parts) >= 3:
        try:
            rid = int(parts[2])
        except Exception:
            return
        with db() as c:
            c.execute("DELETE FROM force_join WHERE id=?", (rid,))
        log_action(user.id, "force_join_del", str(rid))
        await safe_answer(query, "Removed.")
        await _route_callback(update, context, "fj:admin_list")
        return


