def save_rating(user, rating: int, reason: str, source: str,
                chat_id: Optional[int] = None, chat_type: Optional[str] = None,
                chat_title: Optional[str] = None,
                profile_photo_id: Optional[str] = None) -> int:
    now = now_ist().isoformat()
    with db() as c:
        cur = c.execute(
            "INSERT INTO ratings(user_id, first_name, last_name, username, language_code, "
            "is_premium, profile_photo_id, rating, reason, source, chat_id, chat_type, chat_title, "
            "status, created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (
                int(user.id),
                user.first_name or "",
                getattr(user, "last_name", None) or "",
                user.username or "",
                getattr(user, "language_code", None) or "",
                1 if getattr(user, "is_premium", False) else 0,
                profile_photo_id or "",
                int(rating),
                (reason or "")[:1000],
                source or "",
                chat_id, chat_type or "", chat_title or "",
                "pending", now,
            ),
        )
        return int(cur.lastrowid)


def get_rating(rid: int):
    with db() as c:
        return c.execute("SELECT * FROM ratings WHERE id=?", (int(rid),)).fetchone()


def list_ratings(status: str, limit: int = 50) -> List[Any]:
    with db() as c:
        return c.execute(
            "SELECT * FROM ratings WHERE status=? ORDER BY id DESC LIMIT ?",
            (status, limit),
        ).fetchall()


def count_ratings(status: str) -> int:
    with db() as c:
        r = c.execute("SELECT COUNT(*) AS n FROM ratings WHERE status=?", (status,)).fetchone()
        return int(r["n"]) if r else 0


def ratings_average() -> float:
    with db() as c:
        r = c.execute("SELECT AVG(rating) AS a FROM ratings "
                      "WHERE status IN ('pending','published')").fetchone()
        return float(r["a"] or 0.0) if r and r["a"] is not None else 0.0


def set_rating_status(rid: int, status: str, by_id: int) -> None:
    now = now_ist().isoformat()
    with db() as c:
        if status == "published":
            c.execute(
                "UPDATE ratings SET status=?, reviewed_at=?, reviewed_by=?, published_at=? WHERE id=?",
                (status, now, by_id, now, int(rid)),
            )
        else:
            c.execute(
                "UPDATE ratings SET status=?, reviewed_at=?, reviewed_by=? WHERE id=?",
                (status, now, by_id, int(rid)),
            )


def build_rate_stars(n: int) -> str:
    n = max(0, min(5, int(n)))
    return "<tg-emoji emoji-id=\"6316802577698654299\">😁</tg-emoji>" * n + "<tg-emoji emoji-id=\"6251044120135994563\">🎧</tg-emoji>" * (5 - n)


def rating_card(row) -> str:
    stars = build_rate_stars(row["rating"])
    name = html_escape(
        (row["first_name"] or "") + (" " + row["last_name"] if row["last_name"] else "")
    ) or str(row["user_id"])
    uname = f"@{html_escape(row['username'])}" if row["username"] else "Not Available"
    reason = html_escape(row["reason"] or "") or "—"
    ctx = ""
    if row["chat_id"]:
        ctx = f"📍 " + sb("Source") + f" ➜ {html_escape(row['chat_title'] or str(row['chat_id']))}"
    return panel(
        "Rating",
        stars,
        f"👤 " + sb("User") + f" ➜ {name}",
        f"🪪 " + sb("ID") + f" ➜ <code>{row['user_id']}</code>",
        f"🔹 " + sb("Username") + f" ➜ {uname}",
        f"🌐 " + sb("Language") + f" ➜ {html_escape(row['language_code'] or '—')}",
        f"💎 " + sb("Premium") + f" ➜ {'Yes' if row['is_premium'] else 'No'}",
        ctx,
        f"💬 " + sb("Reason") + f" ➜ {reason}",
        f"😋 " + sb("Time") + f" ➜ {html_escape(str(row['created_at'] or '')[:19])}",
    )


def rating_publish_text(row) -> str:
    stars = build_rate_stars(row["rating"])
    reason = html_escape(row["reason"] or "").strip()
    user_disp = (f"@{html_escape(row['username'])}" if row["username"]
                 else html_escape(row["first_name"] or "Anonymous"))
    lines = [stars]
    if reason:
        lines.append(f'💬 "{reason}"')
    lines.append(f"👤 — {user_disp}")
    lines.append("")
    lines.append(f"👑 Powered by {html_escape(BOT_NAME)}")
    return "\n".join(lines)


