def export_ratings_csv() -> io.BytesIO:
    import csv as _csv
    buf = io.StringIO()
    w = _csv.writer(buf)
    w.writerow([
        "user_id", "first_name", "last_name", "username", "language_code",
        "is_premium", "profile_photo_id", "rating", "reason", "source",
        "chat_id", "chat_type", "chat_title", "status", "created_at",
        "reviewed_at", "reviewed_by", "published_at",
    ])
    with db() as c:
        rows = c.execute("SELECT * FROM ratings ORDER BY id ASC").fetchall()
    for r in rows:
        w.writerow([
            r["user_id"], r["first_name"], r["last_name"], r["username"],
            r["language_code"], r["is_premium"], r["profile_photo_id"],
            r["rating"], (r["reason"] or "").replace("\n", " "), r["source"],
            r["chat_id"], r["chat_type"], r["chat_title"], r["status"],
            r["created_at"], r["reviewed_at"], r["reviewed_by"], r["published_at"],
        ])
    b = io.BytesIO(buf.getvalue().encode("utf-8"))
    b.name = f"ratings_{now_ist().strftime('%Y%m%d')}.csv"
    return b


def export_ratings_txt() -> io.BytesIO:
    with db() as c:
        rows = c.execute("SELECT * FROM ratings ORDER BY id ASC").fetchall()
    lines = [f"REHAN CODEX — Ratings Export — {now_ist().strftime('%Y-%m-%d %H:%M IST')}", ""]
    for r in rows:
        lines.append("=" * 60)
        lines.append(f"ID:          {r['id']}")
        lines.append(f"Status:      {r['status']}")
        lines.append(f"Stars:       {build_rate_stars(r['rating'])}  ({r['rating']}/5)")
        lines.append(f"User ID:     {r['user_id']}")
        lines.append(f"Name:        {r['first_name']} {r['last_name'] or ''}".rstrip())
        lines.append(f"Username:    @{r['username']}" if r["username"] else "Username:    —")
        lines.append(f"Language:    {r['language_code'] or '—'}")
        lines.append(f"Premium:     {'Yes' if r['is_premium'] else 'No'}")
        lines.append(f"Source:      {r['source'] or '—'}")
        if r["chat_id"]:
            lines.append(f"Chat:        {r['chat_title'] or r['chat_id']} ({r['chat_type']})")
        lines.append(f"Reason:      {(r['reason'] or '—')}")
        lines.append(f"Created:     {r['created_at']}")
        if r["reviewed_at"]:
            lines.append(f"Reviewed:    {r['reviewed_at']} by {r['reviewed_by']}")
        if r["published_at"]:
            lines.append(f"Published:   {r['published_at']}")
    b = io.BytesIO("\n".join(lines).encode("utf-8"))
    b.name = f"ratings_{now_ist().strftime('%Y%m%d')}.txt"
    return b


async def _finish_rate(update, context, user, st: Dict[str, Any]) -> None:
    rating = int(st.get("rating") or 0)
    reason = (st.get("reason") or "").strip()
    source = st.get("source") or "button"
    if rating < 1 or rating > 5:
        PENDING.pop(user.id, None)
        return
    photo_id = ""
    try:
        photos = await context.bot.get_user_profile_photos(user.id, limit=1)
        if photos and photos.total_count:
            photo_id = photos.photos[0][0].file_id
    except Exception:
        pass
    try:
        save_rating(user, rating, reason, source, profile_photo_id=photo_id)
    except Exception as e:
        log.warning("save_rating: %s", e)
    PENDING.pop(user.id, None)
    await safe_edit_or_send(
        update, context,
        panel("Thank You",
              build_rate_stars(rating),
              "<tg-emoji emoji-id=\"6316611803841299970\">❤️</tg-emoji> " + sb("Your rating has been recorded.")),
        InlineKeyboardMarkup([[styled_button("🏠 Home", "menu:home", style="primary")]]),
    )


async def handle_rate_callback(update: Update, context: ContextTypes.DEFAULT_TYPE, data: str) -> None:
    query = update.callback_query
    user = query.from_user
    parts = data.split(":")
    sub = parts[1] if len(parts) > 1 else ""

    if sub == "start":
        PENDING[user.id] = {"action": "rate_await_stars", "source": "button"}
        await safe_edit_or_send(
            update, context,
            panel("Rate Us", "<tg-emoji emoji-id=\"6314095339552901161\">🏷</tg-emoji> " + sb("How many stars would you give us?")),
            rate_stars_kb(),
        )
        return

    if sub == "stars" and len(parts) >= 3:
        try:
            stars = int(parts[2])
        except Exception:
            return
        st = PENDING.get(user.id) or {}
        if st.get("action") not in ("rate_await_stars", "rate_await_reason"):
            st = {"action": "rate_await_stars", "source": "button"}
        st["rating"] = stars
        st["action"] = "rate_await_reason"
        PENDING[user.id] = st
        await safe_edit_or_send(
            update, context,
            panel("Rate Us", build_rate_stars(stars),
                  "<tg-emoji emoji-id=\"6314220842792257477\">💸</tg-emoji> " + sb("Would you like to add a reason?")),
            rate_reason_kb(),
        )
        return

    if sub == "write_reason":
        st = PENDING.get(user.id) or {}
        st["action"] = "rate_await_reason_text"
        PENDING[user.id] = st
        await safe_edit_or_send(
            update, context,
            panel("Rate Us", "<tg-emoji emoji-id=\"6062160684047665430\">📍</tg-emoji> " + sb("Send your reason now.")),
            InlineKeyboardMarkup([[styled_button("⛓ Cancel", "rate:cancel", style="danger")]]),
        )
        return

    if sub == "skip_reason":
        st = PENDING.get(user.id) or {}
        st["reason"] = ""
        await _finish_rate(update, context, user, st)
        return

    if sub == "cancel":
        PENDING.pop(user.id, None)
        await safe_edit_or_send(
            update, context,
            panel("Rate Us", "<tg-emoji emoji-id=\"6314471789141427686\">🛜</tg-emoji> " + sb("Cancelled.")),
            InlineKeyboardMarkup([[styled_button("🏠 Home", "menu:home", style="primary")]]),
        )
        return


