def parse_poll_options(raw: str) -> List[str]:
    if not raw:
        return []
    parts = re.split(r"[\n|,]+", raw)
    seen = set()
    out = []
    for p in parts:
        v = p.strip()
        if not v:
            continue
        if v.lower() in seen:
            continue
        seen.add(v.lower())
        out.append(v[:100])
        if len(out) >= 10:
            break
    return out


def parse_timer_seconds(raw: str) -> Optional[int]:
    if not raw:
        return None
    t = raw.strip().lower()
    if t in ("off", "0", "none", "no"):
        return 0
    m = re.fullmatch(r"(\d+)\s*(m|h|d|s)?", t)
    if not m:
        return None
    n = int(m.group(1))
    unit = m.group(2) or "s"
    mult = {"s": 1, "m": 60, "h": 3600, "d": 86400}[unit]
    secs = n * mult
    return secs if 0 <= secs <= 30 * 86400 else None


def format_timer_label(secs: int) -> str:
    if not secs:
        return "OFF"
    if secs % 86400 == 0:
        return f"{secs // 86400}d"
    if secs % 3600 == 0:
        return f"{secs // 3600}h"
    if secs % 60 == 0:
        return f"{secs // 60}m"
    return f"{secs}s"


def save_poll(creator_id: int, chat_id: int, chat_type: str, question: str,
              options: List[str], poll_type: str = "regular",
              allows_multiple: bool = False, is_anonymous: bool = True,
              correct_option: Optional[int] = None, explanation: str = "",
              close_timer: int = 0) -> int:
    with db() as c:
        cur = c.execute(
            "INSERT INTO polls(creator_id, chat_id, chat_type, question, options_json, "
            "poll_type, allows_multiple, is_anonymous, correct_option, explanation, "
            "close_timer, created_at, status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (
                creator_id, chat_id, chat_type, question[:300],
                json.dumps(options, ensure_ascii=False),
                poll_type, 1 if allows_multiple else 0, 1 if is_anonymous else 0,
                correct_option, (explanation or "")[:200],
                int(close_timer or 0), now_ist().isoformat(), "active",
            ),
        )
        return int(cur.lastrowid)


