async def _show_poll_settings(update, context, draft: Dict[str, Any]) -> None:
    q = html_escape((draft.get("question") or "")[:200])
    opts = draft.get("options") or []
    timer = int(draft.get("close_timer") or 0)
    lines = [
        f"❓ " + sb("Question") + f" ➜ {q}",
        f"📝 " + sb("Options") + f" ➜ {len(opts)}",
        f"🎯 " + sb("Type") + f" ➜ {draft.get('poll_type', 'regular')}",
        f"⏱ " + sb("Timer") + f" ➜ {format_timer_label(timer)}",
    ]
    await safe_edit_or_send(update, context, panel("Poll Settings", *lines),
                            poll_settings_kb(draft))


async def _send_poll_to_chat(bot, chat_id: int, draft: Dict[str, Any], creator_id: int) -> None:
    q = draft.get("question") or ""
    opts = draft.get("options") or []
    poll_type = draft.get("poll_type") or "regular"
    allows_multiple = bool(draft.get("allows_multiple"))
    is_anonymous = bool(draft.get("is_anonymous", True))
    correct = draft.get("correct_option")
    explanation = draft.get("explanation") or ""
    timer = int(draft.get("close_timer") or 0)
    kwargs: Dict[str, Any] = {
        "chat_id": chat_id,
        "question": q,
        "options": opts,
        "is_anonymous": is_anonymous,
        "allows_multiple_answers": allows_multiple,
        "type": "quiz" if poll_type == "quiz" and correct is not None else "regular",
    }
    if kwargs["type"] == "quiz":
        kwargs["correct_option_id"] = int(correct)
        if explanation:
            kwargs["explanation"] = explanation[:200]
    if timer > 0:
        kwargs["open_period"] = min(timer, 30 * 86400)
    m = await bot.send_poll(**kwargs)
    try:
        try:
            _poll_chat = await bot.get_chat(chat_id)
            ctype = getattr(_poll_chat, "type", None) or ("channel" if chat_id < 0 else "private")
        except Exception:
            ctype = "channel" if chat_id < 0 else "private"
        pid = save_poll(creator_id, chat_id, ctype, q, opts, poll_type,
                        allows_multiple, is_anonymous,
                        int(correct) if correct is not None else None, explanation, timer)
        record_poll_message(pid, m.message_id)
    except Exception as e:
        log.warning("save_poll: %s", e)


async def handle_poll_callback(update: Update, context: ContextTypes.DEFAULT_TYPE, data: str) -> None:
    query = update.callback_query
    user = query.from_user
    parts = data.split(":")
    sub = parts[1] if len(parts) > 1 else ""

    if sub == "hub":
        await safe_edit_or_send(
            update, context,
            panel("Poll System",
                  "<tg-emoji emoji-id=\"6064207472187410089\">✅</tg-emoji> " + sb("Create and send native Telegram polls."),
                  "<tg-emoji emoji-id=\"6316794301296675025\">👍</tg-emoji> " + sb("Polls support regular and quiz modes.")),
            poll_hub_kb(),
        )
        return

    if sub == "create":
        PENDING[user.id] = {"action": "poll_await_question", "draft": {}}
        await safe_edit_or_send(
            update, context,
            panel("Create Poll", "<tg-emoji emoji-id=\"6316470533777000299\">🛍</tg-emoji> " + sb("Send the poll question.")),
            InlineKeyboardMarkup([[styled_button("⛓ Cancel", "poll:cancel", style="danger")]]),
        )
        return

    if sub in ("type",) and len(parts) >= 3:
        st = PENDING.get(user.id) or {}
        draft = st.get("draft") or {}
        draft["poll_type"] = "quiz" if parts[2] == "quiz" else "regular"
        st["draft"] = draft
        st["action"] = "poll_await_options"
        PENDING[user.id] = st
        await safe_edit_or_send(
            update, context,
            panel("Poll Options",
                  "<tg-emoji emoji-id=\"6314237837977847753\">😯</tg-emoji> " + sb("Send options, one per line, or separated by | or ,"),
                  "<tg-emoji emoji-id=\"6314192865375291243\">🤕</tg-emoji> " + sb("2 to 10 options.")),
            InlineKeyboardMarkup([[styled_button("⛓ Cancel", "poll:cancel", style="danger")]]),
        )
        return

    if sub == "toggle" and len(parts) >= 3:
        key = parts[2]
        st = PENDING.get(user.id) or {}
        draft = st.get("draft") or {}
        if key == "multiple":
            draft["allows_multiple"] = not bool(draft.get("allows_multiple"))
        elif key == "anonymous":
            draft["is_anonymous"] = not bool(draft.get("is_anonymous", True))
        st["draft"] = draft
        PENDING[user.id] = st
        await _show_poll_settings(update, context, draft)
        return

    if sub == "timer":
        await safe_edit_or_send(
            update, context,
            panel("Auto-Close Timer", "<tg-emoji emoji-id=\"6062026539334109188\">🔝</tg-emoji> " + sb("When should the poll close?")),
            poll_timer_kb(),
        )
        return

    if sub == "timer_set" and len(parts) >= 3:
        secs = int(parts[2])
        st = PENDING.get(user.id) or {}
        draft = st.get("draft") or {}
        draft["close_timer"] = secs
        st["draft"] = draft
        PENDING[user.id] = st
        await _show_poll_settings(update, context, draft)
        return

    if sub == "timer_custom":
        st = PENDING.get(user.id) or {}
        PENDING[user.id] = {"action": "poll_custom_timer", "draft": st.get("draft") or {}}
        await safe_edit_or_send(
            update, context,
            panel("Custom Timer", "<tg-emoji emoji-id=\"6095920948060358845\">💯</tg-emoji> " + sb("Send duration like 45m, 2h, 1d.")),
            InlineKeyboardMarkup([[styled_button("⛓ Cancel", "poll:timer", style="danger")]]),
        )
        return

    if sub == "back_settings":
        draft = (PENDING.get(user.id) or {}).get("draft") or {}
        await _show_poll_settings(update, context, draft)
        return

    if sub == "send":
        st = PENDING.get(user.id) or {}
        draft = st.get("draft") or {}
        if not draft.get("question") or not draft.get("options"):
            await safe_answer(query, "Missing question or options.", show_alert=True)
            return
        await safe_edit_or_send(
            update, context,
            panel("Send Poll", "<tg-emoji emoji-id=\"6217707120855355134\">🤔</tg-emoji> " + sb("Where should this poll be sent?")),
            poll_send_dest_kb(is_main_admin(user.id)),
        )
        return

    if sub == "dest" and len(parts) >= 3:
        dest = parts[2]
        if dest == "pick":
            PENDING[user.id] = {"action": "poll_dest_pick",
                                "draft": (PENDING.get(user.id) or {}).get("draft") or {}}
            await safe_edit_or_send(
                update, context,
                panel("Send To",
                      "<tg-emoji emoji-id=\"6151963850297051287\">🇧🇯</tg-emoji> " + sb("Send the chat ID or @username where the poll should go."),
                      "<tg-emoji emoji-id=\"6154532210675288074\">🇧🇹</tg-emoji> " + sb("Bot must be admin/member there.")),
                InlineKeyboardMarkup([[styled_button("⛓ Cancel", "poll:cancel", style="danger")]]),
            )
            return
        if dest == "all_mine":
            st = PENDING.get(user.id) or {}
            draft = st.get("draft") or {}
            if not draft.get("question"):
                return
            owned = list_owned_channels(user.id)
            if not owned and not is_main_admin(user.id):
                await safe_answer(query, "No channels registered.", show_alert=True)
                return
            sent = 0
            failed = 0
            for ch in owned:
                try:
                    await _send_poll_to_chat(context.bot, ch["channel_id"], draft, user.id)
                    sent += 1
                except Exception:
                    failed += 1
            PENDING.pop(user.id, None)
            await safe_edit_or_send(
                update, context,
                panel("Poll Sent",
                      f"✅ " + sb("Sent") + f" ➜ {sent}",
                      f"❌ " + sb("Failed") + f" ➜ {failed}"),
                InlineKeyboardMarkup([[styled_button("📊 Poll Hub", "poll:hub", style="primary")]]),
            )
            return

    if sub == "cancel":
        PENDING.pop(user.id, None)
        await safe_edit_or_send(
            update, context,
            panel("Poll Cancelled", "<tg-emoji emoji-id=\"6152044763185940460\">💯</tg-emoji> " + sb("Cancelled.")),
            InlineKeyboardMarkup([[styled_button("🏠 Home", "menu:home", style="primary")]]),
        )
        return

    if sub == "recent":
        await safe_edit_or_send(
            update, context,
            panel("Recent Polls", "<tg-emoji emoji-id=\"6151953834433319012\">🔄</tg-emoji> " + sb("Your recent polls.")),
            poll_list_kb(user.id),
        )
        return

    if sub == "view" and len(parts) >= 3:
        pid = int(parts[2])
        p = get_poll(pid)
        if not p or int(p["creator_id"]) != int(user.id):
            return
        try:
            opts = json.loads(p["options_json"] or "[]")
        except Exception:
            opts = []
        opts_txt = "\n".join(f"• {o}" for o in opts)
        await safe_edit_or_send(
            update, context,
            panel("Poll",
                  f"#{p['id']}  ·  {html_escape(p['question'] or '')}",
                  opts_txt,
                  f"🚦 " + sb("Status") + f" ➜ {p['status']}",
                  f"🎯 " + sb("Type") + f" ➜ {p['poll_type']}"),
            poll_view_kb(pid, p["status"] or "active"),
        )
        return

    if sub == "close" and len(parts) >= 3:
        pid = int(parts[2])
        p = get_poll(pid)
        if not p or int(p["creator_id"]) != int(user.id):
            return
        mark_poll_closed(pid)
        await safe_answer(query, "Marked as closed.")
        await _route_callback(update, context, f"poll:view:{pid}")
        return

    if sub == "delete" and len(parts) >= 3:
        pid = int(parts[2])
        p = get_poll(pid)
        if not p or int(p["creator_id"]) != int(user.id):
            return
        with db() as c:
            c.execute("DELETE FROM polls WHERE id=?", (pid,))
        await safe_answer(query, "Deleted.")
        await _route_callback(update, context, "poll:recent")
        return

    if sub == "repost" and len(parts) >= 3:
        pid = int(parts[2])
        p = get_poll(pid)
        if not p or int(p["creator_id"]) != int(user.id):
            return
        try:
            opts = json.loads(p["options_json"] or "[]")
        except Exception:
            opts = []
        if not opts:
            return
        await _send_poll_to_chat(
            context.bot, p["chat_id"],
            {
                "question": p["question"],
                "options": opts,
                "poll_type": p["poll_type"],
                "allows_multiple": bool(p["allows_multiple"]),
                "is_anonymous": bool(p["is_anonymous"]),
                "correct_option": p["correct_option"],
                "explanation": p["explanation"],
                "close_timer": int(p["close_timer"] or 0),
            },
            user.id,
        )
        await safe_answer(query, "Reposted.")
        return


# ============================================================
#                    REPORT SUBMISSION FLOW
# ============================================================
def generate_report_code() -> str:
    day = now_ist().strftime("%Y%m%d")
    for _ in range(12):
        suffix = secrets.token_hex(3).upper()
        code = f"RPT-{day}-{suffix}"
        with db() as c:
            exists = c.execute("SELECT 1 FROM reports WHERE public_id=?", (code,)).fetchone()
        if not exists:
            return code
    return f"RPT-{day}-{secrets.token_hex(4).upper()}"


def create_report(reporter, chat, message_id: int, reason: str,
                  post_link: str = "", responsible_admin_id: Optional[int] = None,
                  status: str = "pending", parent_report_id: Optional[int] = None,
                  is_duplicate: int = 0, custom_reason: str = "") -> Tuple[int, str]:
    now = now_ist().isoformat()
    public_id = generate_report_code()
    with db() as c:
        cur = c.execute(
            "INSERT INTO reports(reporter_user_id,reporter_first_name,reporter_last_name,"
            "reporter_username,chat_id,chat_type,chat_title,chat_username,message_id,reason,"
            "status,created_at,post_link,responsible_admin_id,notification_status,"
            "parent_report_id,is_duplicate,public_id,custom_reason) "
            "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (
                reporter.id if reporter else 0,
                getattr(reporter, "first_name", "") or "" if reporter else "",
                getattr(reporter, "last_name", "") or "" if reporter else "",
                getattr(reporter, "username", "") or "" if reporter else "",
                chat.id if chat else 0,
                getattr(chat, "type", "") if chat else "",
                getattr(chat, "title", "") or "" if chat else "",
                getattr(chat, "username", "") or "" if chat else "",
                message_id, (reason or "")[:1000], status or "pending", now,
                (post_link or "")[:500], responsible_admin_id,
                "pending", parent_report_id, int(is_duplicate or 0), public_id,
                (custom_reason or "")[:1000],
            ),
        )
        return int(cur.lastrowid), public_id


def get_report(report_id) -> Optional[Any]:
    with db() as c:
        try:
            rid = int(report_id)
            row = c.execute("SELECT * FROM reports WHERE report_id=?", (rid,)).fetchone()
            if row:
                return row
        except Exception:
            pass
        try:
            return c.execute("SELECT * FROM reports WHERE public_id=?", (str(report_id),)).fetchone()
        except Exception:
            return None


def set_report_status(report_id: int, status: str, by_id: Optional[int] = None) -> None:
    with db() as c:
        c.execute(
            "UPDATE reports SET status=?, resolved_by=?, resolved_at=? WHERE report_id=?",
            (status, by_id,
             now_ist().isoformat() if status in ("resolved", "dismissed") else None,
             report_id),
        )


def resolve_chat_owner(chat_id: int, chat_type: str = "") -> Tuple[Optional[int], str]:
    if chat_type in ("channel", ChatType.CHANNEL, "Channel"):
        with db() as c:
            row = c.execute(
                "SELECT added_by_user_id, added_by_first_name, added_by_last_name, "
                "added_by_username FROM managed_channels WHERE channel_id=?",
                (chat_id,),
            ).fetchone()
    else:
        with db() as c:
            row = c.execute(
                "SELECT added_by_user_id, added_by_first_name, added_by_last_name, "
                "added_by_username FROM managed_chats WHERE chat_id=?",
                (chat_id,),
            ).fetchone()
    if not row:
        return None, "Unknown"
    try:
        uid = int(row["added_by_user_id"]) if row["added_by_user_id"] else None
    except Exception:
        uid = None
    un = (row["added_by_username"] or "").strip() if "added_by_username" in row.keys() else ""
    fn = (row["added_by_first_name"] or "").strip() if "added_by_first_name" in row.keys() else ""
    disp = f"@{un}" if un else (fn or (f"User {uid}" if uid else "Unknown"))
    return uid, disp


def get_reporter_state(chat_id: int, chat_type: str, reporter_id: int):
    ct = "channel" if (chat_type or "").lower() in ("channel", "Channel") else "group"
    with db() as c:
        return c.execute(
            "SELECT * FROM report_reporters WHERE chat_id=? AND chat_type=? AND reporter_user_id=?",
            (chat_id, ct, reporter_id),
        ).fetchone()


def upsert_reporter_state(chat_id: int, chat_type: str, reporter_id: int, *,
                          report_count=None, last_report_at=None, cooldown_until=None,
                          duplicate_count=None, status=None, restricted_until=None,
                          restricted_by=None) -> None:
    ct = "channel" if (chat_type or "").lower() in ("channel", "Channel") else "group"
    now = now_ist().isoformat()
    with db() as c:
        ex = c.execute(
            "SELECT * FROM report_reporters WHERE chat_id=? AND chat_type=? AND reporter_user_id=?",
            (chat_id, ct, reporter_id),
        ).fetchone()
        if not ex:
            c.execute(
                "INSERT INTO report_reporters(chat_id,chat_type,reporter_user_id,report_count,"
                "last_report_at,cooldown_until,duplicate_count,status,restricted_until,"
                "restricted_by,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                (chat_id, ct, reporter_id,
                 report_count if report_count is not None else 0,
                 last_report_at, cooldown_until,
                 duplicate_count if duplicate_count is not None else 0,
                 status or "active", restricted_until, restricted_by, now),
            )
            return
        c.execute(
            "UPDATE report_reporters SET report_count=?, last_report_at=?, cooldown_until=?, "
            "duplicate_count=?, status=?, restricted_until=?, restricted_by=?, updated_at=? "
            "WHERE chat_id=? AND chat_type=? AND reporter_user_id=?",
            (
                report_count if report_count is not None else ex["report_count"],
                last_report_at if last_report_at is not None else ex["last_report_at"],
                cooldown_until if cooldown_until is not None else ex["cooldown_until"],
                duplicate_count if duplicate_count is not None else ex["duplicate_count"],
                status if status is not None else ex["status"],
                restricted_until if restricted_until is not None else ex["restricted_until"],
                restricted_by if restricted_by is not None else ex["restricted_by"],
                now, chat_id, ct, reporter_id,
            ),
        )


def log_report_protection_event(chat_id: int, chat_type: str, reporter_id: int,
                                event_type: str, detail: str = "") -> None:
    ct = "channel" if (chat_type or "").lower() in ("channel", "Channel") else "group"
    with db() as c:
        try:
            c.execute(
                "INSERT INTO report_protection_events(chat_id,chat_type,reporter_user_id,"
                "event_type,detail,created_at) VALUES(?,?,?,?,?,?)",
                (chat_id, ct, reporter_id, event_type, (detail or "")[:500], now_ist().isoformat()),
            )
        except Exception:
            pass


def find_duplicate_report(chat_id: int, message_id: int, reporter_id: int, reason: str = ""):
    with db() as c:
        row = c.execute(
            "SELECT * FROM reports WHERE chat_id=? AND message_id=? AND reporter_user_id=? "
            "AND COALESCE(status,'pending') IN ('open','pending') ORDER BY report_id DESC LIMIT 1",
            (chat_id, message_id, reporter_id),
        ).fetchone()
        if row:
            return row
        if reason:
            row = c.execute(
                "SELECT * FROM reports WHERE chat_id=? AND reporter_user_id=? AND reason=? "
                "AND COALESCE(status,'pending') IN ('open','pending') ORDER BY report_id DESC LIMIT 1",
                (chat_id, reporter_id, (reason or "")[:1000]),
            ).fetchone()
            return row
    return None


def check_report_allowed(chat_id: int, chat_type: str, reporter_id: int,
                         message_id: int, reason: str) -> Tuple[bool, Optional[str], Optional[str]]:
    state = get_reporter_state(chat_id, chat_type, reporter_id)
    if not state:
        return True, None, None
    try:
        ru_str = state["restricted_until"] if "restricted_until" in state.keys() else None
    except Exception:
        ru_str = None
    st = state["status"] if "status" in state.keys() else "active"
    if st == "restricted" and ru_str:
        try:
            ru = datetime.fromisoformat(str(ru_str).replace("Z", "+00:00"))
            if ru.tzinfo is None:
                ru = ru.replace(tzinfo=IST)
            if ru > now_ist():
                return False, "restricted", panel(
                    "Reporter Restricted",
                    "<tg-emoji emoji-id=\"6152265584634496632\">🇧🇴</tg-emoji> " + sb("You are temporarily restricted from reporting in this chat."),
                    f"⏳ " + sb("Try Again") + f" ➜ {format_remaining(ru - now_ist())}",
                )
            else:
                upsert_reporter_state(chat_id, chat_type, reporter_id,
                                      status="active", restricted_until="")
        except Exception:
            pass
    return True, None, None


def mark_report_submitted(chat_id: int, chat_type: str, reporter_id: int) -> None:
    state = get_reporter_state(chat_id, chat_type, reporter_id)
    prev = int(state["report_count"]) if state and state["report_count"] is not None else 0
    upsert_reporter_state(chat_id, chat_type, reporter_id,
                          report_count=prev + 1, last_report_at=now_ist().isoformat(),
                          status="active")


def build_report_notice_text(*, chat_type_key, chat_title, chat_id, reporter,
                             reason, message_id, post_link, public_id) -> str:
    is_ch = chat_type_key == "channel"
    type_label = "Channel" if is_ch else "Group"
    emoji = "<tg-emoji emoji-id=\"6152103458209007684\">🤩</tg-emoji>" if is_ch else "<tg-emoji emoji-id=\"6154431420677752889\">🤩</tg-emoji>"
    reporter_name = html_escape(
        (getattr(reporter, "full_name", None) if reporter and hasattr(reporter, "full_name") else None)
        or ((getattr(reporter, "first_name", "") or "") +
            (" " + (getattr(reporter, "last_name", "") or "")).rstrip())
        or str(getattr(reporter, "id", "?"))
    )
    un = getattr(reporter, "username", None) if reporter else None
    uname_disp = f"@{html_escape(un)}" if un else "—"
    ts = now_ist().strftime("%d %b %Y, %I:%M %p IST")
    lines = [
        f"{emoji} " + sb(type_label) + f" ➜ {html_escape(chat_title or str(chat_id))}",
        f"🆔 " + sb("Chat ID") + f" ➜ <code>{chat_id}</code>",
        "",
        f"👤 " + sb("Reported By") + f" ➜ {reporter_name}",
        f"🪪 " + sb("User ID") + f" ➜ <code>{getattr(reporter, 'id', '?')}</code>",
        f"🔹 " + sb("Username") + f" ➜ {uname_disp}",
        "",
        f" " + sb("Reason") + f" ➜ {html_escape((reason or '')[:400])}",
        f"📨 " + sb("Post ID") + f" ➜ <code>{message_id}</code>",
    ]
    if post_link and str(post_link).startswith("http"):
        lines.append(f"🔗 " + sb("Post") + f" ➜ {html_escape(post_link[:160])}")
    lines += [
        f"😋 " + sb("Time") + f" ➜ {ts}",
        f"🔖 " + sb("Report ID") + f" ➜ <code>{public_id}</code>",
    ]
    return panel(f"New {type_label} Report", *lines)


async def notify_report_parties(bot, *, responsible_admin_id, chat_type_key,
                                chat_title, chat_id, reporter, reason, message_id,
                                post_link, public_id, internal_id) -> Dict[str, str]:
    text = build_report_notice_text(
        chat_type_key=chat_type_key, chat_title=chat_title, chat_id=chat_id,
        reporter=reporter, reason=reason, message_id=message_id,
        post_link=post_link, public_id=public_id,
    )
    kb_rows = []
    if post_link and str(post_link).startswith("https://t.me/"):
        kb_rows.append([styled_button("🔗 View Post", url=post_link, style="primary")])
    kb = InlineKeyboardMarkup(kb_rows) if kb_rows else None

    result = {"responsible": "n/a", "main_admin": "n/a", "channel": "n/a"}

    async def _send_private(uid: int) -> str:
        if not uid:
            return "unavailable"
        try:
            await bot.send_message(int(uid), text, parse_mode=ParseMode.HTML, reply_markup=kb)
            return "sent"
        except RetryAfter as e:
            try:
                await asyncio.sleep(min(float(getattr(e, "retry_after", 1) or 1), 10))
                await bot.send_message(int(uid), text, parse_mode=ParseMode.HTML, reply_markup=kb)
                return "sent"
            except Exception:
                return "failed"
        except Forbidden:
            return "unavailable"
        except Exception:
            return "failed"

    resp_id = int(responsible_admin_id) if responsible_admin_id else None
    main_id = int(MAIN_ADMIN_ID) if MAIN_ADMIN_ID else None

    if resp_id and main_id and resp_id == main_id:
        st = await _send_private(resp_id)
        result["responsible"] = st
        result["main_admin"] = st
    else:
        if resp_id:
            result["responsible"] = await _send_private(resp_id)
        else:
            result["responsible"] = "unavailable"
        if main_id:
            result["main_admin"] = await _send_private(main_id)
        else:
            result["main_admin"] = "unavailable"

    if chat_type_key == "channel":
        try:
            me = await bot.get_me()
            member = await bot.get_chat_member(int(chat_id), me.id)
            st = getattr(member, "status", None)
            if st in (ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER,
                      "administrator", "creator"):
                ch_text = panel(
                    "New Post Report",
                    f"📡 " + sb("Channel") + f" ➜ {html_escape(chat_title or str(chat_id))}",
                    f"📨 " + sb("Post ID") + f" ➜ <code>{message_id}</code>",
                    f" " + sb("Reason") + f" ➜ {html_escape((reason or '')[:300])}",
                    f"🔖 " + sb("Report ID") + f" ➜ <code>{public_id}</code>",
                    "",
                    "<tg-emoji emoji-id=\"6228782806424618433\">❤️</tg-emoji> " + sb("Report Received"),
                )
                sent = await bot.send_message(int(chat_id), ch_text,
                                              parse_mode=ParseMode.HTML, reply_markup=kb)
                if sent:
                    BROADCAST_SKIP_PAUSE.add((int(chat_id), int(sent.message_id)))
                result["channel"] = "sent"
            else:
                result["channel"] = "unavailable"
        except Exception:
            result["channel"] = "failed"

    with db() as c:
        c.execute(
            "UPDATE reports SET responsible_notification_status=?, main_admin_notification_status=?, "
            "channel_notification_status=?, notification_status=? WHERE report_id=?",
            (result["responsible"], result["main_admin"], result["channel"],
             f"resp={result['responsible']};main={result['main_admin']};ch={result['channel']}",
             internal_id),
        )
    return result


async def _finalize_link_report(update, context, user, st: dict, reason: str) -> None:
    chat_id = st.get("chat_id")
    message_id = st.get("message_id")
    post_link = st.get("post_link") or ""
    chat_type_key = st.get("chat_type_key") or "group"
    chat_title = st.get("chat_title") or str(chat_id)
    if not chat_id or not message_id or not user:
        PENDING.pop(user.id, None)
        await safe_answer(update.callback_query, "Session incomplete.", show_alert=True)
        return

    if chat_type_key == "channel":
        with db() as c:
            reg = c.execute(
                "SELECT * FROM managed_channels WHERE channel_id=? AND COALESCE(status,'active')='active'",
                (int(chat_id),),
            ).fetchone()
    else:
        with db() as c:
            reg = c.execute(
                "SELECT * FROM managed_chats WHERE chat_id=? AND COALESCE(status,'active')='active'",
                (int(chat_id),),
            ).fetchone()
    if not reg:
        PENDING.pop(user.id, None)
        await safe_edit_or_send(
            update, context,
            panel("Invalid Report Target", "<tg-emoji emoji-id=\"6152434913720141300\">💟</tg-emoji> " + sb("Chat is not registered with the bot.")),
        )
        return
    cfg = get_report_protection(int(chat_id), chat_type_key)
    if not int(cfg.get("enabled", 1)):
        PENDING.pop(user.id, None)
        await safe_edit_or_send(
            update, context,
            panel("Report Protection Is Not Active",
                  "<tg-emoji emoji-id=\"6154369208076470797\">🔫</tg-emoji> " + sb("This Group/Channel is not protected by the bot.")),
        )
        return
    allowed, block_code, block_msg = check_report_allowed(
        int(chat_id), chat_type_key, user.id, int(message_id), reason)
    if not allowed:
        log_report_protection_event(int(chat_id), chat_type_key, user.id,
                                    block_code or "blocked", f"msg={message_id}")
        PENDING.pop(user.id, None)
        await safe_edit_or_send(update, context,
                                block_msg or panel("Blocked", "<tg-emoji emoji-id=\"6154522383790114334\">🇧🇼</tg-emoji> " + sb("Not accepted.")))
        return

    parent_id = None
    is_dup = 0
    if int(cfg.get("duplicate_on", 1)):
        dup = find_duplicate_report(int(chat_id), int(message_id), user.id, reason)
        if dup:
            parent_id = int(dup["report_id"])
            is_dup = 1
            st_row = get_reporter_state(int(chat_id), chat_type_key, user.id)
            prev = int(st_row["duplicate_count"]) if st_row and st_row["duplicate_count"] else 0
            upsert_reporter_state(int(chat_id), chat_type_key, user.id, duplicate_count=prev + 1)
            log_report_protection_event(int(chat_id), chat_type_key, user.id,
                                        "duplicate", f"parent={parent_id}")

    owner_id, _ = resolve_chat_owner(int(chat_id), chat_type_key)
    if not owner_id and reg and "added_by_user_id" in reg.keys():
        try:
            owner_id = int(reg["added_by_user_id"]) if reg["added_by_user_id"] else None
        except Exception:
            owner_id = None

    class _Chat: pass
    chat_obj = _Chat()
    chat_obj.id = int(chat_id)
    chat_obj.type = "channel" if chat_type_key == "channel" else "supergroup"
    chat_obj.title = chat_title
    chat_obj.username = st.get("chat_username") or ""

    internal_id, public_id = create_report(
        user, chat_obj, int(message_id), reason,
        post_link=post_link, responsible_admin_id=owner_id,
        status="pending", parent_report_id=parent_id, is_duplicate=is_dup,
    )
    mark_report_submitted(int(chat_id), chat_type_key, user.id)
    PENDING.pop(user.id, None)

    # Record the category so the protection panel can display it
    cat = "unknown"
    if reason:
        rlow = reason.lower()
        for key in ("spam", "scam", "adult", "abuse", "other"):
            if key in rlow:
                cat = key
                break
    _set_last_report_category(int(chat_id), cat)

    delivery = await notify_report_parties(
        context.bot,
        responsible_admin_id=owner_id, chat_type_key=chat_type_key,
        chat_title=chat_title, chat_id=int(chat_id), reporter=user,
        reason=reason, message_id=int(message_id), post_link=post_link,
        public_id=public_id, internal_id=internal_id,
    )
    log_action(user.id, "report",
               f"id={public_id} chat={chat_id} msg={message_id} resp={delivery.get('responsible')} "
               f"main={delivery.get('main_admin')} ch={delivery.get('channel')}")

    try:
        counts = _restore_counts_bundle(int(chat_id))
        full_panel2 = build_report_protected_panel(
            chat_title, int(chat_id),
            action="Under Protection",
            report_count=counts.get("24h", 0),
            category=cat,
        )
        bot_username = get_var("bot_username", "")
        add_bot_url = (f"https://t.me/{bot_username}?startchannel=true"
                       if bot_username else get_link("add_channel"))
        kb_add = InlineKeyboardMarkup([
            [styled_button("🫧 Add Bot", url=add_bot_url, style="success")]
        ])
        notice = build_channel_saved_notice(chat_title, bot_username, counts)

        for payload, kb in ((full_panel2, kb_add), (notice, kb_add)):
            try:
                await context.bot.send_message(
                    int(chat_id), payload,
                    parse_mode=ParseMode.HTML,
                    reply_markup=kb,
                    disable_web_page_preview=True,
                )
            except Exception as e:
                log.warning("post report panel to chat: %s", e)
    except Exception as e:
        log.warning("full panel post failed: %s", e)

    lines = [
        "<tg-emoji emoji-id=\"6154278945043776868\">🐶</tg-emoji> " + sb("Your report has been recorded and forwarded."),
        f"🔖 " + sb("Report ID") + f" ➜ <code>{public_id}</code>",
        "<tg-emoji emoji-id=\"6151982803987728559\">🦖</tg-emoji> " + sb("Processed by Report Protection — not Telegram native report."),
    ]
    if is_dup and parent_id:
        lines.append(f"🔁 " + sb("Related report") + f" ➜ <code>{parent_id}</code>")
    await safe_edit_or_send(update, context, panel("Report Submitted", *lines))


