        dg = bool(state.get("dest_groups"))
        dc = bool(state.get("dest_channels"))
        if state.get("quick_users"):
            du, dg, dc = True, False, False
        uids = list_bot_user_ids() if du else []
        gids = _list_registered_group_ids() if dg else []
        cids = _list_registered_channel_ids() if dc else []
        title = "Bot Users Broadcast Preview" if state.get("quick_users") else "Global Broadcast Preview"
