async def cmd_done(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    user = update.effective_user
    if not user:
        return
    state = PENDING.get(user.id)
    if not state or state.get("action") != "file_upload":
        await update.message.reply_text(panel("Upload", "<tg-emoji emoji-id=\"6061942014377724267\">👍</tg-emoji> No pending upload."),
                                        parse_mode=ParseMode.HTML)
        return
    files = state.get("files") or []
    if not files:
        await update.message.reply_text(panel("Upload", "<tg-emoji emoji-id=\"6226302114918828194\">❤️</tg-emoji> No files queued."),
                                        parse_mode=ParseMode.HTML)
        return
    group_id = _gen_token()
    exp_key = state.get("expiry") or "never"
    exp_delta = EXPIRY_OPTIONS.get(exp_key)
    expires_at = (now_ist() + exp_delta).isoformat() if exp_delta else None
    for i, f in enumerate(files):
        store_file(
            owner_id=user.id, file_id=f["file_id"], file_type=f["file_type"],
            file_name=f.get("file_name") or "", file_size=f.get("file_size") or 0,
            caption=f.get("caption") or "", file_group_id=group_id,
            file_order=i, expires_at=expires_at,
        )
    PENDING.pop(user.id, None)
    me = await context.bot.get_me()
    link = f"https://t.me/{me.username}?start={group_id}"
    await update.message.reply_text(
        f"✅ Link generated for {len(files)} file(s).\n\n<code>{link}</code>",
        parse_mode=ParseMode.HTML,
    )


