async def cmd_report(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.effective_message
    user = update.effective_user
    if not msg or not user:
        return
    reply = msg.reply_to_message
    chat = update.effective_chat
    if reply and chat and chat.type in (ChatType.GROUP, ChatType.SUPERGROUP,
                                        ChatType.CHANNEL, "group", "supergroup", "channel"):
        is_ch = chat.type in (ChatType.CHANNEL, "channel")
        chat_type_key = "channel" if is_ch else "group"
        if is_ch:
            with db() as c:
                reg = c.execute(
                    "SELECT * FROM managed_channels WHERE channel_id=? AND COALESCE(status,'active')='active'",
                    (chat.id,),
                ).fetchone()
        else:
            with db() as c:
                reg = c.execute(
                    "SELECT * FROM managed_chats WHERE chat_id=? AND COALESCE(status,'active')='active'",
                    (chat.id,),
                ).fetchone()
        if not reg:
            await msg.reply_text(panel("Invalid Report Target", "<tg-emoji emoji-id=\"6226543702534260736\">😉</tg-emoji> Chat not registered."),
                                 parse_mode=ParseMode.HTML)
            return
        cfg = get_report_protection(chat.id, chat_type_key)
        if not int(cfg.get("enabled", 1)):
            await msg.reply_text(panel("Report Protection Is Not Active",
                                       "<tg-emoji emoji-id=\"6316802577698654299\">😌</tg-emoji> This chat is not protected."),
                                 parse_mode=ParseMode.HTML)
            return
        un = getattr(chat, "username", None) or ""
        if un:
            post_link = f"https://t.me/{un}/{reply.message_id}"
        else:
            cid = str(chat.id)
            internal = cid[4:] if cid.startswith("-100") else cid.lstrip("-")
            post_link = f"https://t.me/c/{internal}/{reply.message_id}"
        token = secrets.token_hex(8)
        PENDING[user.id] = {
            "action": "report_await_reason", "token": token,
            "chat_id": chat.id, "message_id": reply.message_id,
            "post_link": post_link, "chat_type_key": chat_type_key,
            "chat_title": chat.title or str(chat.id),
            "chat_username": un,
            "validated_at": now_ist().isoformat(),
            "started_at": now_ist().isoformat(),
        }
        await msg.reply_text(
            panel("Select Report Reason", "<tg-emoji emoji-id=\"6251044120135994563\">😇</tg-emoji> " + sb("Choose a reason for this report.")),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([
                [styled_button("🚨 Spam", f"r:reason:{token}:spam", style="danger")],
                [styled_button("⚠️ Scam / Fraud", f"r:reason:{token}:scam", style="danger")],
                [styled_button("🛑 Inappropriate Content", f"r:reason:{token}:adult", style="danger")],
                [styled_button("🛡️ Abuse / Harassment", f"r:reason:{token}:abuse", style="danger")],
                [styled_button("Other", f"r:reason:{token}:other", style="primary")],
                [styled_button("⛓ Cancel", "help:hidden", style="danger")],
            ]),
        )
        return
    await msg.reply_text(
        panel("Report",
              "<tg-emoji emoji-id=\"6316611803841299970\">😎</tg-emoji> " + sb("Open Help → Hidden Features → Report."),
              "<tg-emoji emoji-id=\"6314095339552901161\">🔞</tg-emoji> " + sb("Or reply to a message in a registered chat with /report."),
              "<tg-emoji emoji-id=\"6314220842792257477\">😘</tg-emoji> " + sb("Reports go to bot administrators.")),
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([
            [styled_button("🛰️ Hidden Features", "help:hidden", style="success", icon_id="6120482156629201430")],
        ]),
    )


