#              JOBQUEUE REBUILD
# ============================================================
async def memory_sweeper_job(context: ContextTypes.DEFAULT_TYPE) -> None:
    """Prune long-lived in-memory caches to prevent unbounded growth."""
    now_t = time.time()
    try:
        for k in list(_spam_bucket.keys()):
            bucket = _spam_bucket.get(k)
            if not bucket or now_t - max(bucket) > 60:
                _spam_bucket.pop(k, None)
        for k in list(_raid_joins.keys()):
            bucket = _raid_joins.get(k)
            if not bucket or now_t - max(bucket) > 120:
                _raid_joins.pop(k, None)
        for k in list(_nuke_events.keys()):
            bucket = _nuke_events.get(k)
            if not bucket or now_t - max(bucket) > 120:
                _nuke_events.pop(k, None)
        if len(BROADCAST_SKIP_PAUSE) > 5000:
            for item in list(BROADCAST_SKIP_PAUSE)[:2000]:
                BROADCAST_SKIP_PAUSE.discard(item)
        if len(_MILESTONE_CHECK_LOCKS) > 500:
            for cid in list(_MILESTONE_CHECK_LOCKS.keys()):
                lk = _MILESTONE_CHECK_LOCKS.get(cid)
                if lk is not None and not lk.locked():
                    _MILESTONE_CHECK_LOCKS.pop(cid, None)
                    if len(_MILESTONE_CHECK_LOCKS) <= 300:
                        break
    except Exception as e:
        log.warning("memory_sweeper: %s", e)


async def rebuild_jobqueue(app: Application) -> None:
    jq = app.job_queue
    if not jq:
        log.warning("JobQueue unavailable")
        return
    for job in list(jq.jobs()):
        name = job.name or ""
        if name.startswith(("sched_", "timer_", "chdel_", "night_cleanup_", "analytics_")):
            try:
                job.schedule_removal()
            except Exception:
                pass
    now = now_ist()
    with db() as c:
        rows = c.execute("SELECT * FROM schedules WHERE enabled=1").fetchall()
    for r in rows:
        sid = r["schedule_id"]
        try:
            when = datetime.fromisoformat(r["next_run"] or r["schedule_time"])
            if when.tzinfo is None:
                when = when.replace(tzinfo=IST)
            delay = (when - now).total_seconds()
            if delay < 0 and (r["repeat_type"] or "once") == "once":
                continue
            delay = max(1, int(delay))
            jq.run_once(scheduled_group_message, when=delay,
                        data={"schedule_id": sid, "chat_id": r["chat_id"],
                              "text": r["content"] or "",
                              "media_type": r["media_type"],
                              "media_file_id": r["media_file_id"],
                              "repeat_type": r["repeat_type"] or "once"},
                        name=f"sched_{sid}")
        except Exception as e:
            log.warning("rebuild sched %s: %s", sid, e)
    with db() as c:
        trows = c.execute("SELECT * FROM channel_timers WHERE enabled=1").fetchall()
    for t in trows:
        tid = t["timer_id"]
        data = {"timer_id": tid, "channel_id": t["channel_id"], "text": t["content"] or "Timer"}
        try:
            interval = int(t["interval_seconds"] or 0)
            if interval > 0:
                jq.run_repeating(channel_timer_job, interval=max(60, interval), first=5,
                                 data=data, name=f"timer_{tid}")
        except Exception as e:
            log.warning("rebuild timer %s: %s", tid, e)
    with db() as c:
        drows = c.execute(
            "SELECT * FROM channel_message_delete_jobs WHERE status='pending'"
        ).fetchall()
    for d in drows:
        try:
            when = datetime.fromisoformat(d["delete_at"])
            if when.tzinfo is None:
                when = when.replace(tzinfo=IST)
            delay = max(1, int((when - now).total_seconds())) if when > now else 5
            jq.run_once(channel_msg_delete_job, when=delay,
                        data={"channel_id": d["channel_id"], "message_id": d["message_id"],
                              "job_id": d["job_id"]},
                        name=f"chdel_{d['channel_id']}_{d['message_id']}")
        except Exception as e:
            log.warning("rebuild chdel: %s", e)
    with db() as c:
        arows = c.execute(
            "SELECT channel_id, message_id FROM post_analytics WHERE COALESCE(owner_dm_sent,0)=0"
        ).fetchall()
    for a in arows:
        try:
            jq.run_once(per_post_analytics_dm_job, when=24 * 3600,
                        data={"channel_id": a["channel_id"], "message_id": a["message_id"]},
                        name=f"analytics_{a['channel_id']}_{a['message_id']}")
        except Exception:
            pass

    # Reset and register long-running jobs
    for name in ("night_watch", "chdel_watchdog", "stale_cleanup_loop", "milestone_loop", "report_protection_24h", "memory_sweeper"):
        for j in list(jq.jobs()):
            if (j.name or "") == name:
                try:
                    j.schedule_removal()
                except Exception:
                    pass
    jq.run_repeating(night_watch_job, interval=60, first=10, name="night_watch")
    jq.run_repeating(channel_delete_watchdog, interval=30, first=15, name="chdel_watchdog")
    jq.run_repeating(stale_cleanup_job, interval=6 * 3600, first=60, name="stale_cleanup_loop")
    jq.run_repeating(_milestone_loop_job, interval=3600, first=120, name="milestone_loop")
    jq.run_repeating(_report_protection_24h_job, interval=24 * 3600, first=24 * 3600,
                     name="report_protection_24h")
    jq.run_repeating(memory_sweeper_job, interval=300, first=120, name="memory_sweeper")
    log.info("[STARTUP] JobQueue rebuilt — schedules=%s timers=%s chdel=%s analytics=%s",
             len(rows), len(trows), len(drows), len(arows))


