_instance_lock_handle = None


def acquire_instance_lock() -> None:
    global _instance_lock_handle
    if fcntl is None:
        return
    lock_path = os.path.join(os.path.dirname(DB_PATH) or ".", ".bot_instance.lock")
    try:
        _instance_lock_handle = open(lock_path, "a+")
        fcntl.flock(_instance_lock_handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        _instance_lock_handle.seek(0)
        _instance_lock_handle.truncate()
        _instance_lock_handle.write(str(os.getpid()))
        _instance_lock_handle.flush()
        log.info("[INSTANCE] lock acquired pid=%s", os.getpid())
    except BlockingIOError:
        raise SystemExit("Another instance is already running on this host.")
    except Exception as e:
        log.warning("[INSTANCE] lock: %s", e)


