_LINE_PREFIX_COUNTER = [0]
_LINE_PREFIX_EMOJI = ["✨","💎","📌","🔥","⚡","🚀","🌟","🎯","💫","🔮","💠","🩷","⭐","🎁","💥","🎉","🎮","🕹","🎲","🃏"]


def _prefix_one_line(ln):
    """Prefix a single line with premium emoji if it has none."""
    if not ln or not ln.strip():
        return ln
    s = ln.lstrip()
    if s.startswith("<"):
        return ln
    if s.startswith("<tg-emoji"):
        return ln
    try:
        cp0 = ord(s[0])
    except TypeError:
        return ln
    if _is_primary_emoji(cp0):
        return ln
    _key = s[:40]
    idx = _stable_idx(_key, 10**9)
    try:
        cid = _WORKING_IDS[idx % len(_WORKING_IDS)]
    except Exception:
        return ln
    fb = _LINE_PREFIX_EMOJI[idx % len(_LINE_PREFIX_EMOJI)]
    tag = f'<tg-emoji emoji-id="{cid}">{fb}</tg-emoji> '
    indent = ln[:len(ln) - len(s)]
    return indent + tag + s


def _prefix_text(text):
    """Add premium emoji prefix to each line of a multi-line text."""
    if not text or not isinstance(text, str):
        return text
    if "<pre>" in text or "<code>" in text:
        return text
    return "\n".join(_prefix_one_line(ln) for ln in text.split("\n"))


