def _pm_is_html(parse_mode):
    if parse_mode is None:
        return False
    try:
        return str(parse_mode).upper().endswith("HTML") or str(parse_mode).upper() == "HTML"
    except Exception:
        return False


def _prepend_header(text):
    """Prepend _BOT_ONLINE_HEADER if AUTO enabled and size fits."""
    if not text or not isinstance(text, str):
        return text
    if not globals().get("_AUTO_EMOJI_ENABLED", False):
        return text
    if "6120587228709130895" in text:
        return text
    header = globals().get("_BOT_ONLINE_HEADER")
    if not header:
        return text
    if len(text) + len(header) + 1 > 950:
        return text
    return header + "\n" + text


