def _is_horny_trigger(text: str) -> bool:
    if not text:
        return False
    t = " " + str(text).lower().strip() + " "
    # normalize common joins
    t = t.replace("-", " ").replace("_", " ")
    for kw in _HORNY_TRIGGERS:
        if kw in t:
            return True
    return False


async def _uraraka_reply(user_text: str, history=None, user_id=None, chat_type=None) -> str:
    """Zara reply. Admin (7569146424) = unrestricted. Others = restricted."""
    c = _get_groq()
    if not c:
        return "😅 Zara abhi busy hai — admin se bolo Groq check kare."
    try:
        # Choose prompt
        is_admin = False
        try:
            if user_id is not None and int(user_id) == int(_ZARA_ADMIN_ID):
                is_admin = True
        except Exception:
            pass
        _is_private = (chat_type is None) or (str(chat_type).lower() in ("private", "dm"))
        if is_admin and not _is_private:
            # Owner in GROUP chat — boss tone only, no modes, no restriction chain
            sys_prompt = _URARAKA_SYSTEM_BOSS_GROUP
        elif is_admin:
            _uid = user_id if user_id else 0
            # MOOD LOCK: if ANY mode is already active, do not auto-switch.
            # Only /of clears the lock, or explicit /command on/off.
            _locked = (_coding_mode_get(_uid) or _learn_mode_get(_uid)
                       or _horny_mode_get() or _support_mode_get(_uid)
                       or _caring_mode_get(_uid))

            # Sex keyword ALWAYS wins — check first
            _sex_hit   = _is_horny_trigger(user_text)
            _care_hit  = _is_caring_trigger(user_text)

            if _sex_hit:
                # Force horny, clear all others
                _coding_mode_set(_uid, False)
                _learn_mode_set(_uid, False)
                _support_mode_set(_uid, False)
                _caring_mode_set(_uid, False)
                _horny_mode_set(True)
                auto_coding = auto_learn = auto_horny = auto_support = auto_caring = False
            else:
                auto_coding  = _is_coding_trigger(user_text)
                auto_learn   = _is_learn_trigger(user_text)
                auto_horny   = False
                auto_caring  = _care_hit
                auto_support = _is_support_trigger(user_text)

            if not _locked or _sex_hit:
                if auto_coding:
                    _coding_mode_set(_uid, True)
                    _learn_mode_set(_uid, False)
                    _horny_mode_set(False)
                    _support_mode_set(_uid, False)
                    try:
                        asyncio.create_task(_notify_mode(context_bot_ref, _uid, "coding", True))
                    except Exception:
                        pass
                elif auto_learn:
                    _learn_mode_set(_uid, True)
                    _coding_mode_set(_uid, False)
                    _horny_mode_set(False)
                    _support_mode_set(_uid, False)
                    try:
                        asyncio.create_task(_notify_mode(context_bot_ref, _uid, "learn", True))
                    except Exception:
                        pass
                elif auto_horny:
                    _horny_mode_set(True)
                    _coding_mode_set(_uid, False)
                    _learn_mode_set(_uid, False)
                    _support_mode_set(_uid, False)
                    try:
                        asyncio.create_task(_notify_mode(context_bot_ref, _uid, "horny", True))
                    except Exception:
                        pass
                elif auto_caring:
                    _caring_mode_set(_uid, True)
                    _coding_mode_set(_uid, False)
                    _learn_mode_set(_uid, False)
                    _horny_mode_set(False)
                    _support_mode_set(_uid, False)
                    try:
                        asyncio.create_task(_notify_mode(context_bot_ref, _uid, "caring", True))
                    except Exception:
                        pass
                elif auto_support:
                    _support_mode_set(_uid, True)
                    _coding_mode_set(_uid, False)
                    _learn_mode_set(_uid, False)
                    _horny_mode_set(False)
                    _caring_mode_set(_uid, False)
                    try:
                        asyncio.create_task(_notify_mode(context_bot_ref, _uid, "support", True))
                    except Exception:
                        pass

            # Select prompt by current mode (mood lock respected)
            if _coding_mode_get(_uid):
                sys_prompt = _URARAKA_SYSTEM_CODING
            elif _learn_mode_get(_uid):
                sys_prompt = _URARAKA_SYSTEM_LEARN
            elif _horny_mode_get():
                # tier: explicit trigger -> full explicit, else soft
                if _is_explicit_trigger(user_text):
                    sys_prompt = _URARAKA_SYSTEM_HORNY
                else:
                    sys_prompt = _URARAKA_SYSTEM_HORNY_SOFT
            elif _caring_mode_get(_uid):
                sys_prompt = _URARAKA_SYSTEM_CARING
            elif _support_mode_get(_uid):
                sys_prompt = _URARAKA_SYSTEM_SUPPORT
            else:
                sys_prompt = _URARAKA_SYSTEM_ADMIN
        else:
            sys_prompt = _URARAKA_SYSTEM

        if is_admin and history:
            recent = [h.get("content", "") for h in history if h.get("role") == "assistant"]
            recent = [r.strip() for r in recent if r.strip()][-8:]
            if recent:
                snippets = ["- " + r[:40].replace("\n", " ").strip() for r in recent]
                sys_prompt = sys_prompt + (
                    "\n\n★★★ DO NOT REPEAT any of these earlier replies. Use a "
                    "completely different opening, pet name, structure, emoji set: "
                    "★★★\n" + "\n".join(snippets) +
                    "\nProduce a NEW reply that shares no opening sound or pet name "
                    "with any line above."
                )

        msgs = [{"role": "system", "content": sys_prompt}]
        if history:
            msgs.extend(history[-6:])
        msgs.append({"role": "user", "content": user_text})
        _uid2 = user_id if user_id else 0
        _coding = is_admin and _coding_mode_get(_uid2)
        _learn = is_admin and _learn_mode_get(_uid2)
        _horny = is_admin and _horny_mode_get()
        _support = is_admin and _support_mode_get(_uid2)
        if _coding:
            _mt = 1500
            _tp = 0.9
        elif _learn:
            _mt = 900
            _tp = 0.85
        elif _horny:
            _mt = 1400
            _tp = 1.2
        elif _support:
            _mt = 600
            _tp = 1.05
        elif is_admin:
            _mt = 750
            _tp = 1.15
        else:
            _mt = 350
            _tp = 0.85
        resp = await c.chat.completions.create(
            model="openai/gpt-oss-120b",
            messages=msgs, max_tokens=_mt, temperature=_tp,
        )
        raw = (resp.choices[0].message.content or "").strip() or "Hmm 😽"
        # Strip any stray tg-emoji tags
        raw = re.sub(r"<tg-emoji[^>]*>", "", raw).replace("</tg-emoji>", "")
        return raw
    except Exception as e:
        log.error("[ZARA] Groq API error: %s | type=%s", e, type(e).__name__)
        return f"😅 Zara ko problem hai — {str(e)[:80]}"




async def _transcribe_voice(path: str) -> str:
    c = _get_groq()
    if not c:
        return ""
    try:
        with open(path, "rb") as f:
            resp = await c.audio.transcriptions.create(
                file=(path.split("/")[-1], f),
                model="whisper-large-v3-turbo",
            )
        return (resp.text or "").strip()
    except Exception as e:
        log.warning("whisper: %s", e)
        return ""


def _eco_ensure(user_id: int) -> None:
    try:
        with db() as c:
            c.execute("INSERT OR IGNORE INTO economy(user_id, joined_at) VALUES(?,?)",
                      (int(user_id), now_ist().isoformat()))
    except Exception:
        pass


def _eco_get(user_id: int):
    _eco_ensure(user_id)
    with db() as c:
        return c.execute("SELECT * FROM economy WHERE user_id=?", (int(user_id),)).fetchone()


def _eco_update(user_id: int, field: str, delta: int) -> None:
    _eco_ensure(user_id)
    with db() as c:
        c.execute(f"UPDATE economy SET {field}=MAX(0,COALESCE({field},0)+?) WHERE user_id=?",
                  (int(delta), int(user_id)))


def _eco_cooldown_left(last_iso, hours: float):
    if not last_iso:
        return None
    try:
        last = datetime.fromisoformat(last_iso)
        if last.tzinfo is None:
            last = last.replace(tzinfo=IST)
        delta = (last + timedelta(hours=hours)) - now_ist()
        s = int(delta.total_seconds())
        return s if s > 0 else None
    except Exception:
        return None


def _eco_set_cd(user_id: int, field: str) -> None:
    with db() as c:
        c.execute(f"UPDATE economy SET {field}=? WHERE user_id=?",
                  (now_ist().isoformat(), int(user_id)))


def _ai_save_msg(user_id: int, role: str, content: str) -> None:
    try:
        with db() as c:
            c.execute("INSERT INTO ai_chat_history(user_id,role,content,ts) VALUES(?,?,?,?)",
                      (int(user_id), role, content[:2000], now_ist().isoformat()))
            c.execute("DELETE FROM ai_chat_history WHERE user_id=? AND id NOT IN "
                      "(SELECT id FROM ai_chat_history WHERE user_id=? ORDER BY id DESC LIMIT 20)",
                      (int(user_id), int(user_id)))
    except Exception:
        pass


def _ai_get_history(user_id: int):
    try:
        with db() as c:
            rows = c.execute("SELECT role,content FROM ai_chat_history "
                             "WHERE user_id=? ORDER BY id DESC LIMIT 12",
                             (int(user_id),)).fetchall()
        return [{"role": r["role"], "content": r["content"]} for r in reversed(rows)]
    except Exception:
        return []


# ---------- AI Chat (DM text) ----------
async def ai_chat_dm_handler(update, context):
    msg = update.message
    if not msg or not msg.text or not update.effective_user:
        return
    if PENDING.get(update.effective_user.id):
        return
    try:
        await context.bot.send_chat_action(msg.chat_id, "typing")
    except Exception:
        pass
    hist = _ai_get_history(msg.from_user.id)
    reply = await _uraraka_reply(msg.text, hist, user_id=msg.from_user.id if msg.from_user else None, chat_type='private')
    _ai_save_msg(msg.from_user.id, "user", msg.text)
    _ai_save_msg(msg.from_user.id, "assistant", reply)
    try:
        await msg.reply_text(reply)
    except Exception as e:
        log.warning("ai_chat_dm: %s", e)


# ---------- Voice transcribe ----------
async def ai_voice_handler(update, context):
    msg = update.message
    if not msg or not update.effective_user:
        return
    media = msg.voice or msg.audio
    if not media:
        return
    status = None
    try:
        status = await msg.reply_text('<tg-emoji emoji-id="5260652149469094137">🎙️</tg-emoji> Transcribing...')
        tg_file = await context.bot.get_file(media.file_id)
        import tempfile
        tmp_path = tempfile.mktemp(suffix=".ogg")
        await tg_file.download_to_drive(tmp_path)
        transcript = await _transcribe_voice(tmp_path)
        try:
            os.remove(tmp_path)
        except Exception:
            pass
        if not transcript:
            await status.edit_text("💀 Transcribe fail.")
            return
        roast = await _uraraka_reply(f"User voice note: '{transcript}'.", user_id=msg.from_user.id if msg.from_user else None, chat_type=str(getattr(msg.chat, 'type', 'private')).lower())
        await status.edit_text(
            f"🎙️ <b>Decoded:</b> <i>{transcript}</i>\n\n"
            f"💀 <b>Zara:</b> {roast}",
            parse_mode="HTML",
        )
    except Exception as e:
        log.warning("voice: %s", e)
        if status:
            try:
                await status.edit_text("💀 Voice decode fail.")
            except Exception:
                pass


