async def cmd_img(update, context):
    msg = update.message
    if not msg or not msg.text:
        return
    prompt = " ".join(context.args) if context.args else ""
    if not prompt:
        await msg.reply_text("🙄 Prompt de: /img beautiful anime girl")
        return
    user = _eco_get(msg.from_user.id)
    if not user or user["credits"] < 5:
        await msg.reply_text("💀 5 credits lagbe. /daily /work try kar.")
        return
    status = await msg.reply_text('<tg-emoji emoji-id="6147464060305676048">🎨</tg-emoji> Generating... <tg-emoji emoji-id="6046241923539842474">✨</tg-emoji>')
    try:
        import urllib.parse
        url = (f"https://image.pollinations.ai/prompt/{urllib.parse.quote(prompt)}"
               "?width=1024&height=1024&nologo=true&enhance=true")
        async with aiohttp.ClientSession() as s:
            async with s.get(url, timeout=aiohttp.ClientTimeout(total=40)) as r:
                if r.status != 200:
                    raise Exception(f"HTTP {r.status}")
                data = await r.read()
        _eco_update(msg.from_user.id, "credits", -5)
        await status.delete()
        await msg.reply_photo(
            data,
            caption=f"🎨 <b>AI Image</b>\n<i>{prompt}</i>\n\n<i>-5 credits</i>",
            parse_mode="HTML",
        )
    except Exception as e:
        log.warning("img: %s", e)
        try:
            await status.edit_text("💀 Image fail — retry.")
        except Exception:
            pass


