async def _fun_action(update, context, cmd: str, verb: str, emoji: str):
    msg = update.message
    if not msg or not msg.from_user:
        return
    target = msg.reply_to_message.from_user if msg.reply_to_message else None
    if not target:
        await msg.reply_text(f"🙄 Reply karo kisi ko {cmd} karne ke liye.")
        return
    caption = (f"{emoji} {mention_user(msg.from_user)} <b>{verb}</b> "
               f"{mention_user(target)}\n_{random.choice(_FUN_ROASTS[cmd])}_")
    try:
        async with aiohttp.ClientSession() as s:
            async with s.get(f"https://nekos.best/api/v2/{cmd}",
                             timeout=aiohttp.ClientTimeout(total=6)) as r:
                if r.status == 200:
                    d = await r.json()
                    gif = d["results"][0]["url"]
                    await msg.reply_animation(gif, caption=caption, parse_mode="HTML")
                    return
    except Exception:
        pass
    await msg.reply_text(caption, parse_mode="HTML")


