# ---------- Anti-abuse + Filters (group text) ----------
async def group_abuse_filter_handler(update, context):
    msg = update.message
    if not msg or not msg.text or not msg.from_user:
        return
    if msg.from_user.is_bot:
        return
    chat_id = msg.chat_id
    text_lo = msg.text.lower()
    # keyword filters
    try:
        with db() as c:
            rows = c.execute("SELECT keyword,response FROM ai_group_filters WHERE chat_id=?",
                             (chat_id,)).fetchall()
        for r in rows:
            if r["keyword"] in text_lo:
                try:
                    await msg.reply_text(r["response"])
                except Exception:
                    pass
                return
    except Exception:
        pass
    # anti-abuse
    hit = next((g for g in _AI_GAALI if g in text_lo), None)
    if not hit:
        return
    try:
        if await is_group_admin(context.bot, chat_id, msg.from_user.id):
            return
    except Exception:
        pass
    try:
        with db() as c:
            ex = c.execute("SELECT strikes FROM ai_strikes WHERE chat_id=? AND user_id=?",
                           (chat_id, msg.from_user.id)).fetchone()
            n = (int(ex["strikes"]) if ex else 0) + 1
            c.execute("INSERT INTO ai_strikes(chat_id,user_id,strikes,last_at) VALUES(?,?,?,?) "
                      "ON CONFLICT(chat_id,user_id) DO UPDATE SET strikes=excluded.strikes, last_at=excluded.last_at",
                      (chat_id, msg.from_user.id, n, now_ist().isoformat()))
        if n >= 3:
            try:
                await context.bot.ban_chat_member(chat_id, msg.from_user.id)
                with db() as c:
                    c.execute("UPDATE ai_strikes SET strikes=0 WHERE chat_id=? AND user_id=?",
                              (chat_id, msg.from_user.id))
                await msg.reply_text(f'<tg-emoji emoji-id="6316611803841299970">🚫</tg-emoji> {mention_user(msg.from_user)} banned! 3 strikes <tg-emoji emoji-id="6147902731085420231">💀</tg-emoji>')
            except Exception:
                await msg.reply_text("💀 Ban fail — admin rights dao.")
        else:
            roasts = ["Seedha baat kar 💀", "Itna gussa 😤", "Kya bol raha 🤌"]
            await msg.reply_text(
                f'<tg-emoji emoji-id="6271786398404055377">⚠️</tg-emoji> {mention_user(msg.from_user)} — {random.choice(roasts)}\n'
                f"<i>Warning {n}/3</i>",
                parse_mode="HTML",
            )
    except Exception as e:
        log.warning("abuse: %s", e)


# ---------- Filters save/stop/list ----------
async def cmd_save_filter(update, context):
    msg = update.message
    if not msg or not msg.from_user:
        return
    if not await authorized_for_group(context.bot, msg.from_user.id, msg.chat_id):
        await msg.reply_text("💀 Admin only.")
        return
    args = context.args or []
    if not args:
        await msg.reply_text("🙄 /save <keyword> <response>")
        return
    kw = args[0].lower()
    resp = " ".join(args[1:]) if len(args) > 1 else (
        msg.reply_to_message.text if msg.reply_to_message else "")
    if not resp:
        await msg.reply_text("🙄 Response bhi de.")
        return
    try:
        with db() as c:
            c.execute("INSERT OR REPLACE INTO ai_group_filters(chat_id,keyword,response) "
                      "VALUES(?,?,?)", (msg.chat_id, kw, resp))
        await msg.reply_text(f"✅ Filter saved: '{kw}'")
    except Exception as e:
        log.warning("save filter: %s", e)


async def cmd_stop_filter(update, context):
    msg = update.message
    if not msg or not msg.from_user:
        return
    if not await authorized_for_group(context.bot, msg.from_user.id, msg.chat_id):
        return
    args = context.args or []
    if not args:
        await msg.reply_text("🙄 /stop <keyword>")
        return
    kw = args[0].lower()
    with db() as c:
        c.execute("DELETE FROM ai_group_filters WHERE chat_id=? AND keyword=?",
                  (msg.chat_id, kw))
    await msg.reply_text(f"✅ Removed: '{kw}'")


async def cmd_list_filters(update, context):
    msg = update.message
    if not msg:
        return
    with db() as c:
        rows = c.execute("SELECT keyword FROM ai_group_filters WHERE chat_id=?",
                         (msg.chat_id,)).fetchall()
