    kws = "\n".join(f"• `{r['keyword']}`" for r in rows)
    await msg.reply_text(f'<tg-emoji emoji-id="6089396712349114126">🔍</tg-emoji> <b>Filters</b>\n\n{kws}', parse_mode="HTML")


