#              BANK SYSTEM
# ============================================================
def _bank_get(user_id):
    _eco_ensure(user_id)
    with db() as c:
        return c.execute("SELECT coins, bank FROM economy WHERE user_id=?",
                         (int(user_id),)).fetchone()


def _bank_set(user_id, coins=None, bank=None):
    with db() as c:
        if coins is not None:
            c.execute("UPDATE economy SET coins=? WHERE user_id=?", (int(coins), int(user_id)))
        if bank is not None:
            c.execute("UPDATE economy SET bank=? WHERE user_id=?", (int(bank), int(user_id)))


async def cmd_bank(update, context):
    msg = update.message
    if not msg or not msg.from_user:
        return
    row = _bank_get(msg.from_user.id)
    coins = int(row["coins"] or 0); bank = int(row["bank"] or 0)
    await msg.reply_text(
        f'<tg-emoji emoji-id="6224462992742813755">💰</tg-emoji> <b>Bank</b> — {mention_user(msg.from_user)}\n\n'
        f'<tg-emoji emoji-id="6104942084483982100">💎</tg-emoji> Wallet: <code>{coins}</code>\n'
        f'<tg-emoji emoji-id="5893255507380014983">💼</tg-emoji> Bank: <code>{bank}</code>\n\n'
        f'<i>/deposit &lt;amt&gt; · /withdraw &lt;amt&gt;</i>\n'
        f'<i>Bank is safe from /rob</i>',
        parse_mode="HTML",
    )


async def cmd_deposit(update, context):
    msg = update.message
    if not msg or not msg.from_user:
        return
    try:
        amt = int(context.args[0]) if context.args else 0
        assert amt > 0
    except Exception:
        await msg.reply_text("🙄 /deposit &lt;amount&gt;", parse_mode="HTML")
        return
    row = _bank_get(msg.from_user.id)
    coins = int(row["coins"] or 0); bank = int(row["bank"] or 0)
    if coins < amt:
        await msg.reply_text("💀 Not enough coins.")
        return
    _bank_set(msg.from_user.id, coins=coins - amt, bank=bank + amt)
    await msg.reply_text(
        f'<tg-emoji emoji-id="6120688813275616207">✅</tg-emoji> Deposited <code>{amt}</code> to bank.',
        parse_mode="HTML",
    )


async def cmd_withdraw(update, context):
    msg = update.message
    if not msg or not msg.from_user:
        return
    try:
        amt = int(context.args[0]) if context.args else 0
        assert amt > 0
    except Exception:
        await msg.reply_text("🙄 /withdraw &lt;amount&gt;", parse_mode="HTML")
        return
    row = _bank_get(msg.from_user.id)
    coins = int(row["coins"] or 0); bank = int(row["bank"] or 0)
    if bank < amt:
        await msg.reply_text("💀 Not enough in bank.")
        return
    _bank_set(msg.from_user.id, coins=coins + amt, bank=bank - amt)
    await msg.reply_text(
        f'<tg-emoji emoji-id="6120688813275616207">✅</tg-emoji> Withdrew <code>{amt}</code> to wallet.',
        parse_mode="HTML",
    )


