def _lottery_current_round(chat_id: int):
    with db() as c:
        r = c.execute("SELECT * FROM lottery_rounds WHERE chat_id=? AND status='open' "
                      "ORDER BY round_id DESC LIMIT 1", (int(chat_id),)).fetchone()
        if r:
            return r
        cur = c.execute(
            "INSERT INTO lottery_rounds(chat_id,pot,started_at,status) VALUES(?,0,?,'open')",
            (int(chat_id), now_ist().isoformat()),
        )
        rid = cur.lastrowid
    with db() as c:
        return c.execute("SELECT * FROM lottery_rounds WHERE round_id=?", (rid,)).fetchone()


