async def cmd_buyticket(update, context):
    msg = update.message
    if not msg or not msg.from_user:
        return
    r = _lottery_current_round(msg.chat_id)
    PRICE = 100
    row = _eco_get(msg.from_user.id)
    if int(row["coins"] or 0) < PRICE:
        await msg.reply_text(f"💀 Need {PRICE} coins.")
        return
    _eco_update(msg.from_user.id, "coins", -PRICE)
    with db() as c:
        c.execute("INSERT INTO lottery_tickets(round_id,chat_id,user_id,bought_at) "
                  "VALUES(?,?,?,?)",
                  (r["round_id"], msg.chat_id, msg.from_user.id, now_ist().isoformat()))
        c.execute("UPDATE lottery_rounds SET pot=pot+? WHERE round_id=?",
                  (PRICE, r["round_id"]))
    await msg.reply_text(
        f'<tg-emoji emoji-id="6235637621473680408">🎁</tg-emoji> Ticket bought! Pot: <code>{r["pot"] + PRICE}</code>',
        parse_mode="HTML",
    )


async def cmd_lottery_draw(update, context):
    msg = update.message
    if not msg or not msg.from_user:
        return
    if not await authorized_for_group(context.bot, msg.from_user.id, msg.chat_id):
        await msg.reply_text("💀 Admin only.")
        return
    r = _lottery_current_round(msg.chat_id)
    with db() as c:
        rows = c.execute("SELECT user_id FROM lottery_tickets WHERE round_id=?",
                         (r["round_id"],)).fetchall()
    if not rows:
        await msg.reply_text("💀 No tickets in this round.")
        return
    winner_id = random.choice([x["user_id"] for x in rows])
    prize = int(r["pot"] * 0.8)
    _eco_update(winner_id, "coins", prize)
    with db() as c:
        c.execute("UPDATE lottery_rounds SET status='drawn', drawn_at=?, winner_id=?, pot=0 "
                  "WHERE round_id=?",
                  (now_ist().isoformat(), winner_id, r["round_id"]))
    try:
        winner = await context.bot.get_chat_member(msg.chat_id, winner_id)
        uname = mention_user(winner.user)
    except Exception:
        uname = f'<code>{winner_id}</code>'
    await msg.reply_text(
        f'<tg-emoji emoji-id="6107254975912484790">🎉</tg-emoji> <b>Lottery Winner</b>\n\n'
        f'{uname} won <code>{prize}</code> coins!',
        parse_mode="HTML",
    )


