async def cmd_gnumber(update, context):
    msg = update.message
    if not msg or not msg.from_user:
        return
    if not await authorized_for_group(context.bot, msg.from_user.id, msg.chat_id):
        await msg.reply_text("💀 Admin only.")
        return
    lo, hi = 1, 100
    target = random.randint(lo, hi)
    with db() as c:
        c.execute("INSERT OR REPLACE INTO guess_games(chat_id,target,lo,hi,started_by,"
                  "started_at,prize,active) VALUES(?,?,?,?,?,?,500,1)",
                  (msg.chat_id, target, lo, hi, msg.from_user.id, now_ist().isoformat()))
    await msg.reply_text(
        f'<tg-emoji emoji-id="6280663554639007979">❓</tg-emoji> <b>Guess the Number!</b>\n\n'
        f'Range: {lo}–{hi} · Prize: 500 coins\n'
        f'<i>Send /g &lt;number&gt; to guess</i>',
        parse_mode="HTML",
    )


async def cmd_guess(update, context):
    msg = update.message
    if not msg or not msg.from_user:
        return
    args = context.args or []
    if not args:
        await msg.reply_text("🙄 /g &lt;number&gt;", parse_mode="HTML")
        return
    try:
        g = int(args[0])
    except Exception:
        await msg.reply_text("🙄 Number de.")
        return
    with db() as c:
        game = c.execute("SELECT * FROM guess_games WHERE chat_id=? AND active=1",
                         (msg.chat_id,)).fetchone()
    if not game:
        await msg.reply_text("🙄 No active game. Admin: /gnumber")
        return
    with db() as c:
        c.execute("INSERT INTO guess_attempts(chat_id,user_id,guess,at) VALUES(?,?,?,?)",
                  (msg.chat_id, msg.from_user.id, g, now_ist().isoformat()))
    if g == int(game["target"]):
        _eco_update(msg.from_user.id, "coins", int(game["prize"] or 500))
        with db() as c:
            c.execute("UPDATE guess_games SET active=0 WHERE chat_id=?", (msg.chat_id,))
        await msg.reply_text(
            f'<tg-emoji emoji-id="6107254975912484790">🎉</tg-emoji> {mention_user(msg.from_user)} '
            f'guessed <b>{g}</b>! +{game["prize"]} coins',
            parse_mode="HTML",
        )
    elif g < int(game["target"]):
        await msg.reply_text("📈 Higher!")
    else:
        await msg.reply_text("📉 Lower!")


