# ============================================================
async def cmd_sticker(update, context):
    msg = update.message
    if not msg or not msg.from_user:
        return
    reply = msg.reply_to_message
    if not reply or not reply.photo:
        await msg.reply_text("🙄 Reply to a photo + /sticker")
        return
    status = await msg.reply_text(
        '<tg-emoji emoji-id="6147464060305676048">🎨</tg-emoji> Creating sticker pack...',
        parse_mode="HTML",
    )
    try:
        # Create or reuse pack name
        pack_name = f"u{msg.from_user.id}_uraraka_pack_by_{context.bot.username}"
        pack_title = f"{msg.from_user.first_name or 'User'}'s stickers"
        with db() as c:
            row = c.execute("SELECT pack_name FROM user_sticker_packs WHERE user_id=?",
                            (msg.from_user.id,)).fetchone()
        # Download photo
        tg_file = await context.bot.get_file(reply.photo[-1].file_id)
        import tempfile
        tmp = tempfile.mktemp(suffix=".png")
        await tg_file.download_to_drive(tmp)
        # Upload as sticker
        from telegram import InputSticker
        with open(tmp, "rb") as f:
            sticker_file = InputFile(f, filename="sticker.png")
            try:
                # Try to add to existing pack
                await context.bot.add_sticker_to_set(
                    user_id=context.bot.id, name=pack_name,
                    sticker=InputSticker(sticker=sticker_file, emoji_list=["🙂"]),
                )
                action = "added"
            except Exception:
                # Create new pack
                await context.bot.create_new_sticker_set(
                    user_id=context.bot.id, name=pack_name, title=pack_title,
                    stickers=[InputSticker(sticker=sticker_file, emoji_list=["🙂"])],
                )
                action = "created"
                with db() as c:
                    c.execute("INSERT OR REPLACE INTO user_sticker_packs(user_id,pack_name,"
                              "pack_title,created_at) VALUES(?,?,?,?)",
                              (msg.from_user.id, pack_name, pack_title, now_ist().isoformat()))
        try:
            os.remove(tmp)
        except Exception:
            pass
        link = f"https://t.me/addstickers/{pack_name}"
        await status.edit_text(
            f'<tg-emoji emoji-id="6120688813275616207">✅</tg-emoji> Sticker pack {action}!\n\n'
            f'<a href="{link}">Open Sticker Pack</a>',
            parse_mode="HTML",
        )
    except Exception as e:
        log.warning("sticker: %s", e)
        try:
            await status.edit_text(
                f'<tg-emoji emoji-id="6316611803841299970">🚫</tg-emoji> Failed: <code>{str(e)[:120]}</code>',
                parse_mode="HTML",
            )
        except Exception:
            pass


