# ============================================================
async def streak_on_message(update, context):
    msg = update.message
    if not msg or not msg.from_user:
        return
    _eco_ensure(msg.from_user.id)
    with db() as c:
        row = c.execute("SELECT streak, streak_last FROM economy WHERE user_id=?",
                        (msg.from_user.id,)).fetchone()
    today = now_ist().strftime("%Y-%m-%d")
    last = (row["streak_last"] or "")[:10]
    if last == today:
        return
    yesterday = (now_ist() - timedelta(days=1)).strftime("%Y-%m-%d")
    new_streak = int(row["streak"] or 0) + 1 if last == yesterday else 1
    with db() as c:
        c.execute("UPDATE economy SET streak=?, streak_last=? WHERE user_id=?",
                  (new_streak, today, msg.from_user.id))
    if new_streak in (3, 7, 30):
        bonus = {3: 300, 7: 1000, 30: 5000}[new_streak]
        _eco_update(msg.from_user.id, "coins", bonus)
        try:
            await msg.reply_text(
                f'<tg-emoji emoji-id="6107254975912484790">🎉</tg-emoji> {mention_user(msg.from_user)} '
                f'{new_streak}-day streak! +{bonus} coins',
                parse_mode="HTML",
            )
        except Exception:
            pass


