async def cmd_admin_mention(update, context):
    msg = update.message
    if not msg or not msg.from_user:
        return
    if msg.chat.type not in (ChatType.GROUP, ChatType.SUPERGROUP):
        return
    try:
        admins = await context.bot.get_chat_administrators(msg.chat_id)
    except Exception:
        await msg.reply_text(
            '<tg-emoji emoji-id="6316611803841299970">🚫</tg-emoji> Cannot fetch admins.',
            parse_mode="HTML",
        )
        return
    mentions = []
    for a in admins:
        u = a.user
        if u.is_bot:
            continue
        name = html_escape(u.first_name or "Admin")
        mentions.append(f'<a href="tg://user?id={u.id}">{name}</a>')
    if not mentions:
        await msg.reply_text("🧭 No admins to mention.")
        return
    lines = []
    batch = ""
    for m in mentions:
        if len(batch) + len(m) + 2 > 3500:
            lines.append(batch)
            batch = m
        else:
            batch = (batch + " " + m).strip()
    if batch:
        lines.append(batch)
    text = (
        f'<tg-emoji emoji-id="6237864166879663987">👑</tg-emoji> <b>Group Admins</b>\n\n'
        + "\n".join(lines)
    )
    await msg.reply_text(text, parse_mode="HTML", disable_web_page_preview=True)


