#              @all — mention all tracked members
# ============================================================
async def cmd_all_upgrade(update, context):
    msg = update.message
    if not msg or not msg.text or not msg.from_user:
        return
    if msg.chat.type not in (ChatType.GROUP, ChatType.SUPERGROUP):
        return
    if "@all" not in msg.text.lower():
        return
    if not await is_group_admin(context.bot, msg.chat_id, msg.from_user.id):
        return
    try:
        await msg.delete()
    except Exception:
        pass
    try:
        with db() as c:
            rows = c.execute(
                "SELECT user_id, first_name, username FROM group_members "
                "WHERE chat_id=? LIMIT 300",
                (msg.chat_id,),
            ).fetchall()
    except Exception:
        rows = []
    if not rows:
        await context.bot.send_message(
            msg.chat_id,
            '<tg-emoji emoji-id="6316611803841299970">🚫</tg-emoji> No tracked members yet.',
            parse_mode="HTML",
        )
        return
    mentions = []
    for r in rows:
        uid = r["user_id"]
        name = html_escape((r["first_name"] or r["username"] or str(uid))[:40])
        mentions.append(f'<a href="tg://user?id={uid}">{name}</a>')
    header = '<tg-emoji emoji-id="6237864166879663987">👑</tg-emoji> <b>Attention Everyone</b>\n\n'
    batch = ""
    chunks = []
    for m in mentions:
        if len(batch) + len(m) + 2 > 3500:
            chunks.append(batch)
            batch = m
        else:
            batch = (batch + " " + m).strip()
    if batch:
        chunks.append(batch)
    for i, chunk in enumerate(chunks):
        body = (header if i == 0 else "") + chunk
        try:
            await context.bot.send_message(
                msg.chat_id, body,
                parse_mode="HTML", disable_web_page_preview=True,
            )
            import asyncio as _aio
            await _aio.sleep(0.3)
        except Exception as e:
            log.warning("@all send: %s", e)


# ============================================================
#              BROADCAST REPLY SYSTEM
# ============================================================
def _broadcast_mark(chat_id: int, message_id: int, is_channel: int = 0,
                    owner_id: int = 0) -> None:
    try:
        with db() as c:
            c.execute(
                "INSERT OR IGNORE INTO broadcast_messages"
                "(chat_id,message_id,is_channel,owner_id,sent_at) VALUES(?,?,?,?,?)",
                (int(chat_id), int(message_id), int(is_channel), int(owner_id),
                 now_ist().isoformat()),
            )
    except Exception:
        pass


def _broadcast_is_marked(chat_id: int, message_id: int) -> bool:
    try:
        with db() as c:
            r = c.execute(
                "SELECT 1 FROM broadcast_messages WHERE chat_id=? AND message_id=?",
                (int(chat_id), int(message_id)),
            ).fetchone()
            return bool(r)
    except Exception:
        return False


def _broadcast_thread_create(user_id: int, owner_msg_id: int, body: str,
                             origin_chat_id: int, origin_msg_id: int) -> int:
    with db() as c:
        cur = c.execute(
            "INSERT INTO broadcast_threads(user_id,owner_msg_id,user_reply_body,"
            "origin_chat_id,origin_msg_id,status,created_at) VALUES(?,?,?,?,?,?,?)",
            (int(user_id), int(owner_msg_id), body[:2000], int(origin_chat_id),
             int(origin_msg_id), "open", now_ist().isoformat()),
        )
        return int(cur.lastrowid)


def _broadcast_thread_get(thread_id: int):
    with db() as c:
        return c.execute("SELECT * FROM broadcast_threads WHERE id=?",
                         (int(thread_id),)).fetchone()


def _broadcast_thread_mark_replied(thread_id: int, reply_body: str) -> None:
    with db() as c:
        c.execute(
            "UPDATE broadcast_threads SET owner_reply_body=?, status='replied', "
            "replied_at=? WHERE id=?",
            (reply_body[:2000], now_ist().isoformat(), int(thread_id)),
        )


async def broadcast_reply_handler(update, context):
    """Fires when user replies to a marked broadcast message."""
    msg = update.message
    if not msg or not msg.from_user or not msg.reply_to_message:
        return
    # Only in private chats (users) — owner replies handled separately
    if msg.chat.type != ChatType.PRIVATE:
        return
    if not msg.text:
        return

    replied = msg.reply_to_message
    if not _broadcast_is_marked(replied.chat_id, replied.message_id):
        return

    if not MAIN_ADMIN_ID:
        return

    user = msg.from_user
    uname = f"@{user.username}" if user.username else "—"
    name = html_escape(user.full_name or user.first_name or str(user.id))
    body = html_escape(msg.text[:1500])

    # Get original broadcast info
    with db() as c:
        row = c.execute(
            "SELECT origin_chat_id, origin_msg_id FROM broadcast_threads "
            "WHERE origin_msg_id=? AND origin_chat_id=? LIMIT 1",
            (replied.message_id, replied.chat_id),
        ).fetchone()

    # Compose DM to owner
    origin_txt = ""
    if row:
        ocid = row["origin_chat_id"]; omsg = row["origin_msg_id"]
        origin_txt = f'<i>Original: chat</i> <code>{ocid}</code> · <i>msg</i> <code>{omsg}</code>\n'

    panel_text = (
        '<tg-emoji emoji-id="6217521170246274833">✅</tg-emoji> '
        f'<b>{sb("New Broadcast Reply")}</b>\n\n'
        f'<blockquote>'
        f'<tg-emoji emoji-id="6237864166879663987">👑</tg-emoji> <b>{sb("From")}:</b> '
        f'<a href="tg://user?id={user.id}">{name}</a>\n'
        f'<tg-emoji emoji-id="5893255507380014983">💼</tg-emoji> <b>{sb("User")}:</b> <code>{user.id}</code>\n'
        f'<tg-emoji emoji-id="6120688813275616207">✅</tg-emoji> <b>{sb("Username")}:</b> {html_escape(uname)}\n'
        f'{origin_txt}'
        f'</blockquote>\n'
        f'<blockquote>{body}</blockquote>'
    )

    try:
        sent = await context.bot.send_message(
            int(MAIN_ADMIN_ID), panel_text,
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([
                [styled_button("💬 Reply", f"bc_reply:start:{user.id}", style="success")],
            ]),
        )
        tid = _broadcast_thread_create(
            user.id, int(sent.message_id), msg.text,
            replied.chat_id, replied.message_id,
        )
        # Replace keyboard with thread-id based reply
        try:
            await context.bot.edit_message_reply_markup(
                chat_id=int(MAIN_ADMIN_ID), message_id=sent.message_id,
                reply_markup=InlineKeyboardMarkup([
                    [styled_button("💬 Reply", f"bc_reply:start:{tid}", style="success")],
                ]),
            )
        except Exception:
            pass
        with db() as c:
            c.execute("UPDATE broadcast_threads SET id=? WHERE id=?",
                      (tid, tid))
        try:
            await msg.reply_text(
                '<tg-emoji emoji-id="6120688813275616207">✅</tg-emoji> '
                f'<b>{sb("Sent to Owner")}</b>',
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
    except Exception as e:
        log.warning("broadcast reply fwd: %s", e)
        try:
            await msg.reply_text(
                '<tg-emoji emoji-id="6316611803841299970">🚫</tg-emoji> '
                f'<b>{sb("Owner unreachable")}</b>',
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass


async def broadcast_owner_reply_callback(update, context):
    """Owner clicks Reply button — prompt for text."""
    q = update.callback_query
    if not q or not q.from_user:
        return
    if not is_main_admin(q.from_user.id):
        await safe_answer(q, "Owner only.", show_alert=True)
        return
    parts = (q.data or "").split(":")
    if len(parts) < 3:
        return
    try:
        tid = int(parts[2])
    except Exception:
        return
    thread = _broadcast_thread_get(tid)
    if not thread:
        await safe_answer(q, "Thread not found.", show_alert=True)
        return
    PENDING[q.from_user.id] = {
        "action": "bc_owner_reply",
        "thread_id": tid,
        "user_id": int(thread["user_id"]),
    }
    await safe_answer(q, "Reply mode active.")
    try:
        await q.message.reply_text(
            '<tg-emoji emoji-id="6237864166879663987">👑</tg-emoji> '
            f'<b>{sb("Send your reply now")}</b>\n'
            f'<i>This will be delivered to user</i> <code>{thread["user_id"]}</code>',
            parse_mode=ParseMode.HTML,
        )
    except Exception:
        pass


async def broadcast_owner_reply_text(update, context):
    """Fires when owner sends reply after clicking Reply button."""
    msg = update.message
    if not msg or not msg.from_user or not msg.text:
        return
    st = PENDING.get(msg.from_user.id)
    if not st or st.get("action") != "bc_owner_reply":
        return
    if not is_main_admin(msg.from_user.id):
        return
    tid = int(st.get("thread_id") or 0)
    target_user = int(st.get("user_id") or 0)
    PENDING.pop(msg.from_user.id, None)
    thread = _broadcast_thread_get(tid)
    if not thread or not target_user:
        await msg.reply_text("🚫 Thread missing.", parse_mode=ParseMode.HTML)
        return

    reply_body = html_escape(msg.text[:1500])
    text = (
        '<tg-emoji emoji-id="6237864166879663987">👑</tg-emoji> '
        f'<b>{sb("Reply from Owner")}</b>\n\n'
        f'<blockquote>{reply_body}</blockquote>'
    )
    try:
        await context.bot.send_message(int(target_user), text, parse_mode=ParseMode.HTML)
        _broadcast_thread_mark_replied(tid, msg.text)
        try:
            await msg.reply_text(
                '<tg-emoji emoji-id="6120688813275616207">✅</tg-emoji> '
                f'<b>{sb("Delivered")}</b>',
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
    except Exception as e:
        log.warning("bc owner reply: %s", e)
        try:
            await msg.reply_text(
                '<tg-emoji emoji-id="6316611803841299970">🚫</tg-emoji> '
                f'<b>{sb("Delivery failed")}</b>',
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass


