def _btn_override_get(callback_data: str):
    """Return (label, icon_id) or None."""
    try:
        with db() as c:
            r = c.execute(
                "SELECT custom_label, custom_icon_id FROM ui_button_overrides "
                "WHERE callback_data=?", (str(callback_data),)
            ).fetchone()
        if r:
            return (r["custom_label"], r["custom_icon_id"])
    except Exception:
        pass
    return (None, None)


def _btn_override_set(callback_data: str, label: str, icon_id: str, by: int) -> None:
    with db() as c:
        c.execute(
            "INSERT INTO ui_button_overrides(callback_data,custom_label,custom_icon_id,"
            "updated_at,updated_by) VALUES(?,?,?,?,?) "
            "ON CONFLICT(callback_data) DO UPDATE SET "
            "custom_label=excluded.custom_label, custom_icon_id=excluded.custom_icon_id, "
            "updated_at=excluded.updated_at, updated_by=excluded.updated_by",
            (str(callback_data), (label or "").strip() or None,
             (icon_id or "").strip() or None,
             now_ist().isoformat(), int(by)),
        )


def _btn_override_clear(callback_data: str) -> None:
    with db() as c:
        c.execute("DELETE FROM ui_button_overrides WHERE callback_data=?",
                  (str(callback_data),))


def _btn_override_list():
    with db() as c:
        return c.execute(
            "SELECT callback_data, custom_label, custom_icon_id, updated_at "
            "FROM ui_button_overrides ORDER BY updated_at DESC"
        ).fetchall()


def _text_slot_get(slot_id: str):
    try:
        with db() as c:
            r = c.execute(
                "SELECT original_text, custom_text, custom_icon_id FROM ui_text_slots "
                "WHERE slot_id=?", (str(slot_id),)
            ).fetchone()
        if r:
            return dict(r)
    except Exception:
        pass
    return None


def _text_slot_set(slot_id: str, original: str, text: str, icon_id: str, by: int) -> None:
    with db() as c:
        c.execute(
            "INSERT INTO ui_text_slots(slot_id,original_text,custom_text,custom_icon_id,"
            "updated_at,updated_by) VALUES(?,?,?,?,?,?) "
            "ON CONFLICT(slot_id) DO UPDATE SET "
            "custom_text=excluded.custom_text, custom_icon_id=excluded.custom_icon_id, "
            "updated_at=excluded.updated_at, updated_by=excluded.updated_by",
            (str(slot_id), (original or "")[:300],
             (text or "").strip() or None,
             (icon_id or "").strip() or None,
             now_ist().isoformat(), int(by)),
        )


def _text_slot_clear(slot_id: str) -> None:
    with db() as c:
        c.execute("DELETE FROM ui_text_slots WHERE slot_id=?", (str(slot_id),))


def _text_slot_apply(text: str) -> str:
    """Apply all text slot overrides to a text blob."""
    if not text or not isinstance(text, str):
        return text or ""
    try:
        with db() as c:
            rows = c.execute(
                "SELECT original_text, custom_text, custom_icon_id FROM ui_text_slots"
            ).fetchall()
    except Exception:
        return text
    for r in rows:
        orig = r["original_text"] or ""
        cust = r["custom_text"]
        icon = r["custom_icon_id"]
        if not orig:
            continue
        if cust and icon:
            repl = f'<tg-emoji emoji-id="{icon}">{cust}</tg-emoji>'
        elif cust:
            repl = cust
        elif icon:
            repl = f'<tg-emoji emoji-id="{icon}">{orig[:2]}</tg-emoji>'
        else:
            continue
        if orig in text:
            text = text.replace(orig, repl)
    return text


# ---- Patch styled_button to consult overrides ----
_ORIG_STYLED_BUTTON = styled_button


def styled_button(text, callback_data=None, url=None, *, style="primary", icon_id=None):
    # Consult DB override
    if callback_data is not None:
        try:
            lbl, ic = _btn_override_get(callback_data)
            if lbl is not None:
                text = lbl
            if ic:
                icon_id = ic
        except Exception:
            pass
    return _ORIG_STYLED_BUTTON(text, callback_data=callback_data, url=url,
                                style=style, icon_id=icon_id)


# ---- Bot profile cache ----
async def _cache_bot_profile(bot) -> None:
    try:
        me = await bot.get_me()
        photo_id = None
        try:
            photos = await bot.get_user_profile_photos(user_id=me.id, limit=1)
            if photos and photos.total_count:
                photo_id = photos.photos[0][-1].file_id
        except Exception:
            pass
        with db() as c:
            c.execute(
                "INSERT INTO bot_profile_cache(id,bot_name,bot_username,bot_id,"
                "photo_file_id,updated_at) VALUES(1,?,?,?,?,?) "
                "ON CONFLICT(id) DO UPDATE SET "
                "bot_name=excluded.bot_name, bot_username=excluded.bot_username, "
                "bot_id=excluded.bot_id, photo_file_id=excluded.photo_file_id, "
                "updated_at=excluded.updated_at",
                (me.first_name or "", me.username or "", int(me.id),
                 photo_id, now_ist().isoformat()),
            )
    except Exception as e:
        log.warning("cache bot profile: %s", e)


