async def cb_bot_identity_show(update, context):
    """Bot Identity — premium icons + copy + change name/logo."""
    from telegram.ext import ApplicationHandlerStop
    q = update.callback_query
    user = q.from_user
    try:
        if not is_main_admin(user.id):
            await safe_answer(q, "Main admin only.", show_alert=True)
            raise ApplicationHandlerStop
        try:
            await _cache_bot_profile(context.bot)
        except Exception as e:
            log.warning("cache profile: %s", e)
        with db() as c:
            r = c.execute("SELECT * FROM bot_profile_cache WHERE id=1").fetchone()
        if not r:
            await safe_answer(q, "No cache.", show_alert=True)
            raise ApplicationHandlerStop
        bot_name_v = r["bot_name"] or "?"
        bot_uname_v = (r["bot_username"] or "").lstrip("@")
        bot_id_v = r["bot_id"] or 0
        photo = r["photo_file_id"]

        caption = (
            '<tg-emoji emoji-id="6237864166879663987">👑</tg-emoji> <b>Bot Identity</b>\n\n'
            '<blockquote>'
            '<tg-emoji emoji-id="6104715731117547405">💎</tg-emoji> '
            '<b>Name:</b> ' + html_escape(bot_name_v) +
            '</blockquote>\n'
            '<blockquote>'
            '<tg-emoji emoji-id="6104659630254726636">✅</tg-emoji> '
            '<b>Username:</b> @' + html_escape(bot_uname_v) +
            '</blockquote>\n'
            '<blockquote>'
            '<tg-emoji emoji-id="6105189070873305867">☁️</tg-emoji> '
            '<b>ID:</b> <code>' + str(bot_id_v) + '</code>'
            '</blockquote>'
        )
        uname_copy = "@" + bot_uname_v if bot_uname_v else "?"

        # Copy buttons with premium icons + style
        try:
            from telegram import CopyTextButton
            copy_name_btn = InlineKeyboardButton(
                text="📋 Copy Name",
                copy_text=CopyTextButton(text=str(bot_name_v)[:256]),
                style="primary",
                icon_custom_emoji_id="5893297890117292323",
            )
            copy_uname_btn = InlineKeyboardButton(
                text="📋 Copy Username",
                copy_text=CopyTextButton(text=uname_copy[:256]),
                style="primary",
                icon_custom_emoji_id="5893297890117292323",
            )
        except Exception as e:
            log.warning("copy btn: %s", e)
            copy_name_btn = styled_button("📋 Copy Name", "a:copy_name", style="primary")
            copy_uname_btn = styled_button("📋 Copy Username", "a:copy_uname", style="primary")

        kb = InlineKeyboardMarkup([
            [copy_name_btn],
            [copy_uname_btn],
            [styled_button("🏷️ Change Name", "a:bot_name_edit",
                           style="success", icon_id="6237930648678440568")],
            [styled_button("🖼️ Change Logo", "a:bot_logo_edit",
                           style="success", icon_id="6147464060305676048")],
            [styled_button("👁 Show DP", "a:show_dp",
                           style="primary", icon_id="6104715731117547405")],
            [styled_button("🔄 Refresh", "a:bot_identity",
                           style="primary", icon_id="6105189070873305867")],
            [styled_button("↩️ Back", "a:settings",
                           style="danger", icon_id="6105059663508676671")],
        ])

        try:
            await safe_delete(context.bot, q.message.chat_id, q.message.message_id)
        except Exception:
            pass
        if photo:
            try:
                await context.bot.send_photo(
                    q.message.chat_id, photo, caption=caption,
                    parse_mode=ParseMode.HTML, reply_markup=kb,
                )
                raise ApplicationHandlerStop
            except ApplicationHandlerStop:
                raise
            except Exception as e:
                log.warning("send_photo: %s", e)
        await context.bot.send_message(
            q.message.chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=kb,
        )
    except ApplicationHandlerStop:
        raise
    except Exception as e:
        log.error("cb_bot_identity_show FAIL: %s", e)
        try:
            await safe_answer(q, f"Error: {str(e)[:80]}", show_alert=True)
        except Exception:
            pass
    finally:
        raise ApplicationHandlerStop


