# ---- Pending text handler for UI ----
async def ui_pending_text(update, context):
    msg = update.message
    if not msg or not msg.from_user or not msg.text:
        return
    st = PENDING.get(msg.from_user.id)
    if not st or not str(st.get("action", "")).startswith("ui_"):
        return
    if not is_main_admin(msg.from_user.id):
        PENDING.pop(msg.from_user.id, None)
        return
    action = st["action"]

    if action == "ui_btn_add":
        cb_data = msg.text.strip()
        if not cb_data:
            await msg.reply_text("🚫 Invalid callback_data.", parse_mode=ParseMode.HTML)
            return
        st["cb_data"] = cb_data
        st["action"] = "ui_btn_add_label"
        PENDING[msg.from_user.id] = st
        await msg.reply_text(
            '<b>Step 2/3</b> — Send the new button label',
            parse_mode=ParseMode.HTML,
        )
        return

    if action == "ui_btn_add_label":
        st["new_label"] = msg.text.strip()
        st["action"] = "ui_btn_add_icon"
        PENDING[msg.from_user.id] = st
        await msg.reply_text(
            '<b>Step 3/3</b> — Send the premium emoji ID (numeric)',
            parse_mode=ParseMode.HTML,
        )
        return

    if action == "ui_btn_add_icon":
        icon_id = msg.text.strip()
        cb_data = st.get("cb_data", "")
        label = st.get("new_label", "")
        _btn_override_set(cb_data, label, icon_id, msg.from_user.id)
        PENDING.pop(msg.from_user.id, None)
        await msg.reply_text(
            f'✅ Button override saved\n<code>{cb_data}</code> → {label} (icon {icon_id})',
            parse_mode=ParseMode.HTML,
        )
        return

    if action == "ui_btn_icon_only":
        cb = st.get("cb_data", "")
        icon = msg.text.strip()
        lbl, old_ic = _btn_override_get(cb)
        # Keep existing label if any
        with db() as c:
            r = c.execute("SELECT label FROM ui_button_registry WHERE callback_data=?",
                          (cb,)).fetchone()
        base_lbl = (r["label"] if r else "") or cb
        final_label = lbl if lbl else base_lbl
        _btn_override_set(cb, final_label, icon, msg.from_user.id)
        PENDING.pop(msg.from_user.id, None)
        await msg.reply_text(
            f'✅ Emoji ID set for <code>{html_escape(cb)}</code>',
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([
                [styled_button("↩️ Back to Button", f"a:ui_btn_edit:{cb}", style="primary")],
            ]),
        )
        return

    if action == "ui_btn_label_only":
        cb = st.get("cb_data", "")
        newlbl = msg.text.strip()
        lbl, old_ic = _btn_override_get(cb)
        _btn_override_set(cb, newlbl, old_ic or "", msg.from_user.id)
        PENDING.pop(msg.from_user.id, None)
        await msg.reply_text(
            f'✅ Label set for <code>{html_escape(cb)}</code>',
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([
                [styled_button("↩️ Back to Button", f"a:ui_btn_edit:{cb}", style="primary")],
            ]),
        )
        return

    if action == "ui_btn_remove":
        _btn_override_clear(msg.text.strip())
        PENDING.pop(msg.from_user.id, None)
        await msg.reply_text(
            f'✅ Override removed: <code>{msg.text.strip()}</code>',
            parse_mode=ParseMode.HTML,
        )
        return

    if action == "ui_text_add":
        st["slot_id"] = msg.text.strip()
        st["action"] = "ui_text_add_orig"
        PENDING[msg.from_user.id] = st
        await msg.reply_text(
            '<b>Step 2/4</b> — Send the ORIGINAL text (exact match to replace)',
            parse_mode=ParseMode.HTML,
        )
        return

    if action == "ui_text_add_orig":
        st["orig"] = msg.text
        st["action"] = "ui_text_add_new"
        PENDING[msg.from_user.id] = st
        await msg.reply_text(
            '<b>Step 3/4</b> — Send the NEW text (plain)',
            parse_mode=ParseMode.HTML,
        )
        return

    if action == "ui_text_add_new":
        st["new"] = msg.text.strip()
        st["action"] = "ui_text_add_icon"
        PENDING[msg.from_user.id] = st
        await msg.reply_text(
            '<b>Step 4/4</b> — Send the premium emoji ID',
            parse_mode=ParseMode.HTML,
        )
        return

    if action == "ui_text_add_icon":
        icon_id = msg.text.strip()
        _text_slot_set(st.get("slot_id", ""), st.get("orig", ""),
                       st.get("new", ""), icon_id, msg.from_user.id)
        PENDING.pop(msg.from_user.id, None)
        await msg.reply_text(
            f'✅ Text override saved (#{st.get("slot_id","")})',
            parse_mode=ParseMode.HTML,
        )
        return

    if action == "ui_text_remove":
        _text_slot_clear(msg.text.strip())
        PENDING.pop(msg.from_user.id, None)
        await msg.reply_text(
            f'✅ Text override removed: #{msg.text.strip()}',
            parse_mode=ParseMode.HTML,
        )
        return


# ============================================================
#              EMOJI CUSTOM FILE MANAGER
# ============================================================
_CUSTOM_EMOJI_FILE = "premiumemoji_custom.txt"


def _custom_emoji_path():
    try:
        return Path(__file__).resolve().with_name(_CUSTOM_EMOJI_FILE)
    except Exception:
        return Path(_CUSTOM_EMOJI_FILE)


def _custom_emoji_load() -> list:
    """Load (emoji, id) pairs from the custom file."""
    out = []
    p = _custom_emoji_path()
    if not p.is_file():
        return out
    try:
        for line in p.read_text(encoding="utf-8", errors="ignore").splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            # Format 1: emoji — id
            import re as _re
            m = _re.match(r'^(\S+)\s*[—\-:]+\s*(\d{5,30})\s*$', line)
            if m:
                out.append((m.group(1), m.group(2)))
                continue
            # Format 2: id emoji
            m = _re.match(r'^(\d{5,30})\s+\[(.+?)\]\s*$', line)
            if m:
                out.append((m.group(2), m.group(1)))
                continue
            m = _re.match(r'^(\d{5,30})\s+(\S+)\s*$', line)
            if m:
                out.append((m.group(2), m.group(1)))
    except Exception:
        pass
    # Dedupe by id
    seen = set()
    uniq = []
    for e, cid in out:
        if cid not in seen:
            uniq.append((e, cid))
            seen.add(cid)
    return uniq


def _custom_emoji_append(pairs: list) -> int:
    """Append new (emoji, id) pairs to the custom file. Returns count added."""
    if not pairs:
        return 0
    p = _custom_emoji_path()
    existing = set(cid for _, cid in _custom_emoji_load())
    added = []
    for e, cid in pairs:
        if cid not in existing:
            added.append((e, cid))
            existing.add(cid)
    if not added:
        return 0
    try:
        with p.open("a", encoding="utf-8") as f:
            for e, cid in added:
                f.write(f"{e} — {cid}\n")
    except Exception as e:
        log.warning("custom emoji write: %s", e)
        return 0
    # Also index in DB
    try:
        with db() as c:
            for e, cid in added:
                c.execute(
                    "INSERT OR IGNORE INTO emoji_custom(emoji,emoji_id,added_by,added_at) "
                    "VALUES(?,?,?,?)",
                    (e, cid, 0, now_ist().isoformat()),
                )
    except Exception:
        pass
    return len(added)


def _custom_emoji_count() -> int:
    return len(_custom_emoji_load())


async def _custom_emoji_send_file(bot, chat_id: int) -> bool:
    """Send the custom emoji file as TXT document."""
    p = _custom_emoji_path()
    if not p.is_file():
        try:
            p.write_text("# Emoji Custom File — add lines like: emoji — id\n", encoding="utf-8")
        except Exception:
            return False
    try:
        with p.open("rb") as f:
            await bot.send_document(
                chat_id,
                document=f,
                filename=_CUSTOM_EMOJI_FILE,
                caption=(
                    '<tg-emoji emoji-id="6104715731117547405">💎</tg-emoji> '
                    '<b>Emoji Custom File</b>\n\n'
                    f'<blockquote>Total lines: {_custom_emoji_count()}</blockquote>\n'
                    '<blockquote>Format: <code>emoji — id</code></blockquote>'
                ),
                parse_mode=ParseMode.HTML,
            )
        return True
    except Exception as e:
        log.warning("send custom emoji file: %s", e)
        return False


async def _custom_emoji_purge_file() -> None:
    """Clear the custom emoji file."""
    try:
        p = _custom_emoji_path()
        if p.is_file():
            p.write_text("# Emoji Custom File — add lines like: emoji — id\n", encoding="utf-8")
        with db() as c:
            c.execute("DELETE FROM emoji_custom")
    except Exception:
        pass


