async def cb_emoji_custom_reload(update, context):
    q = update.callback_query
    user = q.from_user
    if not is_main_admin(user.id):
        await safe_answer(q, "Main admin only.", show_alert=True)
        return
    # Force reload of pool by resetting the loaded flag
    try:
        globals()["_PREMIUM_MAP_LOADED"] = False
        pairs = _custom_emoji_load()
        for e, cid in pairs:
            try:
                globals()["_PREMIUM_MAP"][e] = cid
            except Exception:
                pass
        try:
            globals()["_PREMIUM_KEYS"] = sorted(
                globals()["_PREMIUM_MAP"].keys(), key=len, reverse=True
            )
        except Exception:
            pass
        await safe_answer(q, f"Reloaded {len(pairs)} custom emoji.", show_alert=True)
    except Exception as e:
        await safe_answer(q, f"Reload failed: {str(e)[:60]}", show_alert=True)


