            [styled_button("✏️ Change Emoji ID", f"a:ui_btn_seticon:{cb}", style="success")],
            [styled_button("📝 Change Label", f"a:ui_btn_setlabel:{cb}", style="primary")],
            [styled_button("♻️ Reset", f"a:ui_btn_reset:{cb}", style="danger")],
