# ============================================================
#              TEXT REGISTRY SCANNER
# ============================================================
def _scan_texts() -> int:
    """Parse main.py — find all panel() calls, register titles + lines."""
    try:
        import ast as _ast
        with open(__file__, "r", encoding="utf-8") as f:
            tree = _ast.parse(f.read())
    except Exception as e:
        log.warning("text scan parse: %s", e)
        return 0

    found = []  # (slot_id, source, text)

    def _extract(node):
        if isinstance(node, _ast.Constant) and isinstance(node.value, str):
            return node.value
        if isinstance(node, _ast.JoinedStr):
            parts = []
            for v in node.values:
                if isinstance(v, _ast.Constant) and isinstance(v.value, str):
                    parts.append(v.value)
                else:
                    parts.append("{?}")
            return "".join(parts)
        if isinstance(node, _ast.BinOp):  # "a" + sb("b") + ...
            def _walk(n):
                if isinstance(n, _ast.Constant) and isinstance(n.value, str):
                    return n.value
                if isinstance(n, _ast.BinOp):
                    return _walk(n.left) + _walk(n.right)
                if isinstance(n, _ast.Call):
                    for a in n.args:
                        s = _walk(a)
                        if s:
                            return s
                if isinstance(n, _ast.JoinedStr):
                    return _extract(n)
                return ""
            return _walk(node)
        return ""

    for node in _ast.walk(tree):
        if not isinstance(node, _ast.Call):
            continue
        fname = ""
        if isinstance(node.func, _ast.Name):
            fname = node.func.id
        elif isinstance(node.func, _ast.Attribute):
            fname = node.func.attr
        if fname not in ("panel", "quote_panel"):
            continue
        if not node.args:
            continue
        # First arg = title
        title = _extract(node.args[0]).strip()
        if title:
            sid = "T:" + title[:80]
            found.append((sid, "panel", title))
        # Subsequent args = detail lines
        for i, a in enumerate(node.args[1:], 1):
            line = _extract(a).strip()
            if line and len(line) > 3:
                sid = "L:" + line[:80]
                found.append((sid, "panel", line))

    # dedupe by slot_id
    seen = set()
    uniq = []
    for sid, src_, txt in found:
        if sid in seen:
            continue
        seen.add(sid)
        uniq.append((sid, src_, txt))

    added = 0
    try:
        with db() as c:
            for sid, src_, txt in uniq:
                r = c.execute(
                    "INSERT OR IGNORE INTO ui_text_registry(slot_id,source,text,first_seen) "
                    "VALUES(?,?,?,?)",
                    (sid, src_, txt[:500], now_ist().isoformat()),
                )
                if r.rowcount:
                    added += 1
    except Exception as e:
        log.warning("text registry insert: %s", e)
    log.info("[UI] text registry scanned: %d found, %d new", len(uniq), added)
    return len(uniq)


def _list_text_registry():
    try:
        with db() as c:
            return c.execute(
                "SELECT slot_id, source, text FROM ui_text_registry ORDER BY slot_id"
            ).fetchall()
    except Exception:
        return []


