_TEXT_PICKER_PAGE = 8


async def cb_ui_text_picker(update, context):
    q = update.callback_query
    if not is_main_admin(q.from_user.id):
        await safe_answer(q, "Main admin only.", show_alert=True)
        return
    parts = (q.data or "").split(":")
    page = 1
    if len(parts) >= 3:
        try:
            page = max(1, int(parts[2]))
        except Exception:
            page = 1
    rows = _list_text_registry()
    total = len(rows)
    pages = max(1, (total + _TEXT_PICKER_PAGE - 1) // _TEXT_PICKER_PAGE)
    page = min(page, pages)
    start = (page - 1) * _TEXT_PICKER_PAGE
    chunk = rows[start:start + _TEXT_PICKER_PAGE]

    kb = []
    for r in chunk:
        sid = r["slot_id"]
        text = r["text"] or ""
        # check override
        ov = _text_slot_get(sid)
        mark = "✏️ " if (ov and (ov.get("custom_text") or ov.get("custom_icon_id"))) else ""
        label = mark + text[:40]
        # callback needs to be compact — use short hash index
        # use the sid itself but paginated — length may exceed 64 bytes for TG
        # we use a small id: index in registry
        idx = rows.index(r) + 1
        kb.append([styled_button(label, f"a:ui_text_edit:{idx}", style="primary")])

    nav = []
    if page > 1:
        nav.append(styled_button("◀️ Prev", f"a:ui_text_picker:{page-1}", style="primary"))
    nav.append(styled_button(f"{page}/{pages}", f"a:ui_text_picker:{page}", style="primary"))
    if page < pages:
        nav.append(styled_button("Next ▶️", f"a:ui_text_picker:{page+1}", style="primary"))
    kb.append(nav)
    kb.append([styled_button("↩️ Back", "a:ui_text", style="danger")])

    await safe_edit_or_send(
        update, context,
        panel("Pick a Text",
              f"Total texts: {total}",
              "<i>Tap to change emoji + emoji ID.</i>"),
        InlineKeyboardMarkup(kb),
    )


