# ---- Multi-step pending text handler ----
async def ui_text_multi_pending(update, context):
    msg = update.message
    if not msg or not msg.from_user or not msg.text:
        return
    st = PENDING.get(msg.from_user.id)
    if not st:
        return
    action = st.get("action", "")
    if not action.startswith("ui_text_"):
        return
    if not is_main_admin(msg.from_user.id):
        PENDING.pop(msg.from_user.id, None)
        return

    idx = int(st.get("idx") or 0)
    rows = _list_text_registry()
    if idx < 1 or idx > len(rows):
        PENDING.pop(msg.from_user.id, None)
        await msg.reply_text("🚫 Index invalid.", parse_mode=ParseMode.HTML)
        return
    r = rows[idx - 1]
    sid = r["slot_id"]
    orig = r["text"] or ""

    if action == "ui_text_pick_emoji":
        # Store emoji char, wait for ID
        st["emoji_char"] = msg.text.strip()[:8]
        st["action"] = "ui_text_pick_id"
        PENDING[msg.from_user.id] = st
        await msg.reply_text(
            f'✅ Emoji set: {html_escape(st["emoji_char"])}\n\n'
            '<b>Step 2 of 2 — Send the emoji ID (numeric)</b>',
            parse_mode=ParseMode.HTML,
        )
        return

    if action == "ui_text_pick_id":
        icon_id = msg.text.strip()
        if not icon_id.isdigit():
            await msg.reply_text("🚫 ID must be numeric.", parse_mode=ParseMode.HTML)
            return
        emoji_char = st.get("emoji_char") or "😀"
        # Save — override icon with char, keep custom_text as emoji_char
        _text_slot_set(sid, orig, emoji_char, icon_id, msg.from_user.id)
        PENDING.pop(msg.from_user.id, None)
        await msg.reply_text(
            f'✅ Done\n\n'
            f'<b>Slot:</b> <code>{html_escape(sid[:60])}</code>\n'
            f'<b>Emoji:</b> <tg-emoji emoji-id="{icon_id}">{html_escape(emoji_char)}</tg-emoji>',
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([
                [styled_button("↩️ Back to Text", f"a:ui_text_edit:{idx}", style="primary")],
            ]),
        )
        return

    if action == "ui_text_newtext_only":
        new_text = msg.text.strip()
        if not new_text:
            return
        ov = _text_slot_get(sid) or {}
        cur_icon = ov.get("custom_icon_id") or ""
        _text_slot_set(sid, orig, new_text, cur_icon, msg.from_user.id)
        PENDING.pop(msg.from_user.id, None)
        await msg.reply_text(
            f'✅ Text updated\n\n'
            f'<b>Slot:</b> <code>{html_escape(sid[:60])}</code>\n'
            f'<b>New:</b> {html_escape(new_text[:80])}',
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([
                [styled_button("↩️ Back to Text", f"a:ui_text_edit:{idx}", style="primary")],
            ]),
        )
        return


