async def cb_bc_emoji_extract(update, context):
    q = update.callback_query
    if not is_main_admin(q.from_user.id):
        await safe_answer(q, "Main admin only.", show_alert=True)
        return
    pool = list_emoji_pool()
    if not pool:
        await safe_answer(q, "Pool empty.", show_alert=True)
        return
    import io
    lines = ["# Broadcast Emoji Pool — format: emoji — id"]
    for r in pool:
        lines.append(f"{r['emoji']} — {r['emoji_id']}")
    buf = io.BytesIO("\n".join(lines).encode("utf-8"))
    buf.name = "broadcast_emoji_pool.txt"
    try:
        await context.bot.send_document(
            q.message.chat_id, document=buf,
            filename="broadcast_emoji_pool.txt",
            caption=(
                '<tg-emoji emoji-id="6104715731117547405">💎</tg-emoji> '
                f'<b>Pool extracted</b> — {len(pool)} emoji'
            ),
            parse_mode=ParseMode.HTML,
        )
        await safe_answer(q, "File sent.")
    except Exception as e:
        await safe_answer(q, f"Failed: {str(e)[:60]}", show_alert=True)


