# ============================================================
#              ADMIN EMOJI POOL (Panel + Buttons)
# ============================================================
def list_admin_emoji():
    try:
        with db() as c:
            return c.execute(
                "SELECT emoji, emoji_id FROM admin_emoji_pool ORDER BY id"
            ).fetchall()
    except Exception:
        return []


def add_admin_emoji(emoji: str, emoji_id: str, added_by: int) -> bool:
    try:
        with db() as c:
            r = c.execute(
                "INSERT OR IGNORE INTO admin_emoji_pool(emoji,emoji_id,added_by,added_at) "
                "VALUES(?,?,?,?)",
                (emoji, emoji_id, int(added_by), now_ist().isoformat()),
            )
            return r.rowcount > 0
    except Exception:
        return False


def clear_admin_emoji() -> None:
    with db() as c:
        c.execute("DELETE FROM admin_emoji_pool")


def apply_admin_emoji_to_text(text: str) -> str:
    """Apply admin emoji pool to admin panel text (optional)."""
    if not text or not isinstance(text, str):
        return text or ""
    pool = list_admin_emoji()
    if not pool:
        return text
    out = text
    for r in pool:
        emoji = r["emoji"]
        cid = r["emoji_id"]
        if f'<tg-emoji emoji-id="{cid}">' in out:
            continue
        out = out.replace(emoji, f'<tg-emoji emoji-id="{cid}">{emoji}</tg-emoji>')
    return out


