async def admin_emoji_pending_text(update, context):
    msg = update.message
    if not msg or not msg.from_user or not msg.text:
        return
    st = PENDING.get(msg.from_user.id)
    if not st or st.get("action") != "admin_emoji_add":
        return
    if not is_main_admin(msg.from_user.id):
        PENDING.pop(msg.from_user.id, None); return
    import re as _re
    pairs = []
    for line in msg.text.split("\n"):
        line = line.strip()
        if not line:
            continue
        m = _re.match(r'^(\S+)\s*[—\-:]+\s*(\d{5,30})\s*$', line)
        if m:
            pairs.append((m.group(1), m.group(2)))
            continue
        m = _re.match(r'^(\d{5,30})\s+\[(.+?)\]\s*$', line)
        if m:
            pairs.append((m.group(2), m.group(1)))
            continue
        m = _re.match(r'^(\d{5,30})\s+(\S+)\s*$', line)
        if m:
            pairs.append((m.group(2), m.group(1)))
    added = 0
    for e, cid in pairs:
        if add_admin_emoji(e, cid, msg.from_user.id):
            added += 1
    PENDING.pop(msg.from_user.id, None)
    try:
        await msg.reply_text(
            f'<tg-emoji emoji-id="6104659630254726636">✅</tg-emoji> '
            f'<b>Admin emoji added</b>\n\n'
            f'<blockquote>Parsed: {len(pairs)}\nAdded: {added}\nTotal: {len(list_admin_emoji())}</blockquote>',
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([
                [styled_button("🎛 Admin Emoji", "a:admin_emoji", style="primary")],
            ]),
        )
    except Exception:
        pass


