def _is_caring_trigger(text: str) -> bool:
    if not text:
        return False
    t = " " + str(text).lower().strip() + " "
    t = t.replace("-", " ").replace("_", " ")
    for kw in _CARING_KW:
        if kw in t:
            return True
    return False


def _is_coding_trigger(text: str) -> bool:
    if not text:
        return False
    t = text.lower()
    return any(k in t for k in _CODING_KW)


def _is_learn_trigger(text: str) -> bool:
    if not text:
        return False
    t = text.lower()
    # Only trigger if a question-mark or learn-intent word is present
    if "?" in text:
        return True
    return any(k in t for k in _LEARN_KW)


