    label = labels.get(mode, mode)
    state = "ON" if on else "OFF"
    try:
        await bot.send_message(
            int(uid),
            f"<tg-emoji emoji-id=\"6120688813275616207\">✅</tg-emoji> "
            f"<b>{label} mode:</b> {state}",
            parse_mode=ParseMode.HTML,
        )
    except Exception:
        pass


