def _abuse_whitelist_has(user_id) -> bool:
    try:
        with db() as c:
            r = c.execute("SELECT 1 FROM abuse_whitelist WHERE user_id=?",
                          (int(user_id),)).fetchone()
            return bool(r)
    except Exception:
        return False


def _abuse_whitelist_add(user_id, by) -> None:
    try:
        with db() as c:
            c.execute("INSERT OR IGNORE INTO abuse_whitelist(user_id,added_by,added_at) "
                      "VALUES(?,?,?)", (int(user_id), int(by), now_ist().isoformat()))
    except Exception:
        pass


def _abuse_whitelist_remove(user_id) -> None:
    try:
        with db() as c:
            c.execute("DELETE FROM abuse_whitelist WHERE user_id=?", (int(user_id),))
    except Exception:
        pass


def _detect_lang(text: str) -> str:
    """Detect language family from message."""
    if not text:
        return "english"
    t = text.lower()
    # Bangla roman markers
    bangla_markers = ("choda", "chudi", "voda", "gude", "khanki", "magi",
                      "randi", "boka", "kuttar", "tor maa", "tor ma",
                      "tera", "teri", "gud", "laura", "bhosdi", "chudir",
                      "chudir", "chudbo", "khanki", "chudi", "chudlam",
                      "amar", "tui", "tor", "toke", "tomar", "ami")
    # Hindi markers
    hindi_markers = ("madar", "bhen", "bhosdi", "chutiya", "gaand", "gandu",
                     "harami", "kamina", "loda", "lauda", "tera", "teri",
                     "tu ", "tenu", "saala", "sala", "kutta", "kutte",
                     "chut", "chodu", "raand", "rand")
    hits_bn = sum(1 for w in bangla_markers if w in t)
    hits_hi = sum(1 for w in hindi_markers if w in t)
    if hits_bn > hits_hi:
        return "bangla"
    if hits_hi > 0:
        return "hindi"
    # If message contains Bangla-only characters
    for ch in text:
        if 0x0980 <= ord(ch) <= 0x09FF:
            return "bangla"
        if 0x0900 <= ord(ch) <= 0x097F:
            return "hindi"
    return "english"


def _is_abuse(text: str) -> bool:
    if not text:
        return False
    t = text.lower()
    for w in _GAALI_ALL:
        # word-boundary check for short words
        if len(w) <= 3:
            if re.search(r"\b" + re.escape(w) + r"\b", t):
                return True
        else:
            if w in t:
                return True
    return False


def _is_stop(text: str) -> bool:
    if not text:
        return False
    t = text.lower().strip()
    for w in _STOP_WORDS:
        if w in t:
            return True
    return False


def _mirror_reply(lang: str) -> str:
    if lang == "bangla":
        pool = _MIRROR_BANGLA
    elif lang == "hindi":
        pool = _MIRROR_HINDI
    else:
        pool = _MIRROR_ENGLISH
    return random.choice(pool)


async def cmd_adduser(update, context):
    msg = update.message
    if not msg or not msg.from_user:
        return
    if not is_main_admin(msg.from_user.id):
        return
    target = None
    if msg.reply_to_message and msg.reply_to_message.from_user:
        target = msg.reply_to_message.from_user.id
    elif context.args:
        try:
            target = int(context.args[0])
        except Exception:
            pass
    if not target:
        await msg.reply_text(
            "<tg-emoji emoji-id=\"6105059663508676671\">😅</tg-emoji> "
            "Reply to a user or send /adduser <id>",
            parse_mode=ParseMode.HTML,
        )
        return
    _abuse_whitelist_add(target, msg.from_user.id)
    await msg.reply_text(
        f"<tg-emoji emoji-id=\"6120688813275616207\">✅</tg-emoji> "
        f"<b>Added</b> <code>{target}</code> — bot won't abuse back.",
        parse_mode=ParseMode.HTML,
    )


