async def cmd_list_users(update, context):
    msg = update.message
    if not msg or not msg.from_user:
        return
    if not is_main_admin(msg.from_user.id):
        return
    with db() as c:
        rows = c.execute("SELECT user_id, added_at FROM abuse_whitelist "
                         "ORDER BY added_at DESC LIMIT 50").fetchall()
    if not rows:
        await msg.reply_text("🧭 No whitelist entries.")
        return
    lines = ["<b>Whitelist:</b>"]
    for r in rows:
        lines.append(f"• <code>{r['user_id']}</code>")
    await msg.reply_text("\n".join(lines), parse_mode=ParseMode.HTML)


async def abuse_mirror_handler(update, context):
    """Group message — mirror abuse, respect whitelist + owner."""
    msg = update.message
    if not msg or not msg.text or not msg.from_user:
        return
    if msg.chat.type not in (ChatType.GROUP, ChatType.SUPERGROUP):
        return
    # skip commands
    if msg.text.startswith("/"):
        return
    user = msg.from_user
    # Owner never abused
    if is_main_admin(user.id):
        return
    # Whitelist never abused
    if _abuse_whitelist_has(user.id):
        return
    text = msg.text
    # Abuse detected → mirror
    if _is_abuse(text):
        lang = _detect_lang(text)
        reply = _mirror_reply(lang)
        try:
            await msg.reply_text(reply)
        except Exception:
            pass
        return
    # Stop requested → bot stops + tells abuser to stop
    if _is_stop(text):
        # Only respond if bot was recently abused in this chat
        try:
            await msg.reply_text(
                "Ok stop it. Tumi o band koro. 🫡",
            )
        except Exception:
            pass
        return


