#              FILE / IMAGE / VIDEO GENERATION (any user)
# ============================================================
async def cmd_gen_file(update, context):
    """/file <description> — any user. AI writes the file, sends as document."""
    msg = update.message
    if not msg or not msg.from_user:
        return
    prompt = " ".join(context.args) if context.args else ""
    if not prompt:
        await msg.reply_text(
            '<tg-emoji emoji-id="6105098880855055646">😛</tg-emoji> '
            '<b>Usage:</b> <code>/file &lt;description&gt;</code>',
            parse_mode=ParseMode.HTML,
        )
        return
    status = await msg.reply_text(
        '<tg-emoji emoji-id="6105189070873305867">☁️</tg-emoji> '
        'Generating file...',
        parse_mode=ParseMode.HTML,
    )
    try:
        c = _get_groq()
        if not c:
            await status.edit_text("😅 AI offline — admin check kare.")
            return
        sys = (
            "You are a code/file generator. Output ONLY the raw file content. "
            "No markdown fences. No explanation. No intro. No trailing comments. "
            "Just the file. Match the file type to the request (python, js, html, "
            "yaml, json, csv, txt, md, bash, etc). Complete and runnable."
        )
        resp = await c.chat.completions.create(
            model="openai/gpt-oss-120b",
            messages=[{"role": "system", "content": sys},
                      {"role": "user", "content": prompt}],
            max_tokens=3500, temperature=0.7,
        )
        content = (resp.choices[0].message.content or "").strip()
        content = re.sub(r"^```[a-zA-Z0-9_+-]*\n", "", content)
        content = re.sub(r"\n```$", "", content)
        # Determine extension
        low = prompt.lower()
        ext = "txt"
        for k, e in [
            ("python", "py"), ("py ", "py"), (".py", "py"),
            ("javascript", "js"), (" js ", "js"),
            ("html", "html"), ("css", "css"), ("json", "json"),
            ("yaml", "yaml"), ("yml", "yaml"), ("xml", "xml"),
            ("csv", "csv"), ("sql", "sql"), ("bash", "sh"),
            ("shell", "sh"), ("c++", "cpp"), ("cpp", "cpp"),
            ("c#", "cs"), ("java", "java"), ("rust", "rs"),
            ("go ", "go"), ("markdown", "md"), ("readme", "md"),
            ("dockerfile", "dockerfile"), ("ini", "ini"), ("cfg", "cfg"),
        ]:
            if k in low:
                ext = e
                break
        fname = f"generated.{ext}"
        import io as _io
        buf = _io.BytesIO(content.encode("utf-8"))
        buf.name = fname
        await status.delete()
        await msg.reply_document(
            buf,
            filename=fname,
            caption=(
                '<tg-emoji emoji-id="6104715731117547405">💎</tg-emoji> '
                f'<b>{html_escape(fname)}</b>'
            ),
            parse_mode=ParseMode.HTML,
        )
    except Exception as e:
        log.error("[gen_file] %s", e)
        try:
            await status.edit_text(
                f'<tg-emoji emoji-id="6105059663508676671">😅</tg-emoji> '
                f'File gen failed: <code>{str(e)[:100]}</code>',
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass


