async def cmd_gen_video(update, context):
    """/video <prompt> — public. Generates short AI video via Pollinations."""
    msg = update.message
    if not msg or not msg.from_user:
        return
    prompt = " ".join(context.args) if context.args else ""
    if not prompt:
        await msg.reply_text(
            '<tg-emoji emoji-id="6105098880855055646">😛</tg-emoji> '
            '<b>Usage:</b> <code>/video &lt;description&gt;</code>',
            parse_mode=ParseMode.HTML,
        )
        return
    status = await msg.reply_text(
        '<tg-emoji emoji-id="6105189070873305867">☁️</tg-emoji> '
        'Generating video... (30-60s)',
        parse_mode=ParseMode.HTML,
    )
    try:
        import urllib.parse
        enc = urllib.parse.quote(prompt)
        # Pollinations video endpoint
        url = f"https://video.pollinations.ai/prompt/{enc}?nologo=true&model=flux"
        async with aiohttp.ClientSession() as s:
            async with s.get(url, timeout=aiohttp.ClientTimeout(total=180)) as r:
                if r.status != 200:
                    raise Exception(f"HTTP {r.status}")
                data = await r.read()
        await status.delete()
        import io as _io
        buf = _io.BytesIO(data)
        buf.name = "generated.mp4"
        await msg.reply_video(
            buf,
            filename="generated.mp4",
            caption=(
                '<tg-emoji emoji-id="6147464060305676048">🎨</tg-emoji> '
                f'<b>{html_escape(prompt[:200])}</b>'
            ),
            parse_mode=ParseMode.HTML,
        )
    except Exception as e:
        log.error("[gen_video] %s", e)
        try:
            await status.edit_text(
                f'<tg-emoji emoji-id="6105059663508676671">😅</tg-emoji> '
                f'Video gen failed: <code>{str(e)[:120]}</code>',
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass


# ============================================================
#              NSFW PROVIDER ROUTER
# ============================================================
async def _openrouter_reply(sys_prompt: str, msgs: list, mt: int, tp: float) -> str:
    """OpenRouter — uncensored model. OpenAI-compatible API."""
    if not OPENROUTER_API_KEY:
        return ""
    try:
        payload = {
            "model": OPENROUTER_NSFW_MODEL,
            "messages": [{"role": "system", "content": sys_prompt}] + msgs,
            "max_tokens": mt,
            "temperature": tp,
        }
        headers = {
            "Authorization": f"Bearer {OPENROUTER_API_KEY}",
            "Content-Type": "application/json",
            "HTTP-Referer": "https://t.me/RehanNexusBot",
            "X-Title": "Rehan Nexus",
        }
        async with aiohttp.ClientSession() as s:
            async with s.post("https://openrouter.ai/api/v1/chat/completions",
                              json=payload, headers=headers,
                              timeout=aiohttp.ClientTimeout(total=60)) as r:
                if r.status != 200:
                    body = await r.text()
                    log.warning("[OPENROUTER] HTTP %s: %s", r.status, body[:200])
                    return ""
                data = await r.json()
                return (data["choices"][0]["message"]["content"] or "").strip()
    except Exception as e:
        log.warning("[OPENROUTER] %s", e)
        return ""


async def _ollama_reply(sys_prompt: str, msgs: list, mt: int, tp: float) -> str:
    """Local Ollama — /api/chat."""
    if not OLLAMA_HOST:
        return ""
    try:
        payload = {
            "model": OLLAMA_NSFW_MODEL,
            "messages": [{"role": "system", "content": sys_prompt}] + msgs,
            "stream": False,
            "options": {"num_predict": mt, "temperature": tp},
        }
        async with aiohttp.ClientSession() as s:
            async with s.post(f"{OLLAMA_HOST.rstrip('/')}/api/chat",
                              json=payload,
                              timeout=aiohttp.ClientTimeout(total=120)) as r:
                if r.status != 200:
                    return ""
                data = await r.json()
                return (data.get("message", {}).get("content", "") or "").strip()
    except Exception as e:
        log.warning("[OLLAMA] %s", e)
        return ""


async def _nsfw_reply(sys_prompt: str, msgs: list, mt: int = 900, tp: float = 1.15) -> str:
    """Try OpenRouter first, then Ollama. Return '' if both fail (fallback to Groq)."""
    out = await _openrouter_reply(sys_prompt, msgs, mt, tp)
    if out:
        return out
    out = await _ollama_reply(sys_prompt, msgs, mt, tp)
    if out:
        return out
    return ""


