def main() -> None:
    """Start the bot and log startup failures instead of losing their context."""
    log.info("[STARTUP] Starting %s", BOT_NAME)
    acquire_instance_lock()
    conflicts = 0
    while True:
        try:
            # Build inside the protected block: DB/schema/app-construction errors
            # previously escaped before the startup error handler could log them.
            app = build_app()
            app.run_polling(
                allowed_updates=Update.ALL_TYPES,
                drop_pending_updates=False,
            )
            break
        except Conflict as e:
            conflicts += 1
            log.exception("[CONFLICT] attempt %s/3", conflicts)
            if conflicts >= 3:
                log.error("[STOPPED] Duplicate instance detected after 3 attempts.")
                break
            time.sleep(min(30, 5 * conflicts))
        except (TimedOut, NetworkError) as e:
            log.warning("[NETWORK] Telegram connection problem: %s", e)
            time.sleep(5)
        except TelegramError as e:
            log.exception("[TELEGRAM] polling/startup error: %s", e)
            time.sleep(5)
        except KeyboardInterrupt:
            log.info("[SHUTDOWN] KeyboardInterrupt")
            break
        except SystemExit:
            # Keep intentional config/version/instance-lock messages intact.
            raise
        except Exception:
            log.exception("[STARTUP/RUNTIME] Fatal error; bot stopped.")
            break


if __name__ == "__main__":
    main()
    